import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum LeaveType {
  FULL_DAY = 'FULL_DAY',
  HALF_DAY = 'HALF_DAY',
  HOLIDAY = 'HOLIDAY', // Company Holiday
  OTHER = 'OTHER', // Paternity, Sick, etc.
  WORK = 'WORK' // Standard work day (clears selection)
}

export interface TeamMember {
  id: string;
  name: string;
}

export interface LeaveRecord {
  // Key format: "userId_YYYY-MM-DD" or "GLOBAL_YYYY-MM-DD" for holidays
  // However, simpler to store map: Record<string, LeaveType> where key is compound
  [key: string]: LeaveType;
}

export interface AppState {
  team: TeamMember[];
  leaves: LeaveRecord;
  year: number;
}

import { LeaveType } from './types';

export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

export const DAYS_OF_WEEK = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

export const LEAVE_COLORS: Record<LeaveType, string> = {
  [LeaveType.WORK]: 'bg-white hover:bg-gray-50',
  [LeaveType.FULL_DAY]: 'bg-red-500 text-white',
  [LeaveType.HALF_DAY]: 'bg-[linear-gradient(135deg,_#ef4444_50%,_#ffffff_50%)]', // Diagonal Red/White
  [LeaveType.HOLIDAY]: 'bg-yellow-400',
  [LeaveType.OTHER]: 'bg-blue-400 text-white',
};

export const LEAVE_LABELS: Record<LeaveType, string> = {
  [LeaveType.WORK]: 'Clear / Work Day',
  [LeaveType.FULL_DAY]: 'Vacation (Full)',
  [LeaveType.HALF_DAY]: 'Vacation (Half)',
  [LeaveType.HOLIDAY]: 'Company Holiday',
  [LeaveType.OTHER]: 'Paternity / Other',
};

export const getDaysInMonth = (year: number, monthIndex: number): number => {
  return new Date(year, monthIndex + 1, 0).getDate();
};

export const getDayOfWeekIndex = (year: number, monthIndex: number, day: number): number => {
  return new Date(year, monthIndex, day).getDay();
};

export const isWeekend = (year: number, monthIndex: number, day: number): boolean => {
  const dayIndex = getDayOfWeekIndex(year, monthIndex, day);
  return dayIndex === 0 || dayIndex === 6; // 0 is Sunday, 6 is Saturday
};

export const generateLeaveKey = (userId: string, year: number, monthIndex: number, day: number): string => {
  // Pad month and day
  const m = (monthIndex + 1).toString().padStart(2, '0');
  const d = day.toString().padStart(2, '0');
  return `${userId}_${year}-${m}-${d}`;
};

export const generateGlobalKey = (year: number, monthIndex: number, day: number): string => {
  const m = (monthIndex + 1).toString().padStart(2, '0');
  const d = day.toString().padStart(2, '0');
  return `GLOBAL_${year}-${m}-${d}`;
};

import React from 'react';
