import React from 'react';
import { TeamMember, LeaveType, LeaveRecord } from '../types';
import { MONTHS, DAYS_OF_WEEK, LEAVE_COLORS } from '../constants';
import { getDaysInMonth, isWeekend, getDayOfWeekIndex, generateLeaveKey, generateGlobalKey } from '../utils';

interface Props {
  year: number;
  monthIndex: number;
  team: TeamMember[];
  leaves: LeaveRecord;
  currentTool: LeaveType;
  onToggleLeave: (key: string, type: LeaveType) => void;
}

export const MonthGrid: React.FC<Props> = ({ 
  year, 
  monthIndex, 
  team, 
  leaves, 
  currentTool,
  onToggleLeave 
}) => {
  const daysInMonth = getDaysInMonth(year, monthIndex);
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  // Helper to safely get status including global overrides
  const getStatus = (userId: string, day: number) => {
    // 1. Check specific user leave
    const userKey = generateLeaveKey(userId, year, monthIndex, day);
    const userStatus = leaves[userKey];

    // 2. Check global holiday (overrides work, but specific leaves might take precedence depending on rule. Usually holiday overrides all).
    const globalKey = generateGlobalKey(year, monthIndex, day);
    const isGlobalHoliday = leaves[globalKey] === LeaveType.HOLIDAY;

    if (isGlobalHoliday) return LeaveType.HOLIDAY;
    return userStatus || LeaveType.WORK;
  };

  const isGlobalHoliday = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    return leaves[key] === LeaveType.HOLIDAY;
  };

  const handleDayHeaderClick = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    // Toggle global holiday
    const current = leaves[key];
    onToggleLeave(key, current === LeaveType.HOLIDAY ? LeaveType.WORK : LeaveType.HOLIDAY);
  };

  return (
    <div className="mb-8 bg-white shadow-sm border border-gray-200 rounded-lg overflow-hidden">
      {/* Month Header */}
      <div className="bg-gray-100 px-4 py-2 border-b border-gray-200 font-bold text-gray-700 uppercase tracking-wider">
        {MONTHS[monthIndex]}
      </div>

      <div className="overflow-x-auto hide-scrollbar">
        <div className="inline-block min-w-full">
          {/* Header Row (Days) */}
          <div className="flex border-b border-gray-200">
            {/* Name Column Header */}
            <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-gray-50 border-r border-gray-200 p-2 font-medium text-xs text-gray-500">
              Employee
            </div>

            {/* Day Columns */}
            {daysArray.map(day => {
               const isWE = isWeekend(year, monthIndex, day);
               const isHoliday = isGlobalHoliday(day);
               const dayName = DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)];

               return (
                <div 
                  key={day} 
                  onClick={() => handleDayHeaderClick(day)}
                  className={`
                    w-8 flex-shrink-0 text-center border-r border-gray-100 last:border-r-0 cursor-pointer hover:bg-gray-200 transition-colors
                    ${isWE ? 'bg-gray-200' : isHoliday ? 'bg-yellow-100' : 'bg-white'}
                  `}
                  title="Click to toggle Global Holiday"
                >
                  <div className={`text-xs font-bold p-1 ${isHoliday ? 'text-yellow-700' : isWE ? 'text-gray-500' : 'text-gray-700'}`}>{day}</div>
                  <div className="text-[10px] text-gray-400 font-medium pb-1">{dayName}</div>
                </div>
              );
            })}
          </div>

          {/* User Rows */}
          {team.map(member => (
            <div key={member.id} className="flex border-b border-gray-100 last:border-b-0 hover:bg-gray-50">
              {/* Name Cell */}
              <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-white border-r border-gray-200 p-2 flex items-center">
                <span className="text-sm font-medium text-gray-800 truncate" title={member.name}>
                  {member.name}
                </span>
              </div>

              {/* Day Cells */}
              {daysArray.map(day => {
                const status = getStatus(member.id, day);
                const isWE = isWeekend(year, monthIndex, day);
                // Background priority: Status Color > Weekend Gray > White
                const bgClass = status !== LeaveType.WORK 
                  ? LEAVE_COLORS[status] 
                  : isWE 
                    ? 'bg-gray-200' 
                    : 'bg-white';

                return (
                  <div
                    key={day}
                    className={`
                      w-8 h-10 flex-shrink-0 border-r border-gray-100 last:border-r-0 cursor-pointer
                      transition-colors duration-75 relative group
                      ${bgClass}
                    `}
                    onClick={() => {
                        const key = generateLeaveKey(member.id, year, monthIndex, day);
                        onToggleLeave(key, currentTool);
                    }}
                  >
                    {/* Hover effect to show cell interaction */}
                    <div className="absolute inset-0 bg-black opacity-0 group-hover:opacity-5 pointer-events-none"></div>
                  </div>
                );
              })}
            </div>
          ))}

          {team.length === 0 && (
             <div className="p-8 text-center text-gray-400 italic">
                No team members added yet. Use the "Manage Team" button.
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { LeaveType, TeamMember, LeaveRecord } from './types';
import { MONTHS } from './constants';
import { ChevronLeft, ChevronRight, Calendar } from 'lucide-react';

const STORAGE_KEY = 'vacation_planner_v1';

// Initial Data
const INITIAL_TEAM: TeamMember[] = [
  { id: '1', name: 'Diego' },
  { id: '2', name: 'Lukas' },
  { id: '3', name: 'Pablo' },
];

const App: React.FC = () => {
  // State
  const [year, setYear] = useState(2026);
  const [team, setTeam] = useState<TeamMember[]>(INITIAL_TEAM);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [currentTool, setCurrentTool] = useState<LeaveType>(LeaveType.FULL_DAY);
  const [isClient, setIsClient] = useState(false);

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.team) setTeam(parsed.team);
        if (parsed.leaves) setLeaves(parsed.leaves);
        if (parsed.year) setYear(parsed.year);
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }
    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ team, leaves, year }));
  }, [team, leaves, year, isClient]);

  // Handlers
  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      id: Date.now().toString(), // Simple ID generation
      name,
    };
    setTeam([...team, newMember]);
  };

  const handleRemoveMember = (id: string) => {
    if (confirm('Are you sure? This will remove the user but keep their leave records in history.')) {
      setTeam(team.filter(m => m.id !== id));
    }
  };

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Calendar className="w-6 h-6 text-blue-600" />
            <h1 className="text-xl font-bold text-gray-900 tracking-tight">Team Planner</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center bg-gray-100 rounded-lg p-1">
              <button 
                onClick={() => setYear(y => y - 1)}
                className="p-1 hover:bg-white rounded-md shadow-sm transition-all text-gray-600"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <span className="mx-4 font-bold text-lg w-12 text-center">{year}</span>
              <button 
                onClick={() => setYear(y => y + 1)}
                className="p-1 hover:bg-white rounded-md shadow-sm transition-all text-gray-600"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
           {/* Controls */}
           <div className="flex-1">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Team Manager */}
           <div>
             <TeamManager 
                team={team} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
             />
           </div>
        </div>

        {/* Calendar Grids */}
        <div className="space-y-6 mt-6">
          {MONTHS.map((month, index) => (
            <MonthGrid
              key={month}
              year={year}
              monthIndex={index}
              team={team}
              leaves={leaves}
              currentTool={currentTool}
              onToggleLeave={handleToggleLeave}
            />
          ))}
        </div>

        <div className="mt-12 text-center text-sm text-gray-400">
           <p>Data is saved automatically to your browser.</p>
           <button 
             onClick={() => {
                if(confirm("Clear all data?")) {
                    localStorage.removeItem(STORAGE_KEY);
                    window.location.reload();
                }
             }}
             className="mt-2 text-red-400 hover:text-red-600 underline"
            >
                Reset Application Data
            </button>
        </div>

      </main>
    </div>
  );
};

export default App;

