                        <div className="w-9 h-9 rounded-full bg-gradient-to-br from-blue-100 to-blue-200 text-blue-700 flex items-center justify-center text-sm font-bold shadow-inner">
                          {member.name.substring(0, 2).toUpperCase()}
                        </div>
                        <span className="font-semibold text-gray-700">{member.name}</span>
                      </div>
                      <button
                        onClick={() => onRemoveMember(member.id)}
