interface Props {
  team: TeamMember[];
  onAddMember: (name: string) => void;
  onRemoveMember: (id: string) => void;
  onReorderMembers: (fromIndex: number, toIndex: number) => void;
}

export const TeamManager: React.FC<Props> = ({ team, onAddMember, onRemoveMember, onReorderMembers }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [newName, setNewName] = useState('');
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newName.trim()) {
      onAddMember(newName.trim());
      setNewName('');
      // Keep focus on input for rapid entry
      inputRef.current?.focus();
    }
  };

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    // Needed for Firefox
    e.dataTransfer.effectAllowed = 'move';
    // Optional: make the drag image less opaque immediately if needed, 
    // but usually default browser behavior is fine or handled via CSS on the original element.
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, dropIndex: number) => {
    e.preventDefault();
    if (draggedIndex !== null && draggedIndex !== dropIndex) {
      onReorderMembers(draggedIndex, dropIndex);
    }
    setDraggedIndex(null);
  };

  return (
    <>
      <button
        onClick={() => setIsOpen(true)}
        type="button"
        className="flex items-center gap-2 bg-white text-gray-700 hover:text-blue-600 hover:border-blue-300 border border-gray-200 font-medium px-4 py-3 rounded-lg shadow-sm transition-all h-full"
