              <h3 className="font-bold text-lg text-gray-800 flex items-center gap-2">
                <Users className="w-5 h-5 text-blue-600" />
                Team Members
              </h3>
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="text-gray-400 hover:text-gray-600 transition-colors p-2 hover:bg-gray-200 rounded-full"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto p-6">
              <div className="space-y-2">
                {team.length === 0 ? (
                   <div className="text-center py-8">
                     <div className="bg-gray-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-3">
                       <Users className="w-8 h-8 text-gray-400" />
                     </div>
                     <p className="text-gray-500 font-medium">No team members yet</p>
                     <p className="text-gray-400 text-sm">Add your first colleague below</p>
                   </div>
                ) : (
                  team.map((member, index) => (
                    <div
                      key={member.id}
                      draggable
                      onDragStart={(e) => handleDragStart(e, index)}
                      onDragOver={(e) => handleDragOver(e, index)}
                      onDrop={(e) => handleDrop(e, index)}
                      className={`
                        flex items-center justify-between p-3 bg-white border rounded-lg shadow-sm group transition-all
                        ${draggedIndex === index ? 'opacity-50 border-dashed border-blue-400' : 'border-gray-100 hover:border-blue-200 hover:shadow-md'}
                      `}
                    >
                      <div className="flex items-center gap-3">
                        <div className="cursor-grab active:cursor-grabbing text-gray-300 hover:text-gray-500 p-1">
                          <GripVertical className="w-4 h-4" />
                        </div>
                        <div className="w-9 h-9 rounded-full bg-gradient-to-br from-blue-100 to-blue-200 text-blue-700 flex items-center justify-center text-sm font-bold shadow-inner">
                          {member.name.substring(0, 2).toUpperCase()}
                        </div>
                        <span className="font-semibold text-gray-700">{member.name}</span>
                      </div>
                      <button
                        type="button"
                        onClick={() => onRemoveMember(member.id)}
                        className="text-gray-400 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-colors border border-transparent hover:border-red-100"
                        title="Remove user"
                        aria-label={`Remove ${member.name}`}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Footer / Add Form */}
            <div className="p-4 bg-gray-50 border-t border-gray-200">
              <form onSubmit={handleSubmit} className="flex gap-2">
                <input
                  ref={inputRef}
                  type="text"
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  placeholder="Enter name..."
                  className="flex-1 px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm shadow-sm"
                  autoFocus
                />
                <button
