import { Legend } from './components/Legend';
import { LeaveType, TeamMember, LeaveRecord } from './types';
import { MONTHS } from './constants';
import { ChevronLeft, ChevronRight, Calendar, RotateCcw } from 'lucide-react';

// Updated storage key to reset data for version 2 (ensures clean slate for 2026)
const STORAGE_KEY = 'vacation_planner_v2';

// Initial Data
const INITIAL_TEAM: TeamMember[] = [
  { id: '1', name: 'Diego' },
  { id: '2', name: 'Lukas' },
  { id: '3', name: 'Pablo' },
];

const App: React.FC = () => {
  // State
  // Default to 2026 as requested
  const [year, setYear] = useState(2026);
  const [team, setTeam] = useState<TeamMember[]>(INITIAL_TEAM);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [currentTool, setCurrentTool] = useState<LeaveType>(LeaveType.FULL_DAY);
  const [isClient, setIsClient] = useState(false);

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.team) setTeam(parsed.team);
        if (parsed.leaves) setLeaves(parsed.leaves);
        // Ensure we respect the saved year if it exists, otherwise default is 2026
        if (parsed.year) setYear(parsed.year);
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }
    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ team, leaves, year }));
  }, [team, leaves, year, isClient]);

  // Handlers
  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      // Use crypto.randomUUID for better uniqueness if available, else fallback
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };
    setTeam([...team, newMember]);
  };

  const handleRemoveMember = (id: string) => {
    // Removed window.confirm as it can be problematic in some UI flows.
    // In a real app, we might use a custom modal or undo toast.
    setTeam(prevTeam => prevTeam.filter(m => m.id !== id));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeam(prevTeam => {
      const updatedTeam = [...prevTeam];
      const [movedMember] = updatedTeam.splice(fromIndex, 1);
      updatedTeam.splice(toIndex, 0, movedMember);
      return updatedTeam;
    });
  };

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Calendar className="w-6 h-6 text-blue-600" />
            <h1 className="text-xl font-bold text-gray-900 tracking-tight">Team Planner</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center bg-gray-100 rounded-lg p-1 border border-gray-200">
              <button 
                onClick={() => setYear(y => y - 1)}
                className="p-1 hover:bg-white rounded-md shadow-sm transition-all text-gray-600 hover:text-blue-600"
                aria-label="Previous Year"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <span className="mx-4 font-bold text-lg w-16 text-center tabular-nums text-gray-800">{year}</span>
              <button 
                onClick={() => setYear(y => y + 1)}
                className="p-1 hover:bg-white rounded-md shadow-sm transition-all text-gray-600 hover:text-blue-600"
                aria-label="Next Year"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        <div className="flex flex-col lg:flex-row lg:items-start justify-between gap-4">
           {/* Controls */}
           <div className="flex-1">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Team Manager & Legend */}
           <div className="flex flex-col sm:flex-row gap-3">
             <TeamManager 
                team={team} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
                onReorderMembers={handleReorderMembers}
             />
             <Legend />
           </div>
        </div>

        {/* Legend / Info */}
        <div className="mt-4 mb-2 flex items-center gap-2 text-sm text-gray-500 bg-blue-50 p-2 rounded border border-blue-100">
           <span className="font-semibold text-blue-700">Tip:</span> 
           Click on a day number (e.g., "01") in the header to toggle a global company holiday for that day.
        </div>

        {/* Calendar Grids */}
        <div className="space-y-8 mt-6">
          {MONTHS.map((month, index) => (
            <MonthGrid
              key={month}
              year={year}
              monthIndex={index}
              team={team}
              leaves={leaves}
              currentTool={currentTool}
              onToggleLeave={handleToggleLeave}
            />
          ))}
        </div>

        <div className="mt-16 pb-8 border-t border-gray-200 pt-8 flex flex-col items-center">
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 text-gray-400 hover:text-red-500 transition-colors text-sm font-medium px-4 py-2 rounded-md hover:bg-red-50"
            >
                <RotateCcw className="w-4 h-4" />
                Reset Application Data
            </button>
            <p className="mt-2 text-xs text-gray-400">
              Data is stored locally in your browser.
            </p>
        </div>

      </main>
    </div>
  );
};

export default App;

