import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { Legend } from './components/Legend';
import { YearSelector } from './components/YearSelector';
import { ViewToggle } from './components/ViewToggle';
import { LeaveType, TeamMember, LeaveRecord, ViewMode } from './types';
import { MONTHS } from './constants';
import { Calendar, RotateCcw, ChevronLeft, ChevronRight } from 'lucide-react';

// Updated storage key to reset data for version 2 (ensures clean slate for 2026)
const STORAGE_KEY = 'vacation_planner_v2';

// Initial Data
const INITIAL_TEAM: TeamMember[] = [
  { id: '1', name: 'Diego' },
  { id: '2', name: 'Lukas' },
  { id: '3', name: 'Pablo' },
];

const App: React.FC = () => {
  // State
  // Default to 2026 as requested
  const [year, setYear] = useState(2026);
  const [team, setTeam] = useState<TeamMember[]>(INITIAL_TEAM);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [currentTool, setCurrentTool] = useState<LeaveType>(LeaveType.FULL_DAY);
  const [isClient, setIsClient] = useState(false);

  // View State
  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [activeMonthIndex, setActiveMonthIndex] = useState(new Date().getMonth());

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.team) setTeam(parsed.team);
        if (parsed.leaves) setLeaves(parsed.leaves);
        // Ensure we respect the saved year if it exists, otherwise default is 2026
        if (parsed.year) setYear(parsed.year);
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }
    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ team, leaves, year }));
  }, [team, leaves, year, isClient]);

  // Handlers
  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      // Use crypto.randomUUID for better uniqueness if available, else fallback
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };
    setTeam([...team, newMember]);
  };

  const handleRemoveMember = (id: string) => {
    setTeam(prevTeam => prevTeam.filter(m => m.id !== id));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeam(prevTeam => {
      const updatedTeam = [...prevTeam];
      const [movedMember] = updatedTeam.splice(fromIndex, 1);
      updatedTeam.splice(toIndex, 0, movedMember);
      return updatedTeam;
    });
  };

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  // Smart Navigation Logic
  const handlePrevMonth = () => {
    if (activeMonthIndex === 0) {
      setActiveMonthIndex(11);
      setYear(y => y - 1);
    } else {
      setActiveMonthIndex(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (activeMonthIndex === 11) {
      setActiveMonthIndex(0);
      setYear(y => y + 1);
    } else {
      setActiveMonthIndex(prev => prev + 1);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-1.5 rounded-lg text-white shadow-sm">
                <Calendar className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-gray-900 tracking-tight hidden sm:block">Team Planner</h1>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <ViewToggle viewMode={viewMode} onViewChange={setViewMode} />
            <div className="h-6 w-px bg-gray-200"></div>
            <YearSelector year={year} onYearChange={setYear} />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Top Controls Area */}
        <div className="flex flex-col xl:flex-row xl:items-start justify-between gap-6 mb-8">
           {/* Paint Toolbar */}
           <div className="flex-1 min-w-0">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Management Tools */}
           <div className="flex flex-col sm:flex-row gap-3 flex-shrink-0">
             <TeamManager 
                team={team} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
                onReorderMembers={handleReorderMembers}
             />
             <Legend />
           </div>
        </div>

        {/* Tip Box */}
        <div className="mb-6 flex items-center gap-3 text-sm text-blue-800 bg-blue-50/50 px-4 py-3 rounded-lg border border-blue-100">
           <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-0.5 rounded">TIP</span>
           <span>Click on a day number (e.g., "01") in the header to toggle a global company holiday.</span>
        </div>

        {/* Calendar View Area */}
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

          {viewMode === 'year' ? (
            /* YEAR VIEW: Vertical Stack */
            <div className="space-y-8">
              {MONTHS.map((month, index) => (
                <MonthGrid
                  key={`${year}-${month}`}
                  year={year}
                  monthIndex={index}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              ))}
            </div>
          ) : (
            /* MONTH VIEW: Single Focused Card */
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden min-h-[500px] flex flex-col">
              {/* Custom Navigation Header for Single Month View */}
              <div className="bg-white px-6 py-4 border-b border-gray-100 flex items-center justify-between sticky top-0 z-10">
                 <button 
                   onClick={handlePrevMonth}
                   className="p-2 hover:bg-gray-100 rounded-full text-gray-500 hover:text-blue-600 transition-colors"
                   title="Previous Month"
                 >
                   <ChevronLeft className="w-6 h-6" />
                 </button>

                 <div className="text-center">
                    <h2 className="text-2xl font-bold text-gray-800">{MONTHS[activeMonthIndex]}</h2>
                    <p className="text-sm text-gray-400 font-medium">{year}</p>
                 </div>

                 <button 
                   onClick={handleNextMonth}
                   className="p-2 hover:bg-gray-100 rounded-full text-gray-500 hover:text-blue-600 transition-colors"
                   title="Next Month"
                 >
                   <ChevronRight className="w-6 h-6" />
                 </button>
              </div>

              {/* Grid Container */}
              <div className="p-4 sm:p-6 bg-gray-50/50 flex-1">
                <MonthGrid
                  key={`${year}-${activeMonthIndex}`} // Force remount on change for animation/cleanness
                  year={year}
                  monthIndex={activeMonthIndex}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              </div>
            </div>
          )}

        </div>

        {/* Footer */}
        <div className="mt-16 pb-8 border-t border-gray-200 pt-8 flex flex-col items-center">
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 text-gray-400 hover:text-red-500 transition-colors text-sm font-medium px-4 py-2 rounded-md hover:bg-red-50"
            >
                <RotateCcw className="w-4 h-4" />
                Reset Application Data
            </button>
            <p className="mt-2 text-xs text-gray-400">
              Data is stored locally in your browser.
            </p>
        </div>

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { TeamMember, LeaveType, LeaveRecord } from '../types';
import { MONTHS, DAYS_OF_WEEK, LEAVE_COLORS, LEAVE_LABELS } from '../constants';
import { getDaysInMonth, isWeekend, getDayOfWeekIndex, generateLeaveKey, generateGlobalKey } from '../utils';

interface Props {
  year: number;
  monthIndex: number;
  team: TeamMember[];
  leaves: LeaveRecord;
  currentTool: LeaveType;
  onToggleLeave: (key: string, type: LeaveType) => void;
}

export const MonthGrid: React.FC<Props> = ({ 
  year, 
  monthIndex, 
  team, 
  leaves, 
  currentTool,
  onToggleLeave 
}) => {
  const daysInMonth = getDaysInMonth(year, monthIndex);
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  // Tooltip state - stores identifiers to allow reactive updates
  const [hoveredCell, setHoveredCell] = useState<{
    x: number;
    y: number;
    memberId: string;
    day: number;
  } | null>(null);

  // Helper to safely get status including global overrides
  const getStatus = (userId: string, day: number) => {
    // 1. Check specific user leave
    const userKey = generateLeaveKey(userId, year, monthIndex, day);
    const userStatus = leaves[userKey];

    // 2. Check global holiday (overrides work, but specific leaves might take precedence depending on rule. Usually holiday overrides all).
    const globalKey = generateGlobalKey(year, monthIndex, day);
    const isGlobalHoliday = leaves[globalKey] === LeaveType.HOLIDAY;

    if (isGlobalHoliday) return LeaveType.HOLIDAY;
    return userStatus || LeaveType.WORK;
  };

  const isGlobalHoliday = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    return leaves[key] === LeaveType.HOLIDAY;
  };

  const handleDayHeaderClick = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    // Toggle global holiday
    const current = leaves[key];
    onToggleLeave(key, current === LeaveType.HOLIDAY ? LeaveType.WORK : LeaveType.HOLIDAY);
  };

  const handleMouseEnter = (e: React.MouseEvent, memberId: string, day: number) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setHoveredCell({
        x: rect.left + rect.width / 2,
        y: rect.top,
        memberId,
        day
    });
  };

  return (
    <div className="mb-8 bg-white shadow-sm border border-gray-200 rounded-lg overflow-hidden">
      {/* Month Header */}
      <div className="bg-gray-100 px-4 py-2 border-b border-gray-200 font-bold text-gray-700 uppercase tracking-wider">
        {MONTHS[monthIndex]}
      </div>

      <div className="overflow-x-auto hide-scrollbar">
        <div className="inline-block min-w-full">
          {/* Header Row (Days) */}
          <div className="flex border-b border-gray-200">
            {/* Name Column Header */}
            <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-gray-50 border-r border-gray-200 p-2 font-medium text-xs text-gray-500">
              Employee
            </div>

            {/* Day Columns */}
            {daysArray.map(day => {
               const isWE = isWeekend(year, monthIndex, day);
               const isHoliday = isGlobalHoliday(day);
               const dayName = DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)];

               return (
                <div 
                  key={day} 
                  onClick={() => handleDayHeaderClick(day)}
                  className={`
                    w-8 flex-shrink-0 text-center border-r border-gray-100 last:border-r-0 cursor-pointer hover:bg-gray-200 transition-colors
                    ${isWE ? 'bg-gray-200' : isHoliday ? 'bg-yellow-100' : 'bg-white'}
                  `}
                  title="Click to toggle Global Holiday"
                >
                  <div className={`text-xs font-bold p-1 ${isHoliday ? 'text-yellow-700' : isWE ? 'text-gray-500' : 'text-gray-700'}`}>{day}</div>
                  <div className="text-[10px] text-gray-400 font-medium pb-1">{dayName}</div>
                </div>
              );
            })}
          </div>

          {/* User Rows */}
          {team.map(member => (
            <div key={member.id} className="flex border-b border-gray-100 last:border-b-0 hover:bg-gray-50">
              {/* Name Cell */}
              <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-white border-r border-gray-200 p-2 flex items-center">
                <span className="text-sm font-medium text-gray-800 truncate" title={member.name}>
                  {member.name}
                </span>
              </div>

              {/* Day Cells */}
              {daysArray.map(day => {
                const status = getStatus(member.id, day);
                const isWE = isWeekend(year, monthIndex, day);
                // Background priority: Status Color > Weekend Gray > White
                const bgClass = status !== LeaveType.WORK 
                  ? LEAVE_COLORS[status] 
                  : isWE 
                    ? 'bg-gray-200' 
                    : 'bg-white';

                return (
                  <div
                    key={day}
                    className={`
                      w-8 h-10 flex-shrink-0 border-r border-gray-100 last:border-r-0 cursor-pointer
                      transition-all duration-75 relative
                      ${bgClass}
                      hover:brightness-90
                    `}
                    onClick={() => {
                        const key = generateLeaveKey(member.id, year, monthIndex, day);
                        onToggleLeave(key, currentTool);
                    }}
                    onMouseEnter={(e) => handleMouseEnter(e, member.id, day)}
                    onMouseLeave={() => setHoveredCell(null)}
                    title={`${member.name}: ${LEAVE_LABELS[status]}`}
                  >
                  </div>
                );
              })}
            </div>
          ))}

          {team.length === 0 && (
             <div className="p-8 text-center text-gray-400 italic">
                No team members added yet. Use the "Manage Team" button.
             </div>
          )}
        </div>
      </div>

      {/* Reactive Tooltip */}
      {hoveredCell && (() => {
         const member = team.find(m => m.id === hoveredCell.memberId);
         if (!member) return null;

         const status = getStatus(hoveredCell.memberId, hoveredCell.day);
         const label = LEAVE_LABELS[status];

         return (
            <div 
                className="fixed z-50 px-3 py-2 bg-gray-900/95 text-white text-xs rounded shadow-xl pointer-events-none backdrop-blur-sm whitespace-nowrap"
                style={{ 
                    left: hoveredCell.x, 
                    top: hoveredCell.y, 
                    transform: 'translate(-50%, -125%)' // Shift up and center
                }}
            >
                <div className="font-bold mb-0.5">{member.name}</div>
                <div className="font-light text-gray-200">{label}</div>
                {/* Little arrow pointing down */}
                <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 translate-y-full border-4 border-transparent border-t-gray-900/95"></div>
            </div>
         );
      })()}
    </div>
  );
};

