import React, { useMemo } from 'react';
import { TeamMember, LeaveRecord, LeaveType } from '../types';
import { LEAVE_LABELS, LEAVE_COLORS } from '../constants';
import { Calendar, User, ArrowRight, Palmtree, Baby, CalendarDays } from 'lucide-react';

interface Props {
  team: TeamMember[];
  leaves: LeaveRecord;
}

interface LeaveRange {
  memberId: string;
  memberName: string;
  type: LeaveType;
  startDate: Date;
  endDate: Date;
  days: number;
}

export const UpcomingLeaves: React.FC<Props> = ({ team, leaves }) => {
  const upcomingRanges = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // 1. Convert leaves object to array of single day events
    const events: { date: Date; memberId: string; type: LeaveType }[] = [];

    Object.entries(leaves).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;
      if (key.startsWith('GLOBAL_')) return; // Skip global holidays for now to focus on team

      // Parse key: userId_YYYY-MM-DD
      // We assume date is always last 10 chars
      const dateStr = key.slice(-10);
      const memberId = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      const date = new Date(y, m - 1, d);

      if (date >= today) {
        events.push({ date, memberId, type });
      }
    });

    // 2. Sort by member, then by date
    events.sort((a, b) => {
      if (a.memberId !== b.memberId) return a.memberId.localeCompare(b.memberId);
      return a.date.getTime() - b.date.getTime();
    });

    // 3. Group consecutive days into ranges
    const ranges: LeaveRange[] = [];
    let currentRange: LeaveRange | null = null;

    events.forEach((event) => {
      const member = team.find(t => t.id === event.memberId);
      if (!member) return;

      // Check if this event continues the previous range
      const isConsecutive = currentRange && 
        currentRange.memberId === event.memberId &&
        currentRange.type === event.type &&
        event.date.getTime() === currentRange.endDate.getTime() + 86400000; // +1 day in ms

      if (isConsecutive && currentRange) {
        currentRange.endDate = event.date;
        currentRange.days += 1;
      } else {
        // Push previous range if exists
        if (currentRange) ranges.push(currentRange);

        // Start new range
        currentRange = {
          memberId: event.memberId,
          memberName: member.name,
          type: event.type,
          startDate: event.date,
          endDate: event.date,
          days: 1
        };
      }
    });

    // Don't forget the last one
    if (currentRange) ranges.push(currentRange);

    // 4. Final Sort: Chronological by start date
    return ranges.sort((a, b) => a.startDate.getTime() - b.startDate.getTime());
  }, [team, leaves]);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', weekday: 'short' });
  };

  const getIcon = (type: LeaveType) => {
    switch(type) {
        case LeaveType.FULL_DAY: return <Palmtree className="w-4 h-4" />;
        case LeaveType.HALF_DAY: return <div className="w-4 h-4 rounded-full bg-gradient-to-r from-red-400 to-white border border-gray-300"></div>;
        case LeaveType.HOLIDAY: return <CalendarDays className="w-4 h-4" />;
        case LeaveType.OTHER: return <Baby className="w-4 h-4" />;
        default: return <Calendar className="w-4 h-4" />;
    }
  };

  if (upcomingRanges.length === 0) {
    return (
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-12 text-center">
        <div className="bg-green-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
          <Calendar className="w-8 h-8 text-green-600" />
        </div>
        <h3 className="text-lg font-bold text-gray-900 mb-2">No upcoming leaves</h3>
        <p className="text-gray-500">Everyone is scheduled to be in the office for the foreseeable future.</p>
      </div>
    );
  }

  // Group by month for better readability
  const groupedByMonth = upcomingRanges.reduce((acc, range) => {
    const key = range.startDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    if (!acc[key]) acc[key] = [];
    acc[key].push(range);
    return acc;
  }, {} as Record<string, LeaveRange[]>);

  return (
    <div className="space-y-8 max-w-3xl mx-auto">
      {Object.entries(groupedByMonth).map(([month, ranges]) => (
        <div key={month} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
          <h3 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-4 pl-1">{month}</h3>
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden divide-y divide-gray-100">
            {ranges.map((range, idx) => (
              <div key={`${range.memberId}-${range.startDate.getTime()}`} className="p-4 hover:bg-gray-50 transition-colors flex items-center gap-4 group">
                {/* Avatar */}
                <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center text-gray-600 font-bold text-sm shadow-inner shrink-0">
                  {range.memberName.substring(0, 2).toUpperCase()}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0 grid sm:grid-cols-2 gap-2 sm:gap-4 items-center">
                   <div>
                      <div className="font-semibold text-gray-900 truncate">{range.memberName}</div>
                      <div className="text-xs text-gray-500 flex items-center gap-1.5 mt-0.5">
                        <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium uppercase tracking-wide border ${LEAVE_COLORS[range.type] === 'bg-white' ? 'bg-gray-100 text-gray-600 border-gray-200' : 'bg-opacity-10 text-gray-700 border-transparent'} `} 
                           style={{ 
                               backgroundColor: range.type === LeaveType.FULL_DAY ? '#fef2f2' : 
                                                range.type === LeaveType.OTHER ? '#eff6ff' : undefined,
                               color: range.type === LeaveType.FULL_DAY ? '#991b1b' :
                                      range.type === LeaveType.OTHER ? '#1e40af' : undefined
                           }}>
                            {getIcon(range.type)}
                            {LEAVE_LABELS[range.type]}
                        </span>
                      </div>
                   </div>

                   <div className="flex items-center gap-3 text-sm text-gray-600 sm:justify-end">
                      <div className="flex flex-col sm:items-end">
                        <div className="flex items-center gap-2 font-medium">
                            <span>{formatDate(range.startDate)}</span>
                            {range.days > 1 && (
                                <>
                                    <ArrowRight className="w-3 h-3 text-gray-400" />
                                    <span>{formatDate(range.endDate)}</span>
                                </>
                            )}
                        </div>
                        <span className="text-xs text-gray-400">
                            {range.days} {range.days === 1 ? 'day' : 'days'}
                        </span>
                      </div>
                   </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { Legend } from './components/Legend';
import { YearSelector } from './components/YearSelector';
import { ViewToggle } from './components/ViewToggle';
import { UpcomingLeaves } from './components/UpcomingLeaves'; // Import new component
import { LeaveType, TeamMember, LeaveRecord, ViewMode } from './types';
import { MONTHS } from './constants';
import { Calendar, RotateCcw, ChevronLeft, ChevronRight } from 'lucide-react';

// Updated storage key to reset data for version 2 (ensures clean slate for 2026)
const STORAGE_KEY = 'vacation_planner_v2';

// Initial Data
const INITIAL_TEAM: TeamMember[] = [
  { id: '1', name: 'Diego' },
  { id: '2', name: 'Lukas' },
  { id: '3', name: 'Pablo' },
];

const App: React.FC = () => {
  // State
  // Default to 2026 as requested
  const [year, setYear] = useState(2026);
  const [team, setTeam] = useState<TeamMember[]>(INITIAL_TEAM);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [currentTool, setCurrentTool] = useState<LeaveType>(LeaveType.FULL_DAY);
  const [isClient, setIsClient] = useState(false);

  // View State
  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [activeMonthIndex, setActiveMonthIndex] = useState(new Date().getMonth());

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.team) setTeam(parsed.team);
        if (parsed.leaves) setLeaves(parsed.leaves);
        // Ensure we respect the saved year if it exists, otherwise default is 2026
        if (parsed.year) setYear(parsed.year);
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }
    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ team, leaves, year }));
  }, [team, leaves, year, isClient]);

  // Handlers
  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      // Use crypto.randomUUID for better uniqueness if available, else fallback
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };
    setTeam([...team, newMember]);
  };

  const handleRemoveMember = (id: string) => {
    setTeam(prevTeam => prevTeam.filter(m => m.id !== id));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeam(prevTeam => {
      const updatedTeam = [...prevTeam];
      const [movedMember] = updatedTeam.splice(fromIndex, 1);
      updatedTeam.splice(toIndex, 0, movedMember);
      return updatedTeam;
    });
  };

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  // Smart Navigation Logic
  const handlePrevMonth = () => {
    if (activeMonthIndex === 0) {
      setActiveMonthIndex(11);
      setYear(y => y - 1);
    } else {
      setActiveMonthIndex(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (activeMonthIndex === 11) {
      setActiveMonthIndex(0);
      setYear(y => y + 1);
    } else {
      setActiveMonthIndex(prev => prev + 1);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-1.5 rounded-lg text-white shadow-sm">
                <Calendar className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-gray-900 tracking-tight hidden sm:block">Team Planner</h1>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <ViewToggle viewMode={viewMode} onViewChange={setViewMode} />
            <div className="h-6 w-px bg-gray-200"></div>
            <YearSelector year={year} onYearChange={setYear} />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Top Controls Area */}
        <div className="flex flex-col xl:flex-row xl:items-start justify-between gap-6 mb-8">
           {/* Paint Toolbar */}
           <div className="flex-1 min-w-0">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Management Tools */}
           <div className="flex flex-col sm:flex-row gap-3 flex-shrink-0">
             <TeamManager 
                team={team} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
                onReorderMembers={handleReorderMembers}
             />
             <Legend />
           </div>
        </div>

        {/* Tip Box */}
        {viewMode !== 'upcoming' && (
          <div className="mb-6 flex items-center gap-3 text-sm text-blue-800 bg-blue-50/50 px-4 py-3 rounded-lg border border-blue-100">
             <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-0.5 rounded">TIP</span>
             <span>Click on a day number (e.g., "01") in the header to toggle a global company holiday.</span>
          </div>
        )}

        {/* Calendar View Area */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">

          {viewMode === 'upcoming' ? (
             <UpcomingLeaves team={team} leaves={leaves} />
          ) : viewMode === 'year' ? (
            /* YEAR VIEW: Vertical Stack */
            <div className="space-y-8">
              {MONTHS.map((month, index) => (
                <MonthGrid
                  key={`${year}-${month}`}
                  year={year}
                  monthIndex={index}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              ))}
            </div>
          ) : (
            /* MONTH VIEW: Single Focused Card */
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden min-h-[500px] flex flex-col">
              {/* Custom Navigation Header for Single Month View */}
              <div className="bg-white px-6 py-4 border-b border-gray-100 flex items-center justify-between sticky top-0 z-10">
                 <button 
                   onClick={handlePrevMonth}
                   className="p-2 hover:bg-gray-100 rounded-full text-gray-500 hover:text-blue-600 transition-colors"
                   title="Previous Month"
                 >
                   <ChevronLeft className="w-6 h-6" />
                 </button>

                 <div className="text-center">
                    <h2 className="text-2xl font-bold text-gray-800">{MONTHS[activeMonthIndex]}</h2>
                    <p className="text-sm text-gray-400 font-medium">{year}</p>
                 </div>

                 <button 
                   onClick={handleNextMonth}
                   className="p-2 hover:bg-gray-100 rounded-full text-gray-500 hover:text-blue-600 transition-colors"
                   title="Next Month"
                 >
                   <ChevronRight className="w-6 h-6" />
                 </button>
              </div>

              {/* Grid Container */}
              <div className="p-4 sm:p-6 bg-gray-50/50 flex-1">
                <MonthGrid
                  key={`${year}-${activeMonthIndex}`} // Force remount on change for animation/cleanness
                  year={year}
                  monthIndex={activeMonthIndex}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              </div>
            </div>
          )}

        </div>

        {/* Footer */}
        <div className="mt-16 pb-8 border-t border-gray-200 pt-8 flex flex-col items-center">
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 text-gray-400 hover:text-red-500 transition-colors text-sm font-medium px-4 py-2 rounded-md hover:bg-red-50"
            >
                <RotateCcw className="w-4 h-4" />
                Reset Application Data
            </button>
            <p className="mt-2 text-xs text-gray-400">
              Data is stored locally in your browser.
            </p>
        </div>

      </main>
    </div>
  );
};

export default App;

