                    onClick={() => setEditingCell({ memberId: member.id, day })}
                    onMouseEnter={(e) => handleMouseEnter(e, member.id, day)}
                    onMouseLeave={() => setHoveredCell(null)}
                  >
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>

      {/* Reactive Tooltip */}
      {hoveredCell && !editingCell && (() => {
         const member = team.find(m => m.id === hoveredCell.memberId);
         if (!member) return null;

         const status = getStatus(hoveredCell.memberId, hoveredCell.day);
         const label = LEAVE_LABELS[status];

         return (
            <div 
                className="fixed z-50 px-3 py-2 bg-gray-900/95 text-white text-xs rounded shadow-xl pointer-events-none backdrop-blur-sm whitespace-nowrap"
