            </div>
         );
      })()}

      {/* Edit Modal */}
      {editingCell && (() => {
          const member = team.find(m => m.id === editingCell.memberId);
          if (!member) return null;

          const currentStatus = getStatus(editingCell.memberId, editingCell.day);
          const dateStr = `${MONTHS[monthIndex]} ${editingCell.day}, ${year}`;

          // Options to display in modal
          const options = [
             { type: LeaveType.FULL_DAY },
             { type: LeaveType.HALF_DAY },
             { type: LeaveType.OTHER },
             { type: LeaveType.WORK }, // Use this as "Clear"
          ];

          return (
              <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                  <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100">
                      {/* Header */}
                      <div className="bg-gray-50 px-6 py-4 border-b border-gray-100 flex justify-between items-start">
                          <div>
                              <div className="flex items-center gap-2 text-gray-500 text-xs font-bold uppercase tracking-wider mb-1">
                                  <Calendar className="w-3 h-3" />
                                  {dateStr}
                              </div>
                              <h3 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                                  <User className="w-5 h-5 text-blue-600" />
                                  {member.name}
                              </h3>
                          </div>
                          <button 
                             onClick={() => setEditingCell(null)}
                             className="text-gray-400 hover:text-gray-600 p-1 hover:bg-gray-200 rounded-full transition-colors"
                          >
                              <X className="w-5 h-5" />
                          </button>
                      </div>

                      {/* Body */}
                      <div className="p-6 space-y-3">
                          <p className="text-sm text-gray-500 mb-4">Select the leave status for this day:</p>

                          {options.map((opt) => {
                              const isSelected = currentStatus === opt.type;
                              return (
                                  <button
                                      key={opt.type}
                                      onClick={() => handleSelectLeaveFromModal(opt.type)}
                                      className={`
                                          w-full flex items-center justify-between p-3 rounded-lg border transition-all
                                          ${isSelected 
                                              ? 'bg-blue-50 border-blue-500 ring-1 ring-blue-500 text-blue-700' 
                                              : 'bg-white border-gray-200 hover:bg-gray-50 hover:border-gray-300 text-gray-700'}
                                      `}
                                  >
                                      <div className="flex items-center gap-3">
                                          <div className={`
                                              w-8 h-8 rounded-full flex items-center justify-center
                                              ${opt.type === LeaveType.WORK ? 'bg-gray-100 text-gray-500' : 'bg-white shadow-sm border border-gray-100 text-gray-700'}
                                          `}>
                                              {getLeaveIcon(opt.type)}
                                          </div>
                                          <span className="font-medium">{LEAVE_LABELS[opt.type]}</span>
                                      </div>
                                      {isSelected && <Check className="w-5 h-5 text-blue-600" />}
                                  </button>
                              );
                          })}
                      </div>
                  </div>
              </div>
          );
      })()}
    </div>
  );
};

