                                    >
                                        <div className="flex items-center gap-3">
                                            <div className={`
                                                w-8 h-8 rounded-full flex items-center justify-center
                                                ${opt.type === LeaveType.WORK ? 'bg-gray-100 text-gray-500' : 'bg-white shadow-sm border border-gray-100 text-gray-700'}
                                            `}>
                                                {getLeaveIcon(opt.type)}
                                            </div>
                                            <span className="font-medium">{LEAVE_LABELS[opt.type]}</span>
                                        </div>
                                        {isSelected && <Check className="w-5 h-5 text-blue-600" />}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                </div>
            );
          })(),
          document.body
      )}

      {/* Confirmation Dialog via Portal */}
      {showConfirmClear && createPortal(
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-xs overflow-hidden transform transition-all scale-100 p-6">
              <div className="flex flex-col items-center text-center">
                 <div className="w-12 h-12 rounded-full bg-red-100 text-red-600 flex items-center justify-center mb-4">
