                   <ChevronRight className="w-6 h-6" />
                 </button>
              </div>

              {/* Grid Container */}
              <div className="p-4 sm:p-6 bg-gray-50/50 flex-1">
                <MonthGrid
                  key={`${year}-${activeMonthIndex}`} // Force remount on change for animation/cleanness
                  year={year}
                  monthIndex={activeMonthIndex}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              </div>
            </div>
          )}

        </div>

