                      draggable
                      onDragStart={(e) => handleDragStart(e, index)}
                      onDragOver={(e) => handleDragOver(e, index)}
                      onDrop={(e) => handleDrop(e, index)}
                      className={`
                        flex items-center justify-between p-3 bg-white dark:bg-gray-800 border rounded-lg shadow-sm group transition-all
                        ${draggedIndex === index ? 'opacity-50 border-dashed border-blue-400' : 'border-gray-100 dark:border-gray-700 hover:border-blue-200 dark:hover:border-blue-500 hover:shadow-md'}
                      `}
                    >
                      <div className="flex items-center gap-3">
