import React, { useMemo } from 'react';
import { TeamMember, LeaveRecord, LeaveType } from '../types';
import { LEAVE_LABELS, LEAVE_COLORS } from '../constants';
import { Calendar, User, ArrowRight, Palmtree, Baby, CalendarDays } from 'lucide-react';

interface Props {
  team: TeamMember[];
  leaves: LeaveRecord;
}

interface LeaveRange {
  memberId: string;
  memberName: string;
  type: LeaveType;
  startDate: Date;
  endDate: Date;
  days: number;
}

export const UpcomingLeaves: React.FC<Props> = ({ team, leaves }) => {
  const upcomingRanges = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // 1. Convert leaves object to array of single day events
    const events: { date: Date; memberId: string; type: LeaveType }[] = [];

    (Object.entries(leaves) as [string, LeaveType][]).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;
      if (key.startsWith('GLOBAL_')) return; // Skip global holidays for now to focus on team

      // Parse key: userId_YYYY-MM-DD
      // We assume date is always last 10 chars
      const dateStr = key.slice(-10);
      const memberId = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      const date = new Date(y, m - 1, d);

      if (date >= today) {
        events.push({ date, memberId, type });
      }
    });

    // 2. Sort by member, then by date
    events.sort((a, b) => {
      if (a.memberId !== b.memberId) return a.memberId.localeCompare(b.memberId);
      return a.date.getTime() - b.date.getTime();
    });

    // 3. Group consecutive days into ranges
    const ranges: LeaveRange[] = [];
    let currentRange: LeaveRange | null = null;

    events.forEach((event) => {
      const member = team.find(t => t.id === event.memberId);
      if (!member) return;

      // Check if this event continues the previous range
      const isConsecutive = currentRange && 
        currentRange.memberId === event.memberId &&
        currentRange.type === event.type &&
        event.date.getTime() === currentRange.endDate.getTime() + 86400000; // +1 day in ms

      if (isConsecutive && currentRange) {
        currentRange.endDate = event.date;
        currentRange.days += 1;
      } else {
        // Push previous range if exists
        if (currentRange) ranges.push(currentRange);

        // Start new range
        currentRange = {
          memberId: event.memberId,
          memberName: member.name,
          type: event.type,
          startDate: event.date,
          endDate: event.date,
          days: 1
        };
      }
    });

    // Don't forget the last one
    if (currentRange) ranges.push(currentRange);

    // 4. Final Sort: Chronological by start date
    return ranges.sort((a, b) => a.startDate.getTime() - b.startDate.getTime());
  }, [team, leaves]);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', weekday: 'short' });
  };

  const getIcon = (type: LeaveType) => {
    switch(type) {
        case LeaveType.FULL_DAY: return <Palmtree className="w-4 h-4" />;
        case LeaveType.HALF_DAY: return <div className="w-4 h-4 rounded-full bg-gradient-to-r from-red-400 to-white border border-gray-300"></div>;
        case LeaveType.HOLIDAY: return <CalendarDays className="w-4 h-4" />;
        case LeaveType.OTHER: return <Baby className="w-4 h-4" />;
        default: return <Calendar className="w-4 h-4" />;
    }
  };

  if (upcomingRanges.length === 0) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-12 text-center transition-colors">
        <div className="bg-green-50 dark:bg-green-900/20 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
          <Calendar className="w-8 h-8 text-green-600 dark:text-green-400" />
        </div>
        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-2">No upcoming leaves</h3>
        <p className="text-gray-500 dark:text-gray-400">Everyone is scheduled to be in the office for the foreseeable future.</p>
      </div>
    );
  }

  // Group by month for better readability
  const groupedByMonth = upcomingRanges.reduce((acc, range) => {
    const key = range.startDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    if (!acc[key]) acc[key] = [];
    acc[key].push(range);
    return acc;
  }, {} as Record<string, LeaveRange[]>);

  return (
    <div className="space-y-8 max-w-3xl mx-auto">
      {(Object.entries(groupedByMonth) as [string, LeaveRange[]][]).map(([month, ranges]) => (
        <div key={month} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
          <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 pl-1">{month}</h3>
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 overflow-hidden divide-y divide-gray-100 dark:divide-gray-700 transition-colors">
            {ranges.map((range, idx) => (
              <div key={`${range.memberId}-${range.startDate.getTime()}`} className="p-4 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors flex items-center gap-4 group">
                {/* Avatar */}
                <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-700 flex items-center justify-center text-gray-600 dark:text-gray-300 font-bold text-sm shadow-inner shrink-0">
                  {range.memberName.substring(0, 2).toUpperCase()}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0 grid sm:grid-cols-2 gap-2 sm:gap-4 items-center">
                   <div>
                      <div className="font-semibold text-gray-900 dark:text-white truncate">{range.memberName}</div>
                      <div className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-1.5 mt-0.5">
                        <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium uppercase tracking-wide border ${LEAVE_COLORS[range.type].includes('bg-white') ? 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 border-gray-200 dark:border-gray-600' : 'bg-opacity-10 text-gray-700 dark:text-gray-200 border-transparent'} `} 
                           style={{ 
                               backgroundColor: range.type === LeaveType.FULL_DAY ? 'rgba(254, 242, 242, 1)' : 
                                                range.type === LeaveType.OTHER ? 'rgba(239, 246, 255, 1)' : undefined,
                               color: range.type === LeaveType.FULL_DAY ? '#991b1b' :
                                      range.type === LeaveType.OTHER ? '#1e40af' : undefined
                           }}>
                            {getIcon(range.type)}
                            {LEAVE_LABELS[range.type]}
                        </span>
                      </div>
                   </div>

                   <div className="flex items-center gap-3 text-sm text-gray-600 dark:text-gray-300 sm:justify-end">
                      <div className="flex flex-col sm:items-end">
                        <div className="flex items-center gap-2 font-medium">
                            <span>{formatDate(range.startDate)}</span>
                            {range.days > 1 && (
                                <>
                                    <ArrowRight className="w-3 h-3 text-gray-400 dark:text-gray-500" />
                                    <span>{formatDate(range.endDate)}</span>
                                </>
                            )}
                        </div>
                        <span className="text-xs text-gray-400 dark:text-gray-500">
                            {range.days} {range.days === 1 ? 'day' : 'days'}
                        </span>
                      </div>
                   </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

