            ${selectedTool === tool.type && tool.type === LeaveType.HOLIDAY ? 'bg-yellow-400 text-black' : ''}
            ${selectedTool === tool.type && tool.type === LeaveType.OTHER ? 'bg-blue-400 text-white' : ''}
