                        </button>
                    </form>

                    {/* Existing Leaves List */}
                    {leaveMemberId && (
                        <div className="border-t border-gray-100 dark:border-gray-700 pt-4 mt-4">
                            <h4 className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-3">
                                Leaves in {MONTHS[monthIndex]} for {team.find(t => t.id === leaveMemberId)?.name}
                            </h4>

                            <div className="space-y-2 max-h-40 overflow-y-auto pr-2 hide-scrollbar">
                                {getMemberLeavesInMonth(leaveMemberId).length === 0 ? (
                                    <p className="text-sm text-gray-400 italic">No leaves scheduled.</p>
                                ) : (
                                    getMemberLeavesInMonth(leaveMemberId).map(day => {
                                        const key = generateLeaveKey(leaveMemberId, year, monthIndex, day);
                                        const type = leaves[key];
                                        return (
                                            <div 
                                                key={day} 
                                                className="flex items-center justify-between p-2 rounded border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/20"
                                            >
                                                <div className="flex items-center gap-2">
                                                    <span className="font-bold text-gray-700 dark:text-gray-300 w-6 text-center">{day}</span>
                                                    <span className="text-sm text-gray-500 dark:text-gray-400">{DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)]}</span>
                                                    <span className={`text-[10px] px-1.5 py-0.5 rounded border ${
                                                        type === LeaveType.FULL_DAY ? 'bg-red-50 text-red-600 border-red-100' :
                                                        type === LeaveType.HALF_DAY ? 'bg-orange-50 text-orange-600 border-orange-100' :
                                                        'bg-blue-50 text-blue-600 border-blue-100'
                                                    }`}>
                                                        {type === LeaveType.FULL_DAY ? 'FULL' : type === LeaveType.HALF_DAY ? 'HALF' : 'OTHER'}
                                                    </span>
                                                </div>
                                                <button 
                                                    onClick={() => handleRemoveMemberLeave(day)}
                                                    className="text-gray-400 hover:text-red-500 p-1 rounded hover:bg-white dark:hover:bg-gray-800 transition-colors"
                                                    title="Remove Leave"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </div>
                    )}
                </div>
             </div>
          </div>,
          document.body
      )}

      {/* Confirmation Dialog via Portal */}
      {showConfirmClear && createPortal(
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
           <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-xs overflow-hidden transform transition-all scale-100 p-6 ring-1 ring-gray-200 dark:ring-gray-700">
              <div className="flex flex-col items-center text-center">
                 <div className="w-12 h-12 rounded-full bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 flex items-center justify-center mb-4">
                    <AlertTriangle className="w-6 h-6" />
                 </div>
                 <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-2">Clear Leave?</h3>
                 <p className="text-sm text-gray-500 dark:text-gray-400 mb-6">
                    Are you sure you want to remove the assigned leave for this day? This action cannot be undone immediately.
                 </p>
                 <div className="flex gap-3 w-full">
                    <button 
                      onClick={cancelClear}
                      className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={confirmClear}
                      className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg font-medium hover:bg-red-700 transition-colors"
                    >
                      Clear
                    </button>
                 </div>
              </div>
           </div>
        </div>,
        document.body
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { TeamMember, LeaveType, LeaveRecord } from '../types';
import { MONTHS, DAYS_OF_WEEK, LEAVE_COLORS, LEAVE_LABELS } from '../constants';
import { getDaysInMonth, isWeekend, getDayOfWeekIndex, generateLeaveKey, generateGlobalKey } from '../utils';
import { X, Check, Calendar, User, Palmtree, Eraser, Baby, CalendarDays, AlertTriangle, Plus, Trash2, CalendarPlus, Pencil, Save, Ban, UserPlus, Briefcase } from 'lucide-react';

interface Props {
  year: number;
  monthIndex: number;
  team: TeamMember[];
  leaves: LeaveRecord;
  currentTool: LeaveType | null;
  onToggleLeave: (key: string, type: LeaveType) => void;
}

export const MonthGrid: React.FC<Props> = ({ 
  year, 
  monthIndex, 
  team, 
  leaves, 
  currentTool,
  onToggleLeave 
}) => {
  const daysInMonth = getDaysInMonth(year, monthIndex);
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  // State for hover tooltip
  const [hoveredCell, setHoveredCell] = useState<{
    x: number;
    y: number;
    memberId: string;
    day: number;
  } | null>(null);

  // State for Edit Modal (Single Cell)
  const [editingCell, setEditingCell] = useState<{
    memberId: string;
    day: number;
  } | null>(null);

  // State for Confirmation Dialog
  const [showConfirmClear, setShowConfirmClear] = useState(false);

  // State for Holiday Manager Modal
  const [showHolidayManager, setShowHolidayManager] = useState(false);
  // Form state for Adding
  const [holidayStartDate, setHolidayStartDate] = useState('');
  const [holidayEndDate, setHolidayEndDate] = useState('');

  // Inline Edit state for Holidays
  const [editingHolidayOriginalDate, setEditingHolidayOriginalDate] = useState<number | null>(null);
  const [editHolidayValue, setEditHolidayValue] = useState('');

  // State for Team Leave Manager Modal
  const [showLeaveManager, setShowLeaveManager] = useState(false);
  const [leaveMemberId, setLeaveMemberId] = useState('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.FULL_DAY);
  const [leaveStartDate, setLeaveStartDate] = useState('');
  const [leaveEndDate, setLeaveEndDate] = useState('');

  // Auto-select first member when opening leave manager
  useEffect(() => {
    if (showLeaveManager && !leaveMemberId && team.length > 0) {
      setLeaveMemberId(team[0].id);
    }
  }, [showLeaveManager, team, leaveMemberId]);

  // Helper to safely get status including global overrides
  const getStatus = (userId: string, day: number) => {
    const userKey = generateLeaveKey(userId, year, monthIndex, day);
    const userStatus = leaves[userKey];

    const globalKey = generateGlobalKey(year, monthIndex, day);
    const isGlobalHoliday = leaves[globalKey] === LeaveType.HOLIDAY;

    if (isGlobalHoliday) return LeaveType.HOLIDAY;
    return userStatus || LeaveType.WORK;
  };

  const isGlobalHoliday = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    return leaves[key] === LeaveType.HOLIDAY;
  };

  const handleDayHeaderClick = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    const current = leaves[key];
    onToggleLeave(key, current === LeaveType.HOLIDAY ? LeaveType.WORK : LeaveType.HOLIDAY);
  };

  const handleMouseEnter = (e: React.MouseEvent, memberId: string, day: number) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setHoveredCell({
        x: rect.left + rect.width / 2,
        y: rect.top,
        memberId,
        day
    });
  };

  const handleCellClick = (memberId: string, day: number) => {
    if (currentTool === null) {
        // Pointer Mode: Open Modal
        setEditingCell({ memberId, day });
    } else {
        // Paint Mode
        const key = generateLeaveKey(memberId, year, monthIndex, day);
        const currentStatus = leaves[key];

        // Safety Check for Eraser in Paint Mode if removing existing leave
        if (currentTool === LeaveType.WORK && currentStatus) {
            setEditingCell({ memberId, day }); // Track which cell for confirmation
            setShowConfirmClear(true);
            return;
        }

        onToggleLeave(key, currentTool);
    }
  };

  const handleSelectLeaveFromModal = (type: LeaveType) => {
    if (!editingCell) return;

    // Check if we are clearing an existing user leave
    const userKey = generateLeaveKey(editingCell.memberId, year, monthIndex, editingCell.day);
    const hasUserLeave = leaves[userKey] !== undefined;

    if (type === LeaveType.WORK && hasUserLeave) {
        setShowConfirmClear(true);
        return;
    }

    const key = generateLeaveKey(editingCell.memberId, year, monthIndex, editingCell.day);
    onToggleLeave(key, type);
    setEditingCell(null);
  };

  const confirmClear = () => {
    if (!editingCell) return;
    const key = generateLeaveKey(editingCell.memberId, year, monthIndex, editingCell.day);
    onToggleLeave(key, LeaveType.WORK);
    setShowConfirmClear(false);
    setEditingCell(null);
  };

  const cancelClear = () => {
    setShowConfirmClear(false);
  };

  // --- Holiday Manager Logic ---

  const handleAddHolidayRange = (e: React.FormEvent) => {
    e.preventDefault();
    if (!holidayStartDate) return;

    // Determine range
    const start = new Date(holidayStartDate);
    const end = holidayEndDate ? new Date(holidayEndDate) : new Date(holidayStartDate);

    // Simple validation
    if (end < start) {
        alert("End date cannot be before start date");
        return;
    }

    // Iterate and add
    const current = new Date(start);
    while (current <= end) {
        const kYear = current.getFullYear();
        const kMonth = current.getMonth(); // 0-11
        const kDay = current.getDate();

        const key = generateGlobalKey(kYear, kMonth, kDay);
        onToggleLeave(key, LeaveType.HOLIDAY);

        // Next day
        current.setDate(current.getDate() + 1);
    }

    setHolidayStartDate('');
    setHolidayEndDate('');
  };

  const handleStartEditHoliday = (day: number) => {
    setEditingHolidayOriginalDate(day);
    // Format YYYY-MM-DD for the input
    const dateStr = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    setEditHolidayValue(dateStr);
  };

  const handleSaveEditHoliday = () => {
    if (editingHolidayOriginalDate === null || !editHolidayValue) return;

    const [y, m, d] = editHolidayValue.split('-').map(Number);

    // Basic validation
    if (isNaN(y) || isNaN(m) || isNaN(d)) return;

    // Remove old holiday
    const oldKey = generateGlobalKey(year, monthIndex, editingHolidayOriginalDate);
    onToggleLeave(oldKey, LeaveType.WORK);

    // Add new holiday
    // Note: Month from input is 1-12, Date constructor expects 0-11 for month
    const newKey = generateGlobalKey(y, m - 1, d);
    onToggleLeave(newKey, LeaveType.HOLIDAY);

    setEditingHolidayOriginalDate(null);
    setEditHolidayValue('');
  };

  const handleCancelEdit = () => {
    setEditingHolidayOriginalDate(null);
    setEditHolidayValue('');
    setHolidayStartDate('');
    setHolidayEndDate('');
  };

  const handleRemoveHoliday = (day: number) => {
    if (editingHolidayOriginalDate === day) {
        handleCancelEdit();
    }
    const key = generateGlobalKey(year, monthIndex, day);
    onToggleLeave(key, LeaveType.WORK);
  };

  // --- Leave Manager Logic ---

  const handleAddLeaveRange = (e: React.FormEvent) => {
    e.preventDefault();
    if (!leaveMemberId || !leaveStartDate) return;

    const start = new Date(leaveStartDate);
    const end = leaveEndDate ? new Date(leaveEndDate) : new Date(leaveStartDate);

    if (end < start) {
        alert("End date cannot be before start date");
        return;
    }

    if (start.getFullYear() !== year || start.getMonth() !== monthIndex) {
        alert(`Start date must be within ${MONTHS[monthIndex]} ${year}`);
        return;
    }

    const current = new Date(start);
    while (current <= end) {
        const kYear = current.getFullYear();
        const kMonth = current.getMonth();
        const kDay = current.getDate();

        const key = generateLeaveKey(leaveMemberId, kYear, kMonth, kDay);
        onToggleLeave(key, leaveType);

        current.setDate(current.getDate() + 1);
    }

    setLeaveStartDate('');
    setLeaveEndDate('');
  };

  const handleRemoveMemberLeave = (day: number) => {
    if (!leaveMemberId) return;
    const key = generateLeaveKey(leaveMemberId, year, monthIndex, day);
    onToggleLeave(key, LeaveType.WORK);
  };

  const getMemberLeavesInMonth = (memberId: string) => {
      if (!memberId) return [];
      return daysArray.filter(day => {
          const key = generateLeaveKey(memberId, year, monthIndex, day);
          const val = leaves[key];
          return val && val !== LeaveType.WORK;
      });
  };

  const getLeaveIcon = (type: LeaveType) => {
      switch(type) {
          case LeaveType.FULL_DAY: return <Palmtree className="w-4 h-4" />;
          case LeaveType.HALF_DAY: return <div className="w-4 h-4 rounded-full bg-gradient-to-r from-red-400 to-white border border-gray-300"></div>;
          case LeaveType.HOLIDAY: return <CalendarDays className="w-4 h-4" />;
          case LeaveType.OTHER: return <Baby className="w-4 h-4" />;
          case LeaveType.WORK: return <Eraser className="w-4 h-4" />;
          default: return <Check className="w-4 h-4" />;
      }
  };

  const currentMonthHolidays = daysArray.filter(day => isGlobalHoliday(day));

  return (
    <div className="mb-8 bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden transition-colors">
      {/* Month Header */}
      <div className="bg-gray-100 dark:bg-gray-700/50 px-4 py-2 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center transition-colors">
        <span className="font-bold text-gray-700 dark:text-gray-200 uppercase tracking-wider">
          {MONTHS[monthIndex]}
        </span>
        <div className="flex items-center gap-2">
            <button
            onClick={() => {
                setShowLeaveManager(true);
            }}
            className="flex items-center gap-1.5 text-xs font-medium text-green-600 dark:text-green-400 hover:text-green-800 dark:hover:text-green-300 bg-green-50 dark:bg-green-900/30 hover:bg-green-100 dark:hover:bg-green-900/50 px-2 py-1 rounded transition-colors"
            title="Add vacations/leaves"
            >
            <UserPlus className="w-3.5 h-3.5" />
            Add Leave
            </button>
            <button
            onClick={() => {
                setShowHolidayManager(true);
                handleCancelEdit();
            }}
            className="flex items-center gap-1.5 text-xs font-medium text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 bg-blue-50 dark:bg-blue-900/30 hover:bg-blue-100 dark:hover:bg-blue-900/50 px-2 py-1 rounded transition-colors"
            title="Manage Holidays for this month"
            >
            <CalendarPlus className="w-3.5 h-3.5" />
            Manage Holidays
            </button>
        </div>
      </div>

      <div className="overflow-x-auto hide-scrollbar">
        <div className="inline-block min-w-full">
          {/* Header Row (Days) */}
          <div className="flex border-b border-gray-200 dark:border-gray-700">
            {/* Name Column Header */}
            <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-gray-50 dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-2 font-medium text-xs text-gray-500 dark:text-gray-400 transition-colors">
              Employee
            </div>

            {/* Day Columns */}
            {daysArray.map(day => {
               const isWE = isWeekend(year, monthIndex, day);
               const isHoliday = isGlobalHoliday(day);
               const dayName = DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)];

               return (
                <div 
                  key={day} 
                  onClick={() => handleDayHeaderClick(day)}
                  className={`
                    w-8 flex-shrink-0 text-center border-r border-gray-100 dark:border-gray-700 last:border-r-0 cursor-pointer transition-colors
                    ${isWE 
                      ? 'bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600' 
                      : isHoliday 
                        ? 'bg-yellow-100 dark:bg-yellow-900/30 hover:bg-yellow-200 dark:hover:bg-yellow-900/50' 
                        : 'bg-white dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700'}
                  `}
                  title="Click to toggle Global Axalta Holiday"
                >
                  <div className={`text-xs font-bold p-1 ${
                      isHoliday ? 'text-yellow-700 dark:text-yellow-500' : 
                      isWE ? 'text-gray-500 dark:text-gray-400' : 'text-gray-700 dark:text-gray-300'
                  }`}>{day}</div>
                  <div className="text-[10px] text-gray-400 dark:text-gray-500 font-medium pb-1">{dayName}</div>
                </div>
              );
            })}
          </div>

          {/* User Rows */}
          {team.map(member => (
            <div key={member.id} className="flex border-b border-gray-100 dark:border-gray-700 last:border-b-0 hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
              {/* Name Cell */}
              <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 p-2 flex items-center transition-colors">
                <span className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate" title={member.name}>
                  {member.name}
                </span>
              </div>

              {/* Day Cells */}
              {daysArray.map(day => {
                const status = getStatus(member.id, day);
                const isWE = isWeekend(year, monthIndex, day);
                const bgClass = status !== LeaveType.WORK 
                  ? LEAVE_COLORS[status] 
                  : isWE 
                    ? 'bg-gray-200 dark:bg-gray-700' 
                    : 'bg-white dark:bg-gray-800';

                return (
                  <div
                    key={day}
                    className={`
                      w-8 h-10 flex-shrink-0 border-r border-gray-100 dark:border-gray-700 last:border-r-0 cursor-pointer
                      transition-all duration-75 relative
                      ${bgClass}
                      hover:brightness-90 dark:hover:brightness-110
                    `}
                    onClick={() => handleCellClick(member.id, day)}
                    onMouseEnter={(e) => handleMouseEnter(e, member.id, day)}
                    onMouseLeave={() => setHoveredCell(null)}
                  >
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>

      {/* Reactive Tooltip via Portal */}
      {hoveredCell && !editingCell && createPortal(
         (() => {
           const member = team.find(m => m.id === hoveredCell.memberId);
           if (!member) return null;

           const status = getStatus(hoveredCell.memberId, hoveredCell.day);
           const label = LEAVE_LABELS[status];

           return (
              <div 
                  className="fixed z-50 px-3 py-2 bg-gray-900/95 dark:bg-gray-700/95 text-white text-xs rounded shadow-xl pointer-events-none backdrop-blur-sm whitespace-nowrap"
                  style={{ 
                      left: hoveredCell.x, 
                      top: hoveredCell.y, 
                      transform: 'translate(-50%, -125%)'
                  }}
              >
                  <div className="font-bold mb-0.5">{member.name}</div>
                  <div className="font-light text-gray-200">{label}</div>
                  <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 translate-y-full border-4 border-transparent border-t-gray-900/95 dark:border-t-gray-700/95"></div>
              </div>
           );
         })(),
         document.body
      )}

      {/* Edit Modal via Portal */}
      {editingCell && createPortal(
          (() => {
            const member = team.find(m => m.id === editingCell.memberId);
            if (!member) return null;

            const currentStatus = getStatus(editingCell.memberId, editingCell.day);
            const dateStr = `${MONTHS[monthIndex]} ${editingCell.day}, ${year}`;

            // Options to display in modal
            const options = [
               { type: LeaveType.FULL_DAY },
               { type: LeaveType.HALF_DAY },
               { type: LeaveType.HOLIDAY }, // Added Axalta Holiday
               { type: LeaveType.OTHER },
               { type: LeaveType.WORK }, // Use this as "Clear"
            ];

            return (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100 ring-1 ring-gray-200 dark:ring-gray-700">
                        {/* Header */}
                        <div className="bg-gray-50 dark:bg-gray-900/50 px-6 py-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-start">
                            <div>
                                <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-xs font-bold uppercase tracking-wider mb-1">
                                    <Calendar className="w-3 h-3" />
                                    {dateStr}
                                </div>
                                <h3 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2">
                                    <User className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                                    {member.name}
                                </h3>
                            </div>
                            <button 
                               onClick={() => setEditingCell(null)}
                               className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        {/* Body */}
                        <div className="p-6 space-y-3">
                            <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">Select the leave status for this day:</p>

                            {options.map((opt) => {
                                const isSelected = currentStatus === opt.type;
                                return (
                                    <button
                                        key={opt.type}
                                        onClick={() => handleSelectLeaveFromModal(opt.type)}
                                        className={`
                                            w-full flex items-center justify-between p-3 rounded-lg border transition-all
                                            ${isSelected 
                                                ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-500 dark:border-blue-400 ring-1 ring-blue-500 dark:ring-blue-400 text-blue-700 dark:text-blue-300' 
                                                : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 hover:border-gray-300 dark:hover:border-gray-600 text-gray-700 dark:text-gray-300'}
                                        `}
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className={`
                                                w-8 h-8 rounded-full flex items-center justify-center
                                                ${opt.type === LeaveType.WORK ? 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400' : 'bg-white dark:bg-gray-800 shadow-sm border border-gray-100 dark:border-gray-700 text-gray-700 dark:text-gray-300'}
                                            `}>
                                                {getLeaveIcon(opt.type)}
                                            </div>
                                            <span className="font-medium">{LEAVE_LABELS[opt.type]}</span>
                                        </div>
                                        {isSelected && <Check className="w-5 h-5 text-blue-600 dark:text-blue-400" />}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                </div>
            );
          })(),
          document.body
      )}

      {/* Holiday Manager Modal via Portal */}
      {showHolidayManager && createPortal(
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100 ring-1 ring-gray-200 dark:ring-gray-700">
                {/* Header */}
                <div className="bg-yellow-50 dark:bg-yellow-900/20 px-6 py-4 border-b border-yellow-100 dark:border-yellow-900/30 flex justify-between items-center">
                    <h3 className="text-lg font-bold text-yellow-800 dark:text-yellow-500 flex items-center gap-2">
                        <CalendarDays className="w-5 h-5" />
                        Manage Holidays
                    </h3>
                    <button 
                       onClick={() => {
                           setShowHolidayManager(false);
                           handleCancelEdit();
                       }}
                       className="text-yellow-800/50 hover:text-yellow-800 dark:text-yellow-500/50 dark:hover:text-yellow-400 p-1 hover:bg-yellow-100 dark:hover:bg-yellow-900/50 rounded-full transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <div className="p-6">
                    <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
                        Add or remove Axalta Holidays for {MONTHS[monthIndex]} {year}.
                    </p>

                    {/* Add Form */}
                    <form onSubmit={handleAddHolidayRange} className="flex flex-col gap-2 mb-6">
                        <div className="flex gap-2 items-center">
                            <div className="flex-1">
                                <label className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 mb-0.5 block">
                                    Start
                                </label>
                                <input 
                                    type="date"
                                    required
                                    value={holidayStartDate}
                                    onChange={(e) => setHolidayStartDate(e.target.value)}
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg text-sm focus:ring-2 focus:ring-yellow-500 outline-none"
                                />
                            </div>

                            <div className="flex-1">
                                <label className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 mb-0.5 block">
                                    End <span className="font-normal normal-case text-gray-300">(Optional)</span>
                                </label>
                                <input 
                                    type="date"
                                    min={holidayStartDate}
                                    value={holidayEndDate}
                                    onChange={(e) => setHolidayEndDate(e.target.value)}
                                    placeholder="Same as start"
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg text-sm focus:ring-2 focus:ring-yellow-500 outline-none"
                                />
                            </div>
                        </div>

                        <button 
                        type="submit"
                        className="w-full bg-yellow-500 hover:bg-yellow-600 text-white px-3 py-2 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm font-medium mt-1"
                        >
                            <Plus className="w-4 h-4" /> Add Holiday(s)
                        </button>
                    </form>

                    <div className="border-t border-gray-100 dark:border-gray-700 pt-4">
                        <h4 className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-3">
                            Scheduled Holidays ({currentMonthHolidays.length})
                        </h4>

                        <div className="space-y-2 max-h-40 overflow-y-auto pr-2 hide-scrollbar">
                            {currentMonthHolidays.length === 0 ? (
                                <p className="text-sm text-gray-400 italic">No holidays set for this month.</p>
                            ) : (
                                currentMonthHolidays.map(day => (
                                    <div 
                                        key={day} 
                                        className={`flex items-center justify-between p-2 rounded border transition-colors ${
                                            editingHolidayOriginalDate === day 
                                            ? 'bg-yellow-50 dark:bg-yellow-900/30 border-yellow-200 dark:border-yellow-700 ring-1 ring-yellow-400' 
                                            : 'bg-yellow-50 dark:bg-yellow-900/10 border-yellow-100 dark:border-yellow-900/30'
                                        }`}
                                    >
                                        {editingHolidayOriginalDate === day ? (
                                            // Inline Edit Mode
                                            <div className="flex items-center gap-2 w-full">
                                                <input 
                                                    type="date" 
                                                    value={editHolidayValue}
                                                    onChange={(e) => setEditHolidayValue(e.target.value)}
                                                    className="flex-1 px-2 py-1 text-sm border border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white rounded outline-none focus:ring-1 focus:ring-yellow-500"
                                                />
                                                <div className="flex items-center gap-1">
                                                    <button 
                                                        onClick={handleSaveEditHoliday}
                                                        className="p-1.5 bg-green-500 hover:bg-green-600 text-white rounded transition-colors"
                                                        title="Save Changes"
                                                    >
                                                        <Check className="w-3.5 h-3.5" />
                                                    </button>
                                                    <button 
                                                        onClick={handleCancelEdit}
                                                        className="p-1.5 bg-gray-200 hover:bg-gray-300 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-600 dark:text-gray-300 rounded transition-colors"
                                                        title="Cancel Edit"
                                                    >
                                                        <X className="w-3.5 h-3.5" />
                                                    </button>
                                                </div>
                                            </div>
                                        ) : (
                                            // Display Mode
                                            <>
                                                <div className="flex items-center gap-3">
                                                    {/* Visual Indicator */}
                                                    <div className="w-8 h-8 rounded-full bg-yellow-100 dark:bg-yellow-900/50 flex items-center justify-center text-yellow-600 dark:text-yellow-400">
                                                        <CalendarDays className="w-4 h-4" />
                                                    </div>
                                                    <div>
                                                        <span className="font-bold text-gray-700 dark:text-gray-200 block text-sm">
                                                            {MONTHS[monthIndex]} {day}
                                                        </span>
                                                        <span className="text-[10px] text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                                                            {DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)]}
                                                        </span>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <button 
                                                        onClick={() => handleStartEditHoliday(day)}
                                                        className="text-gray-400 hover:text-blue-500 p-1.5 rounded hover:bg-white dark:hover:bg-gray-800 transition-colors"
                                                        title="Edit Holiday Date"
                                                    >
                                                        <Pencil className="w-4 h-4" />
                                                    </button>
                                                    <button 
                                                        onClick={() => handleRemoveHoliday(day)}
                                                        className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-white dark:hover:bg-gray-800 transition-colors"
                                                        title="Remove Holiday"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            </>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
             </div>
          </div>,
          document.body
      )}

      {/* Leave Manager Modal via Portal */}
      {showLeaveManager && createPortal(
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100 ring-1 ring-gray-200 dark:ring-gray-700">
                {/* Header */}
                <div className="bg-green-50 dark:bg-green-900/20 px-6 py-4 border-b border-green-100 dark:border-green-900/30 flex justify-between items-center">
                    <h3 className="text-lg font-bold text-green-800 dark:text-green-500 flex items-center gap-2">
                        <Briefcase className="w-5 h-5" />
                        Manage Leaves
                    </h3>
                    <button 
                       onClick={() => setShowLeaveManager(false)}
                       className="text-green-800/50 hover:text-green-800 dark:text-green-500/50 dark:hover:text-green-400 p-1 hover:bg-green-100 dark:hover:bg-green-900/50 rounded-full transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <div className="p-6">
                    <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
                        Add vacations or other leaves for team members in {MONTHS[monthIndex]} {year}.
                    </p>

                    <form onSubmit={handleAddLeaveRange} className="space-y-4">
                        {/* Member Select */}
                        <div>
                             <label className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 mb-0.5 block">
                                Team Member
                             </label>
                             <select 
                                value={leaveMemberId}
                                onChange={(e) => setLeaveMemberId(e.target.value)}
                                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg text-sm focus:ring-2 focus:ring-green-500 outline-none"
                             >
                                {team.map(m => (
                                    <option key={m.id} value={m.id}>{m.name}</option>
                                ))}
                             </select>
                        </div>

                        {/* Type Select */}
                        <div>
                             <label className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 mb-0.5 block">
                                Leave Type
                             </label>
                             <div className="grid grid-cols-3 gap-2">
                                {[LeaveType.FULL_DAY, LeaveType.HALF_DAY, LeaveType.OTHER].map(t => (
                                    <button
                                        key={t}
                                        type="button"
                                        onClick={() => setLeaveType(t)}
                                        className={`
                                            flex items-center justify-center gap-2 py-2 rounded-lg text-xs font-medium border transition-all
                                            ${leaveType === t 
                                                ? 'bg-green-50 dark:bg-green-900/20 border-green-500 text-green-700 dark:text-green-400 ring-1 ring-green-500' 
                                                : 'border-gray-200 dark:border-gray-600 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'}
                                        `}
                                    >
                                        {t === LeaveType.FULL_DAY && 'Full'}
                                        {t === LeaveType.HALF_DAY && 'Half'}
                                        {t === LeaveType.OTHER && 'Other'}
                                    </button>
                                ))}
                             </div>
                        </div>

                        {/* Date Range */}
                        <div className="flex gap-2 items-center">
                            <div className="flex-1">
                                <label className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 mb-0.5 block">
                                    Start
                                </label>
                                <input 
                                    type="date"
                                    required
                                    value={leaveStartDate}
                                    onChange={(e) => setLeaveStartDate(e.target.value)}
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg text-sm focus:ring-2 focus:ring-green-500 outline-none"
                                />
                            </div>

                            <div className="flex-1">
                                <label className="text-[10px] uppercase font-bold text-gray-400 dark:text-gray-500 mb-0.5 block">
                                    End <span className="font-normal normal-case text-gray-300">(Optional)</span>
                                </label>
                                <input 
                                    type="date"
                                    min={leaveStartDate}
                                    value={leaveEndDate}
                                    onChange={(e) => setLeaveEndDate(e.target.value)}
                                    placeholder="Same as start"
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 dark:bg-gray-900 dark:text-white rounded-lg text-sm focus:ring-2 focus:ring-green-500 outline-none"
                                />
                            </div>
                        </div>

                        <button 
                           type="submit"
                           className="w-full bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm font-medium"
                        >
                            <Plus className="w-4 h-4" /> Add Leave
                        </button>
                    </form>

                    {/* Existing Leaves List */}
                    {leaveMemberId && (
                        <div className="border-t border-gray-100 dark:border-gray-700 pt-4 mt-4">
                            <h4 className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-3">
                                Leaves in {MONTHS[monthIndex]} for {team.find(t => t.id === leaveMemberId)?.name}
                            </h4>

                            <div className="space-y-2 max-h-40 overflow-y-auto pr-2 hide-scrollbar">
                                {getMemberLeavesInMonth(leaveMemberId).length === 0 ? (
                                    <p className="text-sm text-gray-400 italic">No leaves scheduled.</p>
                                ) : (
                                    getMemberLeavesInMonth(leaveMemberId).map(day => {
                                        const key = generateLeaveKey(leaveMemberId, year, monthIndex, day);
                                        const type = leaves[key];
                                        return (
                                            <div 
                                                key={day} 
                                                className="flex items-center justify-between p-2 rounded border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/20"
                                            >
                                                <div className="flex items-center gap-2">
                                                    <span className="font-bold text-gray-700 dark:text-gray-300 w-6 text-center">{day}</span>
                                                    <span className="text-sm text-gray-500 dark:text-gray-400">{DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)]}</span>
                                                    <span className={`text-[10px] px-1.5 py-0.5 rounded border ${
                                                        type === LeaveType.FULL_DAY ? 'bg-red-50 text-red-600 border-red-100' :
                                                        type === LeaveType.HALF_DAY ? 'bg-orange-50 text-orange-600 border-orange-100' :
                                                        'bg-blue-50 text-blue-600 border-blue-100'
                                                    }`}>
                                                        {type === LeaveType.FULL_DAY ? 'FULL' : type === LeaveType.HALF_DAY ? 'HALF' : 'OTHER'}
                                                    </span>
                                                </div>
                                                <button 
                                                    onClick={() => handleRemoveMemberLeave(day)}
                                                    className="text-gray-400 hover:text-red-500 p-1 rounded hover:bg-white dark:hover:bg-gray-800 transition-colors"
                                                    title="Remove Leave"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </div>
                    )}
                </div>
             </div>
          </div>,
          document.body
      )}

      {/* Confirmation Dialog via Portal */}
      {showConfirmClear && createPortal(
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
           <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-xs overflow-hidden transform transition-all scale-100 p-6 ring-1 ring-gray-200 dark:ring-gray-700">
              <div className="flex flex-col items-center text-center">
                 <div className="w-12 h-12 rounded-full bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 flex items-center justify-center mb-4">
                    <AlertTriangle className="w-6 h-6" />
                 </div>
                 <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-2">Clear Leave?</h3>
                 <p className="text-sm text-gray-500 dark:text-gray-400 mb-6">
                    Are you sure you want to remove the assigned leave for this day? This action cannot be undone immediately.
                 </p>
                 <div className="flex gap-3 w-full">
                    <button 
                      onClick={cancelClear}
                      className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={confirmClear}
                      className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg font-medium hover:bg-red-700 transition-colors"
                    >
                      Clear
                    </button>
                 </div>
              </div>
           </div>
        </div>,
        document.body
      )}
    </div>
  );
};

import { LeaveType } from './types';

export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

export const DAYS_OF_WEEK = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

export const LEAVE_COLORS: Record<LeaveType, string> = {
  [LeaveType.WORK]: 'bg-t-surface hover:bg-t-hover',
  [LeaveType.FULL_DAY]: 'bg-red-500 text-white',
  // Gradient: Red to White (Light) / Red to Gray-800 (Dark)
  // Note: For Soft mode, we keep generic white/gray mix, or could improve to be transparent.
  // Sticking to hardcoded gradient for simplicity as it simulates "half".
  [LeaveType.HALF_DAY]: 'bg-[linear-gradient(135deg,_#ef4444_50%,_#ffffff_50%)] dark:bg-[linear-gradient(135deg,_#ef4444_50%,_#1f2937_50%)]',
  [LeaveType.HOLIDAY]: 'bg-yellow-400 text-yellow-900',
  [LeaveType.OTHER]: 'bg-blue-400 text-white',
};

export const LEAVE_LABELS: Record<LeaveType, string> = {
  [LeaveType.WORK]: 'Clear / Work Day',
  [LeaveType.FULL_DAY]: 'Vacation (Full)',
  [LeaveType.HALF_DAY]: 'Vacation (Half)',
  [LeaveType.HOLIDAY]: 'Axalta Holiday',
  [LeaveType.OTHER]: 'Paternity / Other',
};

import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { Legend } from './components/Legend';
import { YearSelector } from './components/YearSelector';
import { ViewToggle } from './components/ViewToggle';
import { UpcomingLeaves } from './components/UpcomingLeaves';
import { LeaveType, TeamMember, LeaveRecord, ViewMode } from './types';
import { MONTHS, LEAVE_LABELS } from './constants';
import { Calendar, RotateCcw, ChevronLeft, ChevronRight, Download, Moon, Sun, Coffee } from 'lucide-react';

const STORAGE_KEY = 'vacation_planner_v2';
const THEME_KEY = 'vacation_planner_theme_v2';

// Initial Data
const INITIAL_TEAM: TeamMember[] = [
  { id: '1', name: 'Diego' },
  { id: '2', name: 'Lukas' },
  { id: '3', name: 'Pablo' },
];

type ThemeMode = 'light' | 'soft' | 'dark';

const App: React.FC = () => {
  // State
  const [year, setYear] = useState(2026);
  const [team, setTeam] = useState<TeamMember[]>(INITIAL_TEAM);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [currentTool, setCurrentTool] = useState<LeaveType | null>(null);
  const [isClient, setIsClient] = useState(false);
  const [theme, setTheme] = useState<ThemeMode>('light');
  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [activeMonthIndex, setActiveMonthIndex] = useState(new Date().getMonth());

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.team) setTeam(parsed.team);
        if (parsed.leaves) setLeaves(parsed.leaves);
        if (parsed.year) setYear(parsed.year);
      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }

    // Load theme
    const savedTheme = localStorage.getItem(THEME_KEY) as ThemeMode;
    if (['light', 'soft', 'dark'].includes(savedTheme)) {
      setTheme(savedTheme);
    } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme('dark');
    }

    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ team, leaves, year }));
  }, [team, leaves, year, isClient]);

  // Handle Theme Change
  useEffect(() => {
    const root = window.document.documentElement;
    // Reset
    root.classList.remove('dark', 'theme-soft');

    if (theme === 'dark') {
      root.classList.add('dark');
    } else if (theme === 'soft') {
      root.classList.add('theme-soft');
    }
    localStorage.setItem(THEME_KEY, theme);
  }, [theme]);

  const toggleTheme = () => {
    const cycle: Record<ThemeMode, ThemeMode> = {
      'light': 'soft',
      'soft': 'dark',
      'dark': 'light'
    };
    setTheme(prev => cycle[prev]);
  };

  // Handlers
  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };
    setTeam([...team, newMember]);
  };

  const handleRemoveMember = (id: string) => {
    setTeam(prevTeam => prevTeam.filter(m => m.id !== id));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeam(prevTeam => {
      const updatedTeam = [...prevTeam];
      const [movedMember] = updatedTeam.splice(fromIndex, 1);
      updatedTeam.splice(toIndex, 0, movedMember);
      return updatedTeam;
    });
  };

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  const handleExportCSV = () => {
    const headers = ['Employee Name', 'Date', 'Type', 'Day of Week'];
    const dataRows: { name: string; dateStr: string; label: string; dayOfWeek: string; sortDate: number }[] = [];

    (Object.entries(leaves) as [string, LeaveType][]).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;

      const dateStr = key.slice(-10);
      const idPart = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      if (y !== year) return;

      let name = 'Unknown';
      if (idPart === 'GLOBAL') {
        name = 'Axalta Holiday';
      } else {
        const member = team.find(t => t.id === idPart);
        if (!member) return;
        name = member.name;
      }

      const date = new Date(y, m - 1, d);
      const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'long' });
      const label = LEAVE_LABELS[type] || type;

      dataRows.push({
        name,
        dateStr,
        label,
        dayOfWeek,
        sortDate: date.getTime()
      });
    });

    dataRows.sort((a, b) => a.sortDate - b.sortDate || a.name.localeCompare(b.name));
    const escape = (str: string) => `"${str.replace(/"/g, '""')}"`;
    const rows = dataRows.map(row => 
      [escape(row.name), escape(row.dateStr), escape(row.label), escape(row.dayOfWeek)].join(',')
    );

    const csvContent = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `leave_plan_${year}.csv`;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handlePrevMonth = () => {
    if (activeMonthIndex === 0) {
      setActiveMonthIndex(11);
      setYear(y => y - 1);
    } else {
      setActiveMonthIndex(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (activeMonthIndex === 11) {
      setActiveMonthIndex(0);
      setYear(y => y + 1);
    } else {
      setActiveMonthIndex(prev => prev + 1);
    }
  };

  return (
    <div className="min-h-screen bg-t-main text-t-text pb-20 font-sans transition-colors duration-200">
      {/* Header */}
      <header className="bg-t-surface border-b border-t-border sticky top-0 z-30 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-1.5 rounded-lg text-white shadow-sm">
                <Calendar className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-t-text tracking-tight hidden sm:block">Team Planner</h1>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <ViewToggle viewMode={viewMode} onViewChange={setViewMode} />

            <button
              onClick={handleExportCSV}
              className="flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium text-t-muted hover:text-blue-500 hover:bg-t-hover border border-t-border transition-all shadow-sm"
              title="Export current year to CSV"
            >
              <Download className="w-4 h-4" />
              <span className="hidden sm:inline">Export</span>
            </button>

            <button
              onClick={toggleTheme}
              className="p-2 rounded-full text-t-muted hover:bg-t-hover transition-colors flex items-center justify-center w-9 h-9"
              title={`Theme: ${theme.charAt(0).toUpperCase() + theme.slice(1)}`}
            >
              {theme === 'light' && <Sun className="w-5 h-5" />}
              {theme === 'soft' && <Coffee className="w-5 h-5" />}
              {theme === 'dark' && <Moon className="w-5 h-5" />}
            </button>

            <div className="h-6 w-px bg-t-border"></div>
            <YearSelector year={year} onYearChange={setYear} />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Top Controls Area */}
        <div className="flex flex-col xl:flex-row xl:items-start justify-between gap-6 mb-8">
           {/* Paint Toolbar */}
           <div className="flex-1 min-w-0">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Management Tools */}
           <div className="flex flex-col sm:flex-row gap-3 flex-shrink-0">
             <TeamManager 
                team={team} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
                onReorderMembers={handleReorderMembers}
             />
             <Legend />
           </div>
        </div>

        {/* Tip Box */}
        {viewMode !== 'upcoming' && (
          <div className="mb-6 flex items-center gap-3 text-sm text-blue-800 dark:text-blue-300 bg-blue-50/50 dark:bg-blue-900/20 px-4 py-3 rounded-lg border border-blue-100 dark:border-blue-800">
             <span className="bg-blue-100 dark:bg-blue-800 text-blue-700 dark:text-blue-200 text-xs font-bold px-2 py-0.5 rounded">TIP</span>
             <span>Click on a day number (e.g., "01") in the header to toggle a global <b>Axalta Holiday</b>.</span>
          </div>
        )}

        {/* Calendar View Area */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">

          {viewMode === 'upcoming' ? (
             <UpcomingLeaves team={team} leaves={leaves} />
          ) : viewMode === 'year' ? (
            /* YEAR VIEW: Vertical Stack */
            <div className="space-y-8">
              {MONTHS.map((month, index) => (
                <MonthGrid
                  key={`${year}-${month}`}
                  year={year}
                  monthIndex={index}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              ))}
            </div>
          ) : (
            /* MONTH VIEW: Single Focused Card */
            <div className="bg-t-surface rounded-xl shadow-sm border border-t-border overflow-hidden min-h-[500px] flex flex-col transition-colors">
              {/* Custom Navigation Header for Single Month View */}
              <div className="bg-t-surface px-6 py-4 border-b border-t-border flex items-center justify-between sticky top-0 z-10 transition-colors">
                 <button 
                   onClick={handlePrevMonth}
                   className="p-2 hover:bg-t-hover rounded-full text-t-muted hover:text-blue-600 transition-colors"
                   title="Previous Month"
                 >
                   <ChevronLeft className="w-6 h-6" />
                 </button>

                 <div className="text-center">
                    <h2 className="text-2xl font-bold text-t-text">{MONTHS[activeMonthIndex]}</h2>
                    <p className="text-sm text-t-muted font-medium">{year}</p>
                 </div>

                 <button 
                   onClick={handleNextMonth}
                   className="p-2 hover:bg-t-hover rounded-full text-t-muted hover:text-blue-600 transition-colors"
                   title="Next Month"
                 >
                   <ChevronRight className="w-6 h-6" />
                 </button>
              </div>

              {/* Grid Container */}
              <div className="p-4 sm:p-6 bg-t-main flex-1 transition-colors">
                <MonthGrid
                  key={`${year}-${activeMonthIndex}`}
                  year={year}
                  monthIndex={activeMonthIndex}
                  team={team}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              </div>
            </div>
          )}

        </div>

        {/* Footer */}
        <div className="mt-16 pb-8 border-t border-t-border pt-8 flex flex-col items-center">
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 text-t-muted hover:text-red-500 transition-colors text-sm font-medium px-4 py-2 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
            >
                <RotateCcw className="w-4 h-4" />
                Reset Application Data
            </button>
            <p className="mt-2 text-xs text-t-muted">
              Data is stored locally in your browser.
            </p>
        </div>

      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { TeamMember, LeaveType, LeaveRecord } from '../types';
import { MONTHS, DAYS_OF_WEEK, LEAVE_COLORS, LEAVE_LABELS } from '../constants';
import { getDaysInMonth, isWeekend, getDayOfWeekIndex, generateLeaveKey, generateGlobalKey } from '../utils';
import { X, Check, Calendar, User, Palmtree, Eraser, Baby, CalendarDays, AlertTriangle, Plus, Trash2, CalendarPlus, Pencil, Save, Ban, UserPlus, Briefcase } from 'lucide-react';

interface Props {
  year: number;
  monthIndex: number;
  team: TeamMember[];
  leaves: LeaveRecord;
  currentTool: LeaveType | null;
  onToggleLeave: (key: string, type: LeaveType) => void;
}

export const MonthGrid: React.FC<Props> = ({ 
  year, 
  monthIndex, 
  team, 
  leaves, 
  currentTool,
  onToggleLeave 
}) => {
  const daysInMonth = getDaysInMonth(year, monthIndex);
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  const [hoveredCell, setHoveredCell] = useState<{
    x: number;
    y: number;
    memberId: string;
    day: number;
  } | null>(null);

  const [editingCell, setEditingCell] = useState<{
    memberId: string;
    day: number;
  } | null>(null);

  const [showConfirmClear, setShowConfirmClear] = useState(false);
  const [showHolidayManager, setShowHolidayManager] = useState(false);

  const [holidayStartDate, setHolidayStartDate] = useState('');
  const [holidayEndDate, setHolidayEndDate] = useState('');

  const [editingHolidayOriginalDate, setEditingHolidayOriginalDate] = useState<number | null>(null);
  const [editHolidayValue, setEditHolidayValue] = useState('');

  const [showLeaveManager, setShowLeaveManager] = useState(false);
  const [leaveMemberId, setLeaveMemberId] = useState('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.FULL_DAY);
  const [leaveStartDate, setLeaveStartDate] = useState('');
  const [leaveEndDate, setLeaveEndDate] = useState('');

  useEffect(() => {
    if (showLeaveManager && !leaveMemberId && team.length > 0) {
      setLeaveMemberId(team[0].id);
    }
  }, [showLeaveManager, team, leaveMemberId]);

  const getStatus = (userId: string, day: number) => {
    const userKey = generateLeaveKey(userId, year, monthIndex, day);
    const userStatus = leaves[userKey];

    const globalKey = generateGlobalKey(year, monthIndex, day);
    const isGlobalHoliday = leaves[globalKey] === LeaveType.HOLIDAY;

    if (isGlobalHoliday) return LeaveType.HOLIDAY;
    return userStatus || LeaveType.WORK;
  };

  const isGlobalHoliday = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    return leaves[key] === LeaveType.HOLIDAY;
  };

  const handleDayHeaderClick = (day: number) => {
    const key = generateGlobalKey(year, monthIndex, day);
    const current = leaves[key];
    onToggleLeave(key, current === LeaveType.HOLIDAY ? LeaveType.WORK : LeaveType.HOLIDAY);
  };

  const handleMouseEnter = (e: React.MouseEvent, memberId: string, day: number) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setHoveredCell({
        x: rect.left + rect.width / 2,
        y: rect.top,
        memberId,
        day
    });
  };

  const handleCellClick = (memberId: string, day: number) => {
    if (currentTool === null) {
        setEditingCell({ memberId, day });
    } else {
        const key = generateLeaveKey(memberId, year, monthIndex, day);
        const currentStatus = leaves[key];

        if (currentTool === LeaveType.WORK && currentStatus) {
            setEditingCell({ memberId, day });
            setShowConfirmClear(true);
            return;
        }

        onToggleLeave(key, currentTool);
    }
  };

  const handleSelectLeaveFromModal = (type: LeaveType) => {
    if (!editingCell) return;

    const userKey = generateLeaveKey(editingCell.memberId, year, monthIndex, editingCell.day);
    const hasUserLeave = leaves[userKey] !== undefined;

    if (type === LeaveType.WORK && hasUserLeave) {
        setShowConfirmClear(true);
        return;
    }

    const key = generateLeaveKey(editingCell.memberId, year, monthIndex, editingCell.day);
    onToggleLeave(key, type);
    setEditingCell(null);
  };

  const confirmClear = () => {
    if (!editingCell) return;
    const key = generateLeaveKey(editingCell.memberId, year, monthIndex, editingCell.day);
    onToggleLeave(key, LeaveType.WORK);
    setShowConfirmClear(false);
    setEditingCell(null);
  };

  const cancelClear = () => {
    setShowConfirmClear(false);
  };

  const handleAddHolidayRange = (e: React.FormEvent) => {
    e.preventDefault();
    if (!holidayStartDate) return;
    const start = new Date(holidayStartDate);
    const end = holidayEndDate ? new Date(holidayEndDate) : new Date(holidayStartDate);
    if (end < start) {
        alert("End date cannot be before start date");
        return;
    }
    const current = new Date(start);
    while (current <= end) {
        const key = generateGlobalKey(current.getFullYear(), current.getMonth(), current.getDate());
        onToggleLeave(key, LeaveType.HOLIDAY);
        current.setDate(current.getDate() + 1);
    }
    setHolidayStartDate('');
    setHolidayEndDate('');
  };

  const handleStartEditHoliday = (day: number) => {
    setEditingHolidayOriginalDate(day);
    const dateStr = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    setEditHolidayValue(dateStr);
  };

  const handleSaveEditHoliday = () => {
    if (editingHolidayOriginalDate === null || !editHolidayValue) return;
    const [y, m, d] = editHolidayValue.split('-').map(Number);
    if (isNaN(y) || isNaN(m) || isNaN(d)) return;
    const oldKey = generateGlobalKey(year, monthIndex, editingHolidayOriginalDate);
    onToggleLeave(oldKey, LeaveType.WORK);
    const newKey = generateGlobalKey(y, m - 1, d);
    onToggleLeave(newKey, LeaveType.HOLIDAY);
    setEditingHolidayOriginalDate(null);
    setEditHolidayValue('');
  };

  const handleCancelEdit = () => {
    setEditingHolidayOriginalDate(null);
    setEditHolidayValue('');
    setHolidayStartDate('');
    setHolidayEndDate('');
  };

  const handleRemoveHoliday = (day: number) => {
    if (editingHolidayOriginalDate === day) handleCancelEdit();
    const key = generateGlobalKey(year, monthIndex, day);
    onToggleLeave(key, LeaveType.WORK);
  };

  const handleAddLeaveRange = (e: React.FormEvent) => {
    e.preventDefault();
    if (!leaveMemberId || !leaveStartDate) return;
    const start = new Date(leaveStartDate);
    const end = leaveEndDate ? new Date(leaveEndDate) : new Date(leaveStartDate);
    if (end < start) {
        alert("End date cannot be before start date");
        return;
    }
    if (start.getFullYear() !== year || start.getMonth() !== monthIndex) {
        alert(`Start date must be within ${MONTHS[monthIndex]} ${year}`);
        return;
    }
    const current = new Date(start);
    while (current <= end) {
        const key = generateLeaveKey(leaveMemberId, current.getFullYear(), current.getMonth(), current.getDate());
        onToggleLeave(key, leaveType);
        current.setDate(current.getDate() + 1);
    }
    setLeaveStartDate('');
    setLeaveEndDate('');
  };

  const handleRemoveMemberLeave = (day: number) => {
    if (!leaveMemberId) return;
    const key = generateLeaveKey(leaveMemberId, year, monthIndex, day);
    onToggleLeave(key, LeaveType.WORK);
  };

  const getMemberLeavesInMonth = (memberId: string) => {
      if (!memberId) return [];
      return daysArray.filter(day => {
          const key = generateLeaveKey(memberId, year, monthIndex, day);
          const val = leaves[key];
          return val && val !== LeaveType.WORK;
      });
  };

  const getLeaveIcon = (type: LeaveType) => {
      switch(type) {
          case LeaveType.FULL_DAY: return <Palmtree className="w-4 h-4" />;
          case LeaveType.HALF_DAY: return <div className="w-4 h-4 rounded-full bg-gradient-to-r from-red-400 to-white border border-gray-300"></div>;
          case LeaveType.HOLIDAY: return <CalendarDays className="w-4 h-4" />;
          case LeaveType.OTHER: return <Baby className="w-4 h-4" />;
          case LeaveType.WORK: return <Eraser className="w-4 h-4" />;
          default: return <Check className="w-4 h-4" />;
      }
  };

  const currentMonthHolidays = daysArray.filter(day => isGlobalHoliday(day));

  return (
    <div className="mb-8 bg-t-surface shadow-sm border border-t-border rounded-lg overflow-hidden transition-colors">
      <div className="bg-t-hover px-4 py-2 border-b border-t-border flex justify-between items-center transition-colors">
        <span className="font-bold text-t-text uppercase tracking-wider">
          {MONTHS[monthIndex]}
        </span>
        <div className="flex items-center gap-2">
            <button
            onClick={() => setShowLeaveManager(true)}
            className="flex items-center gap-1.5 text-xs font-medium text-green-600 dark:text-green-400 hover:text-green-800 dark:hover:text-green-300 bg-green-50 dark:bg-green-900/30 hover:bg-green-100 dark:hover:bg-green-900/50 px-2 py-1 rounded transition-colors"
            >
            <UserPlus className="w-3.5 h-3.5" />
            Add Leave
            </button>
            <button
            onClick={() => {
                setShowHolidayManager(true);
                handleCancelEdit();
            }}
            className="flex items-center gap-1.5 text-xs font-medium text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 bg-blue-50 dark:bg-blue-900/30 hover:bg-blue-100 dark:hover:bg-blue-900/50 px-2 py-1 rounded transition-colors"
            >
            <CalendarPlus className="w-3.5 h-3.5" />
            Manage Holidays
            </button>
        </div>
      </div>

      <div className="overflow-x-auto hide-scrollbar">
        <div className="inline-block min-w-full">
          <div className="flex border-b border-t-border">
            <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-t-hover border-r border-t-border p-2 font-medium text-xs text-t-muted transition-colors">
              Employee
            </div>

            {daysArray.map(day => {
               const isWE = isWeekend(year, monthIndex, day);
               const isHoliday = isGlobalHoliday(day);
               const dayName = DAYS_OF_WEEK[getDayOfWeekIndex(year, monthIndex, day)];

               return (
                <div 
                  key={day} 
                  onClick={() => handleDayHeaderClick(day)}
                  className={`
                    w-8 flex-shrink-0 text-center border-r border-t-border last:border-r-0 cursor-pointer transition-colors
                    ${isWE 
                      ? 'bg-t-weekend hover:bg-t-border' 
                      : isHoliday 
                        ? 'bg-yellow-100 dark:bg-yellow-900/30 hover:bg-yellow-200 dark:hover:bg-yellow-900/50' 
                        : 'bg-t-surface hover:bg-t-hover'}
                  `}
                  title="Click to toggle Global Axalta Holiday"
                >
                  <div className={`text-xs font-bold p-1 ${
                      isHoliday ? 'text-yellow-700 dark:text-yellow-500' : 
                      isWE ? 'text-t-muted' : 'text-t-text'
                  }`}>{day}</div>
                  <div className="text-[10px] text-t-muted font-medium pb-1">{dayName}</div>
                </div>
              );
            })}
          </div>

          {team.map(member => (
            <div key={member.id} className="flex border-b border-t-border last:border-b-0 hover:bg-t-main transition-colors">
              <div className="sticky left-0 z-10 w-40 flex-shrink-0 bg-t-surface border-r border-t-border p-2 flex items-center transition-colors">
                <span className="text-sm font-medium text-t-text truncate" title={member.name}>
                  {member.name}
                </span>
              </div>

              {daysArray.map(day => {
                const status = getStatus(member.id, day);
                const isWE = isWeekend(year, monthIndex, day);
                const bgClass = status !== LeaveType.WORK 
                  ? LEAVE_COLORS[status] 
                  : isWE 
                    ? 'bg-t-weekend' 
                    : 'bg-t-surface';

                return (
                  <div
                    key={day}
                    className={`
                      w-8 h-10 flex-shrink-0 border-r border-t-border last:border-r-0 cursor-pointer
                      transition-all duration-75 relative
                      ${bgClass}
                      hover:brightness-90 dark:hover:brightness-110
                    `}
                    onClick={() => handleCellClick(member.id, day)}
                    onMouseEnter={(e) => handleMouseEnter(e, member.id, day)}
                    onMouseLeave={() => setHoveredCell(null)}
                  >
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>

      {hoveredCell && !editingCell && createPortal(
         (() => {
           const member = team.find(m => m.id === hoveredCell.memberId);
           if (!member) return null;
           const status = getStatus(hoveredCell.memberId, hoveredCell.day);
           const label = LEAVE_LABELS[status];
           return (
              <div 
                  className="fixed z-50 px-3 py-2 bg-gray-900/95 dark:bg-gray-700/95 text-white text-xs rounded shadow-xl pointer-events-none backdrop-blur-sm whitespace-nowrap"
                  style={{ left: hoveredCell.x, top: hoveredCell.y, transform: 'translate(-50%, -125%)' }}
              >
                  <div className="font-bold mb-0.5">{member.name}</div>
                  <div className="font-light text-gray-200">{label}</div>
                  <div className="absolute bottom-0 left-1/2 transform -translate-x-1/2 translate-y-full border-4 border-transparent border-t-gray-900/95 dark:border-t-gray-700/95"></div>
              </div>
           );
         })(),
         document.body
      )}

      {editingCell && createPortal(
          (() => {
            const member = team.find(m => m.id === editingCell.memberId);
            if (!member) return null;
            const currentStatus = getStatus(editingCell.memberId, editingCell.day);
            const dateStr = `${MONTHS[monthIndex]} ${editingCell.day}, ${year}`;
            const options = [
               { type: LeaveType.FULL_DAY },
               { type: LeaveType.HALF_DAY },
               { type: LeaveType.HOLIDAY },
               { type: LeaveType.OTHER },
               { type: LeaveType.WORK },
            ];

            return (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-t-surface rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100 ring-1 ring-t-border">
                        <div className="bg-t-hover px-6 py-4 border-b border-t-border flex justify-between items-start">
                            <div>
                                <div className="flex items-center gap-2 text-t-muted text-xs font-bold uppercase tracking-wider mb-1">
                                    <Calendar className="w-3 h-3" />
                                    {dateStr}
                                </div>
                                <h3 className="text-lg font-bold text-t-text flex items-center gap-2">
                                    <User className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                                    {member.name}
                                </h3>
                            </div>
                            <button onClick={() => setEditingCell(null)} className="text-t-muted hover:text-t-text p-1 hover:bg-t-border rounded-full transition-colors">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="p-6 space-y-3">
                            <p className="text-sm text-t-muted mb-4">Select the leave status for this day:</p>
                            {options.map((opt) => {
                                const isSelected = currentStatus === opt.type;
                                return (
                                    <button
                                        key={opt.type}
                                        onClick={() => handleSelectLeaveFromModal(opt.type)}
                                        className={`
                                            w-full flex items-center justify-between p-3 rounded-lg border transition-all
                                            ${isSelected 
                                                ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-500 ring-1 ring-blue-500 text-blue-700 dark:text-blue-300' 
                                                : 'bg-t-surface border-t-border hover:bg-t-hover hover:border-t-text text-t-text'}
                                        `}
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className={`w-8 h-8 rounded-full flex items-center justify-center ${opt.type === LeaveType.WORK ? 'bg-t-hover text-t-muted' : 'bg-t-surface shadow-sm border border-t-border text-t-text'}`}>
                                                {getLeaveIcon(opt.type)}
                                            </div>
                                            <span className="font-medium">{LEAVE_LABELS[opt.type]}</span>
                                        </div>
                                        {isSelected && <Check className="w-5 h-5 text-blue-600 dark:text-blue-400" />}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                </div>
            );
          })(),
          document.body
      )}

      {showHolidayManager && createPortal(
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-t-surface rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100 ring-1 ring-t-border">
                <div className="bg-yellow-50 dark:bg-yellow-900/20 px-6 py-4 border-b border-yellow-100 dark:border-yellow-900/30 flex justify-between items-center">
                    <h3 className="text-lg font-bold text-yellow-800 dark:text-yellow-500 flex items-center gap-2">
                        <CalendarDays className="w-5 h-5" />
                        Manage Holidays
                    </h3>
                    <button onClick={() => { setShowHolidayManager(false); handleCancelEdit(); }} className="text-yellow-800/50 hover:text-yellow-800 p-1 hover:bg-yellow-100 rounded-full transition-colors">
                        <X className="w-5 h-5" />
                    </button>
                </div>
                <div className="p-6">
                    <p className="text-sm text-t-muted mb-4">
                        Add or remove Axalta Holidays for {MONTHS[monthIndex]} {year}.
                    </p>
                    <form onSubmit={handleAddHolidayRange} className="flex flex-col gap-2 mb-6">
                        <div className="flex gap-2 items-center">
                            <div className="flex-1">
                                <label className="text-[10px] uppercase font-bold text-t-muted mb-0.5 block">Start</label>
                                <input type="date" required value={holidayStartDate} onChange={(e) => setHolidayStartDate(e.target.value)} className="w-full px-3 py-2 border border-t-border bg-t-surface text-t-text rounded-lg text-sm focus:ring-2 focus:ring-yellow-500 outline-none" />
                            </div>
                            <div className="flex-1">
                                <label className="text-[10px] uppercase font-bold text-t-muted mb-0.5 block">End <span className="font-normal normal-case opacity-50">(Optional)</span></label>
                                <input type="date" min={holidayStartDate} value={holidayEndDate} onChange={(e) => setHolidayEndDate(e.target.value)} placeholder="Same as start" className="w-full px-3 py-2 border border-t-border bg-t-surface text-t-text rounded-lg text-sm focus:ring-2 focus:ring-yellow-500 outline-none" />
                            </div>
                        </div>
                        <button type="submit" className="w-full bg-yellow-500 hover:bg-yellow-600 text-white px-3 py-2 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm font-medium mt-1">
                            <Plus className="w-4 h-4" /> Add Holiday(s)
                        </button>
                    </form>
                    <div className="border-t border-t-border pt-4">
                        <h4 className="text-xs font-bold text-t-muted uppercase tracking-wider mb-3">Scheduled Holidays ({currentMonthHolidays.length})</h4>
                        <div className="space-y-2 max-h-40 overflow-y-auto pr-2 hide-scrollbar">
                            {currentMonthHolidays.length === 0 ? (
                                <p className="text-sm text-t-muted italic">No holidays set for this month.</p>
                            ) : (
                                currentMonthHolidays.map(day => (
                                    <div key={day} className={`flex items-center justify-between p-2 rounded border transition-colors ${editingHolidayOriginalDate === day ? 'bg-yellow-50 border-yellow-200 ring-1 ring-yellow-400' : 'bg-yellow-50/50 border-yellow-100'}`}>
                                        {editingHolidayOriginalDate === day ? (
                                            <div className="flex items-center gap-2 w-full">
                                                <input type="date" value={editHolidayValue} onChange={(e) => setEditHolidayValue(e.target.value)} className="flex-1 px-2 py-1 text-sm border border-t-border bg-t-surface text-t-text rounded outline-none focus:ring-1 focus:ring-yellow-500" />
                                                <div className="flex items-center gap-1">
                                                    <button onClick={handleSaveEditHoliday} className="p-1.5 bg-green-500 hover:bg-green-600 text-white rounded transition-colors" title="Save"><Check className="w-3.5 h-3.5" /></button>
                                                    <button onClick={handleCancelEdit} className="p-1.5 bg-gray-200 hover:bg-gray-300 text-gray-600 rounded transition-colors" title="Cancel"><X className="w-3.5 h-3.5" /></button>
