import React, { useMemo, useState } from 'react';
import { TeamMember, LeaveRecord, LeaveType } from '../types';
import { LEAVE_LABELS, LEAVE_COLORS } from '../constants';
import { Calendar, User, ArrowRight, Palmtree, Baby, CalendarDays, Filter, Check } from 'lucide-react';

interface Props {
  team: TeamMember[];
  leaves: LeaveRecord;
}

interface LeaveRange {
  memberId: string;
  memberName: string;
  type: LeaveType;
  startDate: Date;
  endDate: Date;
  days: number;
}

export const UpcomingLeaves: React.FC<Props> = ({ team, leaves }) => {
  // Filter State
  const [activeFilters, setActiveFilters] = useState<LeaveType[]>([
    LeaveType.FULL_DAY,
    LeaveType.HALF_DAY,
    LeaveType.HOLIDAY,
    LeaveType.OTHER
  ]);

  const toggleFilter = (type: LeaveType) => {
    setActiveFilters(prev => 
      prev.includes(type) 
        ? prev.filter(t => t !== type) 
        : [...prev, type]
    );
  };

  const upcomingRanges = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const events: { date: Date; memberId: string; type: LeaveType }[] = [];

    (Object.entries(leaves) as [string, LeaveType][]).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;

      // Filter Logic
      if (!activeFilters.includes(type)) return;

      if (key.startsWith('GLOBAL_')) return;

      const dateStr = key.slice(-10);
      const memberId = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      const date = new Date(y, m - 1, d);

      if (date >= today) {
        events.push({ date, memberId, type });
      }
    });

    events.sort((a, b) => {
      if (a.memberId !== b.memberId) return a.memberId.localeCompare(b.memberId);
      return a.date.getTime() - b.date.getTime();
    });

    const ranges: LeaveRange[] = [];
    let currentRange: LeaveRange | null = null;

    events.forEach((event) => {
      const member = team.find(t => t.id === event.memberId);
      if (!member) return;

      const isConsecutive = currentRange && 
        currentRange.memberId === event.memberId &&
        currentRange.type === event.type &&
        event.date.getTime() === currentRange.endDate.getTime() + 86400000;

      if (isConsecutive && currentRange) {
        currentRange.endDate = event.date;
        currentRange.days += 1;
      } else {
        if (currentRange) ranges.push(currentRange);

        currentRange = {
          memberId: event.memberId,
          memberName: member.name,
          type: event.type,
          startDate: event.date,
          endDate: event.date,
          days: 1
        };
      }
    });

    if (currentRange) ranges.push(currentRange);
    return ranges.sort((a, b) => a.startDate.getTime() - b.startDate.getTime());
  }, [team, leaves, activeFilters]);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', weekday: 'short' });
  };

  const getIcon = (type: LeaveType) => {
    switch(type) {
        case LeaveType.FULL_DAY: return <Palmtree className="w-4 h-4" />;
        case LeaveType.HALF_DAY: return <div className="w-4 h-4 rounded-full bg-gradient-to-r from-red-400 to-white border border-gray-300"></div>;
        case LeaveType.HOLIDAY: return <CalendarDays className="w-4 h-4" />;
        case LeaveType.OTHER: return <Baby className="w-4 h-4" />;
        default: return <Calendar className="w-4 h-4" />;
    }
  };

  const getFilterButtonClass = (type: LeaveType) => {
    const isActive = activeFilters.includes(type);
    const baseClass = "flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium border transition-all cursor-pointer select-none";

    if (!isActive) {
        return `${baseClass} bg-t-main text-t-muted border-t-border hover:bg-t-hover opacity-60`;
    }

    switch (type) {
        case LeaveType.FULL_DAY: return `${baseClass} bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800 ring-1 ring-red-500/20`;
        case LeaveType.HALF_DAY: return `${baseClass} bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-300 dark:border-orange-800 ring-1 ring-orange-500/20`;
        case LeaveType.HOLIDAY: return `${baseClass} bg-yellow-50 text-yellow-700 border-yellow-200 dark:bg-yellow-900/20 dark:text-yellow-300 dark:border-yellow-800 ring-1 ring-yellow-500/20`;
        case LeaveType.OTHER: return `${baseClass} bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 ring-1 ring-blue-500/20`;
        default: return `${baseClass} bg-gray-100 text-gray-700`;
    }
  };

  const filterOptions = [
    { type: LeaveType.FULL_DAY, label: 'Vacation' },
    { type: LeaveType.HALF_DAY, label: 'Half Day' },
    { type: LeaveType.HOLIDAY, label: 'Holidays' },
    { type: LeaveType.OTHER, label: 'Other' },
  ];

  const groupedByMonth = upcomingRanges.reduce((acc, range) => {
    const key = range.startDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    if (!acc[key]) acc[key] = [];
    acc[key].push(range);
    return acc;
  }, {} as Record<string, LeaveRange[]>);

  return (
    <div className="max-w-3xl mx-auto">
      {/* Filter Bar */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 mb-6 bg-t-surface p-4 rounded-xl border border-t-border shadow-sm animate-in fade-in slide-in-from-top-2 duration-500">
         <div className="flex items-center gap-2 text-t-muted text-sm font-medium">
            <Filter className="w-4 h-4" />
            <span>Filter:</span>
         </div>
         <div className="flex flex-wrap gap-2">
            {filterOptions.map(opt => (
                <button
                    key={opt.type}
                    onClick={() => toggleFilter(opt.type)}
                    className={getFilterButtonClass(opt.type)}
                >
                    {activeFilters.includes(opt.type) && <Check className="w-3 h-3" />}
                    {opt.label}
                </button>
            ))}
         </div>
      </div>

      {upcomingRanges.length === 0 ? (
        <div className="bg-t-surface rounded-xl shadow-sm border border-t-border p-12 text-center transition-colors animate-in fade-in duration-500">
          <div className="bg-green-50 dark:bg-green-900/20 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
            <Calendar className="w-8 h-8 text-green-600 dark:text-green-400" />
          </div>
          <h3 className="text-lg font-bold text-t-text mb-2">No upcoming leaves found</h3>
          <p className="text-t-muted">Try adjusting your filters or checking different dates.</p>
        </div>
      ) : (
        <div className="space-y-8">
          {(Object.entries(groupedByMonth) as [string, LeaveRange[]][]).map(([month, ranges]) => (
            <div key={month} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
              <h3 className="text-sm font-bold text-t-muted uppercase tracking-wider mb-4 pl-1">{month}</h3>
              <div className="bg-t-surface rounded-xl shadow-sm border border-t-border overflow-hidden divide-y divide-t-border transition-colors">
                {ranges.map((range, idx) => (
                  <div key={`${range.memberId}-${range.startDate.getTime()}`} className="p-4 hover:bg-t-hover transition-colors flex items-center gap-4 group">
                    <div className="w-10 h-10 rounded-full bg-t-main flex items-center justify-center text-t-muted font-bold text-sm shadow-inner shrink-0">
                      {range.memberName.substring(0, 2).toUpperCase()}
                    </div>

                    <div className="flex-1 min-w-0 grid sm:grid-cols-2 gap-2 sm:gap-4 items-center">
                       <div>
                          <div className="font-semibold text-t-text truncate">{range.memberName}</div>
                          <div className="text-xs text-t-muted flex items-center gap-1.5 mt-0.5">
                            <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium uppercase tracking-wide border ${LEAVE_COLORS[range.type].includes('bg-white') ? 'bg-t-hover text-t-muted border-t-border' : 'bg-opacity-10 text-t-text border-transparent'} `} 
                               style={{ 
                                   backgroundColor: range.type === LeaveType.FULL_DAY ? 'rgba(254, 242, 242, 1)' : 
                                                    range.type === LeaveType.OTHER ? 'rgba(239, 246, 255, 1)' : undefined,
                                   color: range.type === LeaveType.FULL_DAY ? '#991b1b' :
                                          range.type === LeaveType.OTHER ? '#1e40af' : undefined
                               }}>
                                {getIcon(range.type)}
                                {LEAVE_LABELS[range.type]}
                            </span>
                          </div>
                       </div>

                       <div className="flex items-center gap-3 text-sm text-t-text sm:justify-end">
                          <div className="flex flex-col sm:items-end">
                            <div className="flex items-center gap-2 font-medium">
                                <span>{formatDate(range.startDate)}</span>
                                {range.days > 1 && (
                                    <>
                                        <ArrowRight className="w-3 h-3 text-t-muted" />
                                        <span>{formatDate(range.endDate)}</span>
                                    </>
                                )}
                            </div>
                            <span className="text-xs text-t-muted">
                                {range.days} {range.days === 1 ? 'day' : 'days'}
                            </span>
                          </div>
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export enum LeaveType {
  FULL_DAY = 'FULL_DAY',
  HALF_DAY = 'HALF_DAY',
  HOLIDAY = 'HOLIDAY', // Company Holiday
  OTHER = 'OTHER', // Paternity, Sick, etc.
  WORK = 'WORK' // Standard work day (clears selection)
}

export interface TeamMember {
  id: string;
  name: string;
}

export interface Team {
  id: string;
  name: string;
  members: TeamMember[];
}

export interface LeaveRecord {
  // Key format: "userId_YYYY-MM-DD" or "GLOBAL_YYYY-MM-DD" for holidays
  [key: string]: LeaveType;
}

export interface AppState {
  teams: Team[];
  activeTeamId: string;
  leaves: LeaveRecord;
  year: number;
}

export type ViewMode = 'month' | 'year' | 'upcoming';

import React, { useState, useRef, useEffect } from 'react';
import { Team } from '../types';
import { Plus, X, Edit2, Check, Users } from 'lucide-react';

interface Props {
  teams: Team[];
  activeTeamId: string;
  onSwitch: (id: string) => void;
  onAdd: () => void;
  onRename: (id: string, newName: string) => void;
  onDelete: (id: string) => void;
}

export const TeamTabs: React.FC<Props> = ({ 
  teams, 
  activeTeamId, 
  onSwitch, 
  onAdd, 
  onRename, 
  onDelete 
}) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingId && inputRef.current) {
      inputRef.current.focus();
    }
  }, [editingId]);

  const startEditing = (team: Team, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(team.id);
    setEditName(team.name);
  };

  const saveEdit = () => {
    if (editingId && editName.trim()) {
      onRename(editingId, editName.trim());
    }
    setEditingId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      saveEdit();
    } else if (e.key === 'Escape') {
      setEditingId(null);
    }
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to delete this team? All configured members will be hidden from view (leaves are preserved if you add them back later).')) {
      onDelete(id);
    }
  };

  return (
    <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-2 hide-scrollbar">
      {teams.map(team => {
        const isActive = team.id === activeTeamId;
        const isEditing = editingId === team.id;

        return (
          <div
            key={team.id}
            onClick={() => !isEditing && onSwitch(team.id)}
            className={`
              group relative flex items-center gap-2 px-4 py-2 rounded-t-lg border-b-2 transition-all cursor-pointer min-w-[140px] max-w-[240px]
              ${isActive 
                ? 'border-blue-500 bg-t-surface text-blue-600 dark:text-blue-400 font-bold shadow-sm' 
                : 'border-transparent text-t-muted hover:text-t-text hover:bg-t-hover'}
            `}
          >
            {isEditing ? (
              <div className="flex items-center gap-1 w-full">
                <input
                  ref={inputRef}
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
                  onBlur={saveEdit}
                  onKeyDown={handleKeyDown}
                  className="w-full bg-t-main px-1 py-0.5 text-sm rounded outline-none border border-blue-400 text-t-text"
                  onClick={(e) => e.stopPropagation()}
                />
                <button onMouseDown={saveEdit} className="text-green-600 hover:text-green-700">
                    <Check className="w-3 h-3" />
                </button>
              </div>
            ) : (
              <>
                <Users className={`w-4 h-4 ${isActive ? 'opacity-100' : 'opacity-50'}`} />
                <span className="truncate text-sm flex-1">{team.name}</span>

                {isActive && (
                  <div className="flex items-center gap-1 ml-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button 
                      onClick={(e) => startEditing(team, e)}
                      className="p-1 hover:bg-blue-100 dark:hover:bg-blue-900/30 rounded text-blue-500"
                      title="Rename Team"
                    >
                      <Edit2 className="w-3 h-3" />
                    </button>
                    {teams.length > 1 && (
                      <button 
                        onClick={(e) => handleDelete(team.id, e)}
                        className="p-1 hover:bg-red-100 dark:hover:bg-red-900/30 rounded text-red-500"
                        title="Delete Team"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                )}
              </>
            )}
          </div>
        );
      })}

      <button
        onClick={onAdd}
        className="flex items-center gap-1 px-3 py-2 text-sm font-medium text-t-muted hover:text-blue-600 hover:bg-t-hover rounded-lg transition-colors border border-transparent border-dashed hover:border-blue-300"
        title="Create new team"
      >
        <Plus className="w-4 h-4" />
        New Team
      </button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { Legend } from './components/Legend';
import { YearSelector } from './components/YearSelector';
import { ViewToggle } from './components/ViewToggle';
import { UpcomingLeaves } from './components/UpcomingLeaves';
import { TeamTabs } from './components/TeamTabs';
import { LeaveType, TeamMember, Team, LeaveRecord, ViewMode } from './types';
import { MONTHS, LEAVE_LABELS } from './constants';
import { Calendar, RotateCcw, ChevronLeft, ChevronRight, Download, Moon, Sun, Coffee } from 'lucide-react';

const STORAGE_KEY = 'vacation_planner_v2';
const THEME_KEY = 'vacation_planner_theme_v2';

// Initial Data
const DEFAULT_TEAM_ID = 'default';
const INITIAL_TEAMS: Team[] = [
  { 
    id: DEFAULT_TEAM_ID, 
    name: 'General', 
    members: [
      { id: '1', name: 'Diego' },
      { id: '2', name: 'Lukas' },
      { id: '3', name: 'Pablo' },
    ] 
  }
];

type ThemeMode = 'light' | 'soft' | 'dark';

const App: React.FC = () => {
  // State
  const [year, setYear] = useState(2026);
  const [teams, setTeams] = useState<Team[]>(INITIAL_TEAMS);
  const [activeTeamId, setActiveTeamId] = useState<string>(DEFAULT_TEAM_ID);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [currentTool, setCurrentTool] = useState<LeaveType | null>(null);
  const [isClient, setIsClient] = useState(false);
  const [theme, setTheme] = useState<ThemeMode>('light');
  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [activeMonthIndex, setActiveMonthIndex] = useState(new Date().getMonth());

  // Derived State
  const activeTeam = teams.find(t => t.id === activeTeamId) || teams[0];

  // Load from local storage with Migration Logic
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);

        if (parsed.leaves) setLeaves(parsed.leaves);
        if (parsed.year) setYear(parsed.year);

        // Migration: Check if we have 'teams' array, otherwise migrate 'team' array
        if (parsed.teams && Array.isArray(parsed.teams)) {
          setTeams(parsed.teams);
          if (parsed.activeTeamId) setActiveTeamId(parsed.activeTeamId);
        } else if (parsed.team && Array.isArray(parsed.team)) {
          // Legacy format migration
          const migratedTeam: Team = {
            id: DEFAULT_TEAM_ID,
            name: 'General',
            members: parsed.team
          };
          setTeams([migratedTeam]);
          setActiveTeamId(DEFAULT_TEAM_ID);
        }

      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }

    // Load theme
    const savedTheme = localStorage.getItem(THEME_KEY) as ThemeMode;
    if (['light', 'soft', 'dark'].includes(savedTheme)) {
      setTheme(savedTheme);
    } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme('dark');
    }

    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      teams, 
      activeTeamId, 
      leaves, 
      year 
    }));
  }, [teams, activeTeamId, leaves, year, isClient]);

  // Handle Theme Change
  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('dark', 'theme-soft');
    if (theme === 'dark') root.classList.add('dark');
    else if (theme === 'soft') root.classList.add('theme-soft');
    localStorage.setItem(THEME_KEY, theme);
  }, [theme]);

  const toggleTheme = () => {
    const cycle: Record<ThemeMode, ThemeMode> = {
      'light': 'soft',
      'soft': 'dark',
      'dark': 'light'
    };
    setTheme(prev => cycle[prev]);
  };

  // --- Team Management ---

  const handleAddTeam = () => {
    const newId = crypto.randomUUID ? crypto.randomUUID() : Date.now().toString();
    const newTeam: Team = {
      id: newId,
      name: `New Team`,
      members: []
    };
    setTeams([...teams, newTeam]);
    setActiveTeamId(newId);
  };

  const handleRenameTeam = (id: string, newName: string) => {
    setTeams(teams.map(t => t.id === id ? { ...t, name: newName } : t));
  };

  const handleDeleteTeam = (id: string) => {
    if (teams.length <= 1) return; // Prevent deleting last team

    const newTeams = teams.filter(t => t.id !== id);
    setTeams(newTeams);

    // If we deleted the active team, switch to the first one available
    if (activeTeamId === id) {
      setActiveTeamId(newTeams[0].id);
    }
  };

  // --- Member Management (Scoped to Active Team) ---

  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };

    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        return { ...t, members: [...t.members, newMember] };
      }
      return t;
    }));
  };

  const handleRemoveMember = (id: string) => {
    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        return { ...t, members: t.members.filter(m => m.id !== id) };
      }
      return t;
    }));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        const updatedMembers = [...t.members];
        const [movedMember] = updatedMembers.splice(fromIndex, 1);
        updatedMembers.splice(toIndex, 0, movedMember);
        return { ...t, members: updatedMembers };
      }
      return t;
    }));
  };

  // --- Leave Management ---

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  const handleExportCSV = () => {
    const headers = ['Team', 'Employee Name', 'Date', 'Type', 'Day of Week'];
    const dataRows: { teamName: string; name: string; dateStr: string; label: string; dayOfWeek: string; sortDate: number }[] = [];

    (Object.entries(leaves) as [string, LeaveType][]).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;

      const dateStr = key.slice(-10);
      const idPart = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      if (y !== year) return;

      let name = 'Unknown';
      let teamName = '-';

      if (idPart === 'GLOBAL') {
        name = 'Axalta Holiday';
        teamName = 'All';
      } else {
        // Search across all teams
        let found = false;
        for (const t of teams) {
          const member = t.members.find(m => m.id === idPart);
          if (member) {
            name = member.name;
            teamName = t.name;
            found = true;
            break;
          }
        }
        if (!found) return; // Member might have been deleted
      }

      const date = new Date(y, m - 1, d);
      const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'long' });
      const label = LEAVE_LABELS[type] || type;

      dataRows.push({
        teamName,
        name,
        dateStr,
        label,
        dayOfWeek,
        sortDate: date.getTime()
      });
    });

    dataRows.sort((a, b) => a.sortDate - b.sortDate || a.teamName.localeCompare(b.teamName) || a.name.localeCompare(b.name));
    const escape = (str: string) => `"${str.replace(/"/g, '""')}"`;
    const rows = dataRows.map(row => 
      [escape(row.teamName), escape(row.name), escape(row.dateStr), escape(row.label), escape(row.dayOfWeek)].join(',')
    );

    const csvContent = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `leave_plan_${year}.csv`;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handlePrevMonth = () => {
    if (activeMonthIndex === 0) {
      setActiveMonthIndex(11);
      setYear(y => y - 1);
    } else {
      setActiveMonthIndex(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (activeMonthIndex === 11) {
      setActiveMonthIndex(0);
      setYear(y => y + 1);
    } else {
      setActiveMonthIndex(prev => prev + 1);
    }
  };

  return (
    <div className="min-h-screen bg-t-main text-t-text pb-20 font-sans transition-colors duration-200">
      {/* Header */}
      <header className="bg-t-surface border-b border-t-border sticky top-0 z-30 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-1.5 rounded-lg text-white shadow-sm">
                <Calendar className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-t-text tracking-tight hidden sm:block">Team Planner</h1>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <ViewToggle viewMode={viewMode} onViewChange={setViewMode} />

            <button
              onClick={handleExportCSV}
              className="flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium text-t-muted hover:text-blue-500 hover:bg-t-hover border border-t-border transition-all shadow-sm"
              title="Export current year to CSV"
            >
              <Download className="w-4 h-4" />
              <span className="hidden sm:inline">Export</span>
            </button>

            <button
              onClick={toggleTheme}
              className="p-2 rounded-full text-t-muted hover:bg-t-hover transition-colors flex items-center justify-center w-9 h-9"
              title={`Theme: ${theme.charAt(0).toUpperCase() + theme.slice(1)}`}
            >
              {theme === 'light' && <Sun className="w-5 h-5" />}
              {theme === 'soft' && <Coffee className="w-5 h-5" />}
              {theme === 'dark' && <Moon className="w-5 h-5" />}
            </button>

            <div className="h-6 w-px bg-t-border"></div>
            <YearSelector year={year} onYearChange={setYear} />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Team Tabs Navigation */}
        <TeamTabs 
          teams={teams}
          activeTeamId={activeTeamId}
          onSwitch={setActiveTeamId}
          onAdd={handleAddTeam}
          onRename={handleRenameTeam}
          onDelete={handleDeleteTeam}
        />

        {/* Top Controls Area */}
        <div className="flex flex-col xl:flex-row xl:items-start justify-between gap-6 mb-8">
           {/* Paint Toolbar */}
           <div className="flex-1 min-w-0">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Management Tools */}
           <div className="flex flex-col sm:flex-row gap-3 flex-shrink-0">
             <TeamManager 
                team={activeTeam.members} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
                onReorderMembers={handleReorderMembers}
             />
             <Legend />
           </div>
        </div>

        {/* Tip Box */}
        {viewMode !== 'upcoming' && (
          <div className="mb-6 flex items-center gap-3 text-sm text-blue-800 dark:text-blue-300 bg-blue-50/50 dark:bg-blue-900/20 px-4 py-3 rounded-lg border border-blue-100 dark:border-blue-800">
             <span className="bg-blue-100 dark:bg-blue-800 text-blue-700 dark:text-blue-200 text-xs font-bold px-2 py-0.5 rounded">TIP</span>
             <span>Click on a day number (e.g., "01") in the header to toggle a global <b>Axalta Holiday</b>.</span>
          </div>
        )}

        {/* Calendar View Area */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">

          {viewMode === 'upcoming' ? (
             <UpcomingLeaves team={activeTeam.members} leaves={leaves} />
          ) : viewMode === 'year' ? (
            /* YEAR VIEW: Vertical Stack */
            <div className="space-y-8">
              {MONTHS.map((month, index) => (
                <MonthGrid
                  key={`${year}-${month}-${activeTeam.id}`}
                  year={year}
                  monthIndex={index}
                  team={activeTeam.members}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              ))}
            </div>
          ) : (
            /* MONTH VIEW: Single Focused Card */
            <div className="bg-t-surface rounded-xl shadow-sm border border-t-border overflow-hidden min-h-[500px] flex flex-col transition-colors">
              {/* Custom Navigation Header for Single Month View */}
              <div className="bg-t-surface px-6 py-4 border-b border-t-border flex items-center justify-between sticky top-0 z-10 transition-colors">
                 <button 
                   onClick={handlePrevMonth}
                   className="p-2 hover:bg-t-hover rounded-full text-t-muted hover:text-blue-600 transition-colors"
                   title="Previous Month"
                 >
                   <ChevronLeft className="w-6 h-6" />
                 </button>

                 <div className="text-center">
                    <h2 className="text-2xl font-bold text-t-text">{MONTHS[activeMonthIndex]}</h2>
                    <p className="text-sm text-t-muted font-medium">{year}</p>
                 </div>

                 <button 
                   onClick={handleNextMonth}
                   className="p-2 hover:bg-t-hover rounded-full text-t-muted hover:text-blue-600 transition-colors"
                   title="Next Month"
                 >
                   <ChevronRight className="w-6 h-6" />
                 </button>
              </div>

              {/* Grid Container */}
              <div className="p-4 sm:p-6 bg-t-main flex-1 transition-colors">
                <MonthGrid
                  key={`${year}-${activeMonthIndex}-${activeTeam.id}`}
                  year={year}
                  monthIndex={activeMonthIndex}
                  team={activeTeam.members}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              </div>
            </div>
          )}

        </div>

        {/* Footer */}
        <div className="mt-16 pb-8 border-t border-t-border pt-8 flex flex-col items-center">
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 text-t-muted hover:text-red-500 transition-colors text-sm font-medium px-4 py-2 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
            >
                <RotateCcw className="w-4 h-4" />
                Reset Application Data
            </button>
            <p className="mt-2 text-xs text-t-muted">
              Data is stored locally in your browser.
            </p>
        </div>

      </main>
    </div>
  );
};

export default App;

export enum LeaveType {
  FULL_DAY = 'FULL_DAY',
  HALF_DAY = 'HALF_DAY',
  HOLIDAY = 'HOLIDAY', // Company Holiday
  OTHER = 'OTHER', // Paternity, Sick, etc.
  WORK = 'WORK' // Standard work day (clears selection)
}

export interface TeamMember {
  id: string;
  name: string;
}

export interface Team {
  id: string;
  name: string;
  members: TeamMember[];
}

export interface LeaveRecord {
  // Key format: "userId_YYYY-MM-DD" or "GLOBAL_YYYY-MM-DD" for holidays
  [key: string]: LeaveType;
}

export interface AppSettings {
  companyName: string;
  companyLogo: string;
}

export interface AppState {
  teams: Team[];
  activeTeamId: string;
  leaves: LeaveRecord;
  year: number;
  settings?: AppSettings;
}

export type ViewMode = 'month' | 'year' | 'upcoming';

import React, { useState, useRef } from 'react';
import { X, Upload, Globe, Save, RefreshCcw } from 'lucide-react';
import { AppSettings } from '../types';

interface Props {
  settings: AppSettings;
  onSave: (settings: AppSettings) => void;
  onClose: () => void;
}

const DEFAULT_LOGO = 'https://upload.wikimedia.org/wikipedia/commons/b/b5/Axalta_logo.svg';

export const SettingsModal: React.FC<Props> = ({ settings, onSave, onClose }) => {
  const [companyName, setCompanyName] = useState(settings.companyName);
  const [companyLogo, setCompanyLogo] = useState(settings.companyLogo);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCompanyLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ companyName, companyLogo });
    onClose();
  };

  const resetToDefault = () => {
    setCompanyName('Axalta Coating Systems');
    setCompanyLogo(DEFAULT_LOGO);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-t-surface rounded-xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100 ring-1 ring-t-border">
        <div className="px-6 py-4 border-b border-t-border flex justify-between items-center bg-t-hover">
          <h3 className="font-bold text-lg text-t-text flex items-center gap-2">
            Branding Settings
          </h3>
          <button onClick={onClose} className="text-t-muted hover:text-t-text p-2 hover:bg-t-main rounded-full">
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-t-muted uppercase tracking-wider block">Company Name</label>
            <div className="relative">
              <Globe className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-t-muted" />
              <input
                type="text"
                value={companyName}
                onChange={(e) => setCompanyName(e.target.value)}
                placeholder="Enter company name..."
                className="w-full pl-10 pr-4 py-2.5 border border-t-border bg-t-surface text-t-text rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-t-muted uppercase tracking-wider block">Company Logo</label>
            <div className="flex items-center gap-4 p-4 border-2 border-dashed border-t-border rounded-xl bg-t-main/50">
              <div className="w-20 h-20 bg-t-surface rounded-lg border border-t-border flex items-center justify-center p-2 overflow-hidden shadow-inner shrink-0">
                {companyLogo ? (
                  <img src={companyLogo} alt="Preview" className="max-w-full max-h-full object-contain" />
                ) : (
                  <Upload className="w-6 h-6 text-t-muted" />
                )}
              </div>
              <div className="flex-1 space-y-2">
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-2 px-3 bg-t-surface border border-t-border text-t-text rounded-lg text-sm font-medium hover:bg-t-hover transition-colors flex items-center justify-center gap-2"
                >
                  <Upload className="w-4 h-4" />
                  Upload Image
                </button>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  className="hidden"
                />
                <button
                  type="button"
                  onClick={() => {
                    const url = prompt('Enter image URL:', companyLogo);
                    if (url) setCompanyLogo(url);
                  }}
                  className="w-full py-2 px-3 text-t-muted hover:text-blue-600 text-xs font-medium transition-colors"
                >
                  Or use URL
                </button>
              </div>
            </div>
          </div>

          <div className="flex items-center justify-between pt-4 border-t border-t-border">
            <button
              type="button"
              onClick={resetToDefault}
              className="flex items-center gap-2 text-t-muted hover:text-t-text text-sm transition-colors"
            >
              <RefreshCcw className="w-4 h-4" />
              Reset to Default
            </button>
            <div className="flex gap-3">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2 text-t-muted hover:text-t-text font-medium text-sm transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 font-bold shadow-md transition-all flex items-center gap-2"
              >
                <Save className="w-4 h-4" />
                Save Changes
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { Legend } from './components/Legend';
import { YearSelector } from './components/YearSelector';
import { ViewToggle } from './components/ViewToggle';
import { UpcomingLeaves } from './components/UpcomingLeaves';
import { TeamTabs } from './components/TeamTabs';
import { SettingsModal } from './components/SettingsModal';
import { LeaveType, TeamMember, Team, LeaveRecord, ViewMode, AppSettings } from './types';
import { MONTHS, LEAVE_LABELS } from './constants';
import { Calendar, RotateCcw, ChevronLeft, ChevronRight, Download, Moon, Sun, Coffee, Settings } from 'lucide-react';

const STORAGE_KEY = 'vacation_planner_v2';
const THEME_KEY = 'vacation_planner_theme_v2';

const DEFAULT_LOGO = 'https://upload.wikimedia.org/wikipedia/commons/b/b5/Axalta_logo.svg';

// Initial Data
const DEFAULT_TEAM_ID = 'default';
const INITIAL_TEAMS: Team[] = [
  { 
    id: DEFAULT_TEAM_ID, 
    name: 'General', 
    members: [
      { id: '1', name: 'Diego' },
      { id: '2', name: 'Lukas' },
      { id: '3', name: 'Pablo' },
    ] 
  }
];

const INITIAL_SETTINGS: AppSettings = {
  companyName: 'Axalta Coating Systems',
  companyLogo: DEFAULT_LOGO
};

type ThemeMode = 'light' | 'soft' | 'dark';

const App: React.FC = () => {
  // State
  const [year, setYear] = useState(2026);
  const [teams, setTeams] = useState<Team[]>(INITIAL_TEAMS);
  const [activeTeamId, setActiveTeamId] = useState<string>(DEFAULT_TEAM_ID);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [settings, setSettings] = useState<AppSettings>(INITIAL_SETTINGS);
  const [currentTool, setCurrentTool] = useState<LeaveType | null>(null);
  const [isClient, setIsClient] = useState(false);
  const [theme, setTheme] = useState<ThemeMode>('light');
  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [activeMonthIndex, setActiveMonthIndex] = useState(new Date().getMonth());
  const [showSettings, setShowSettings] = useState(false);

  // Derived State
  const activeTeam = teams.find(t => t.id === activeTeamId) || teams[0];

  // Load from local storage with Migration Logic
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);

        if (parsed.leaves) setLeaves(parsed.leaves);
        if (parsed.year) setYear(parsed.year);
        if (parsed.settings) setSettings(parsed.settings);

        // Migration: Check if we have 'teams' array, otherwise migrate 'team' array
        if (parsed.teams && Array.isArray(parsed.teams)) {
          setTeams(parsed.teams);
          if (parsed.activeTeamId) setActiveTeamId(parsed.activeTeamId);
        } else if (parsed.team && Array.isArray(parsed.team)) {
          // Legacy format migration
          const migratedTeam: Team = {
            id: DEFAULT_TEAM_ID,
            name: 'General',
            members: parsed.team
          };
          setTeams([migratedTeam]);
          setActiveTeamId(DEFAULT_TEAM_ID);
        }

      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }

    // Load theme
    const savedTheme = localStorage.getItem(THEME_KEY) as ThemeMode;
    if (['light', 'soft', 'dark'].includes(savedTheme)) {
      setTheme(savedTheme);
    } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme('dark');
    }

    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      teams, 
      activeTeamId, 
      leaves, 
      year,
      settings
    }));
  }, [teams, activeTeamId, leaves, year, isClient, settings]);

  // Handle Theme Change
  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('dark', 'theme-soft');
    if (theme === 'dark') root.classList.add('dark');
    else if (theme === 'soft') root.classList.add('theme-soft');
    localStorage.setItem(THEME_KEY, theme);
  }, [theme]);

  const toggleTheme = () => {
    const cycle: Record<ThemeMode, ThemeMode> = {
      'light': 'soft',
      'soft': 'dark',
      'dark': 'light'
    };
    setTheme(prev => cycle[prev]);
  };

  // --- Team Management ---

  const handleAddTeam = () => {
    const newId = crypto.randomUUID ? crypto.randomUUID() : Date.now().toString();
    const newTeam: Team = {
      id: newId,
      name: `New Team`,
      members: []
    };
    setTeams([...teams, newTeam]);
    setActiveTeamId(newId);
  };

  const handleRenameTeam = (id: string, newName: string) => {
    setTeams(teams.map(t => t.id === id ? { ...t, name: newName } : t));
  };

  const handleDeleteTeam = (id: string) => {
    if (teams.length <= 1) return; // Prevent deleting last team

    const newTeams = teams.filter(t => t.id !== id);
    setTeams(newTeams);

    // If we deleted the active team, switch to the first one available
    if (activeTeamId === id) {
      setActiveTeamId(newTeams[0].id);
    }
  };

  // --- Member Management (Scoped to Active Team) ---

  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };

    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        return { ...t, members: [...t.members, newMember] };
      }
      return t;
    }));
  };

  const handleRemoveMember = (id: string) => {
    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        return { ...t, members: t.members.filter(m => m.id !== id) };
      }
      return t;
    }));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        const updatedMembers = [...t.members];
        const [movedMember] = updatedMembers.splice(fromIndex, 1);
        updatedMembers.splice(toIndex, 0, movedMember);
        return { ...t, members: updatedMembers };
      }
      return t;
    }));
  };

  // --- Leave Management ---

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  const handleExportCSV = () => {
    const headers = ['Team', 'Employee Name', 'Date', 'Type', 'Day of Week'];
    const dataRows: { teamName: string; name: string; dateStr: string; label: string; dayOfWeek: string; sortDate: number }[] = [];

    (Object.entries(leaves) as [string, LeaveType][]).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;

      const dateStr = key.slice(-10);
      const idPart = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      if (y !== year) return;

      let name = 'Unknown';
      let teamName = '-';

      if (idPart === 'GLOBAL') {
        name = 'Axalta Holiday';
        teamName = 'All';
      } else {
        // Search across all teams
        let found = false;
        for (const t of teams) {
          const member = t.members.find(m => m.id === idPart);
          if (member) {
            name = member.name;
            teamName = t.name;
            found = true;
            break;
          }
        }
        if (!found) return; // Member might have been deleted
      }

      const date = new Date(y, m - 1, d);
      const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'long' });
      const label = LEAVE_LABELS[type] || type;

      dataRows.push({
        teamName,
        name,
        dateStr,
        label,
        dayOfWeek,
        sortDate: date.getTime()
      });
    });

    dataRows.sort((a, b) => a.sortDate - b.sortDate || a.teamName.localeCompare(b.teamName) || a.name.localeCompare(b.name));
    const escape = (str: string) => `"${str.replace(/"/g, '""')}"`;
    const rows = dataRows.map(row => 
      [escape(row.teamName), escape(row.name), escape(row.dateStr), escape(row.label), escape(row.dayOfWeek)].join(',')
    );

    const csvContent = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `leave_plan_${year}.csv`;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handlePrevMonth = () => {
    if (activeMonthIndex === 0) {
      setActiveMonthIndex(11);
      setYear(y => y - 1);
    } else {
      setActiveMonthIndex(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (activeMonthIndex === 11) {
      setActiveMonthIndex(0);
      setYear(y => y + 1);
    } else {
      setActiveMonthIndex(prev => prev + 1);
    }
  };

  return (
    <div className="min-h-screen bg-t-main text-t-text pb-20 font-sans transition-colors duration-200">
      {/* Header */}
      <header className="bg-t-surface border-b border-t-border sticky top-0 z-30 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-3">
              {settings.companyLogo && (
                <div className="h-10 w-10 flex items-center justify-center p-1 bg-white dark:bg-gray-100 rounded shadow-sm border border-t-border">
                  <img src={settings.companyLogo} alt="Logo" className="max-h-full max-w-full object-contain" />
                </div>
              )}
              <div className="hidden sm:block">
                <h1 className="text-sm font-bold text-t-text tracking-tight uppercase">{settings.companyName}</h1>
                <p className="text-[10px] text-t-muted font-bold uppercase tracking-widest leading-tight">Leave Planner</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <ViewToggle viewMode={viewMode} onViewChange={setViewMode} />

            <div className="flex items-center gap-1.5 border-l border-t-border pl-3 sm:pl-6">
              <button
                onClick={handleExportCSV}
                className="p-2 rounded-full text-t-muted hover:text-blue-500 hover:bg-t-hover transition-all"
                title="Export to CSV"
              >
                <Download className="w-5 h-5" />
              </button>

              <button
                onClick={toggleTheme}
                className="p-2 rounded-full text-t-muted hover:bg-t-hover transition-colors"
                title={`Theme: ${theme.charAt(0).toUpperCase() + theme.slice(1)}`}
              >
                {theme === 'light' && <Sun className="w-5 h-5" />}
                {theme === 'soft' && <Coffee className="w-5 h-5" />}
                {theme === 'dark' && <Moon className="w-5 h-5" />}
              </button>

              <button
                onClick={() => setShowSettings(true)}
                className="p-2 rounded-full text-t-muted hover:bg-t-hover transition-colors"
                title="Settings"
              >
                <Settings className="w-5 h-5" />
              </button>
            </div>

            <div className="h-6 w-px bg-t-border"></div>
            <YearSelector year={year} onYearChange={setYear} />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Team Tabs Navigation */}
        <TeamTabs 
          teams={teams}
          activeTeamId={activeTeamId}
          onSwitch={setActiveTeamId}
