import React, { useState, useEffect } from 'react';
import { MonthGrid } from './components/MonthGrid';
import { LeaveToolbar } from './components/LeaveToolbar';
import { TeamManager } from './components/TeamManager';
import { Legend } from './components/Legend';
import { YearSelector } from './components/YearSelector';
import { ViewToggle } from './components/ViewToggle';
import { UpcomingLeaves } from './components/UpcomingLeaves';
import { TeamTabs } from './components/TeamTabs';
import { SettingsModal } from './components/SettingsModal';
import { LeaveType, TeamMember, Team, LeaveRecord, ViewMode, AppSettings } from './types';
import { MONTHS, LEAVE_LABELS } from './constants';
import { Calendar, RotateCcw, ChevronLeft, ChevronRight, Download, Moon, Sun, Coffee, Settings } from 'lucide-react';

const STORAGE_KEY = 'vacation_planner_v2';
const THEME_KEY = 'vacation_planner_theme_v2';

// Initial Data
const DEFAULT_TEAM_ID = 'default';
const INITIAL_TEAMS: Team[] = [
  { 
    id: DEFAULT_TEAM_ID, 
    name: 'General', 
    members: [
      { id: '1', name: 'Diego' },
      { id: '2', name: 'Lukas' },
      { id: '3', name: 'Pablo' },
    ] 
  }
];

const INITIAL_SETTINGS: AppSettings = {
  companyName: 'Axalta Coating Systems'
};

type ThemeMode = 'light' | 'soft' | 'dark';

const App: React.FC = () => {
  // State
  const [year, setYear] = useState(2026);
  const [teams, setTeams] = useState<Team[]>(INITIAL_TEAMS);
  const [activeTeamId, setActiveTeamId] = useState<string>(DEFAULT_TEAM_ID);
  const [leaves, setLeaves] = useState<LeaveRecord>({});
  const [settings, setSettings] = useState<AppSettings>(INITIAL_SETTINGS);
  const [currentTool, setCurrentTool] = useState<LeaveType | null>(null);
  const [isClient, setIsClient] = useState(false);
  const [theme, setTheme] = useState<ThemeMode>('light');
  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [activeMonthIndex, setActiveMonthIndex] = useState(new Date().getMonth());
  const [showSettings, setShowSettings] = useState(false);

  // Derived State
  const activeTeam = teams.find(t => t.id === activeTeamId) || teams[0];

  // Load from local storage with Migration Logic
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);

        if (parsed.leaves) setLeaves(parsed.leaves);
        if (parsed.year) setYear(parsed.year);
        if (parsed.settings) setSettings(parsed.settings);

        // Migration: Check if we have 'teams' array, otherwise migrate 'team' array
        if (parsed.teams && Array.isArray(parsed.teams)) {
          setTeams(parsed.teams);
          if (parsed.activeTeamId) setActiveTeamId(parsed.activeTeamId);
        } else if (parsed.team && Array.isArray(parsed.team)) {
          // Legacy format migration
          const migratedTeam: Team = {
            id: DEFAULT_TEAM_ID,
            name: 'General',
            members: parsed.team
          };
          setTeams([migratedTeam]);
          setActiveTeamId(DEFAULT_TEAM_ID);
        }

      } catch (e) {
        console.error("Failed to load saved data", e);
      }
    }

    // Load theme
    const savedTheme = localStorage.getItem(THEME_KEY) as ThemeMode;
    if (['light', 'soft', 'dark'].includes(savedTheme)) {
      setTheme(savedTheme);
    } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme('dark');
    }

    setIsClient(true);
  }, []);

  // Save to local storage
  useEffect(() => {
    if (!isClient) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      teams, 
      activeTeamId, 
      leaves, 
      year,
      settings
    }));
  }, [teams, activeTeamId, leaves, year, isClient, settings]);

  // Handle Theme Change
  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('dark', 'theme-soft');
    if (theme === 'dark') root.classList.add('dark');
    else if (theme === 'soft') root.classList.add('theme-soft');
    localStorage.setItem(THEME_KEY, theme);
  }, [theme]);

  const toggleTheme = () => {
    const cycle: Record<ThemeMode, ThemeMode> = {
      'light': 'soft',
      'soft': 'dark',
      'dark': 'light'
    };
    setTheme(prev => cycle[prev]);
  };

  // --- Team Management ---

  const handleAddTeam = () => {
    const newId = crypto.randomUUID ? crypto.randomUUID() : Date.now().toString();
    const newTeam: Team = {
      id: newId,
      name: `New Team`,
      members: []
    };
    setTeams([...teams, newTeam]);
    setActiveTeamId(newId);
  };

  const handleRenameTeam = (id: string, newName: string) => {
    setTeams(teams.map(t => t.id === id ? { ...t, name: newName } : t));
  };

  const handleDeleteTeam = (id: string) => {
    if (teams.length <= 1) return; // Prevent deleting last team

    const newTeams = teams.filter(t => t.id !== id);
    setTeams(newTeams);

    // If we deleted the active team, switch to the first one available
    if (activeTeamId === id) {
      setActiveTeamId(newTeams[0].id);
    }
  };

  // --- Member Management (Scoped to Active Team) ---

  const handleAddMember = (name: string) => {
    const newMember: TeamMember = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString(), 
      name,
    };

    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        return { ...t, members: [...t.members, newMember] };
      }
      return t;
    }));
  };

  const handleRemoveMember = (id: string) => {
    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        return { ...t, members: t.members.filter(m => m.id !== id) };
      }
      return t;
    }));
  };

  const handleReorderMembers = (fromIndex: number, toIndex: number) => {
    setTeams(prevTeams => prevTeams.map(t => {
      if (t.id === activeTeamId) {
        const updatedMembers = [...t.members];
        const [movedMember] = updatedMembers.splice(fromIndex, 1);
        updatedMembers.splice(toIndex, 0, movedMember);
        return { ...t, members: updatedMembers };
      }
      return t;
    }));
  };

  // --- Leave Management ---

  const handleToggleLeave = (key: string, type: LeaveType) => {
    setLeaves(prev => {
      const next = { ...prev };
      if (type === LeaveType.WORK) {
        delete next[key];
      } else {
        next[key] = type;
      }
      return next;
    });
  };

  const handleReset = () => {
    if (confirm("This will erase all data and reset to default. Are you sure?")) {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
    }
  };

  const handleExportCSV = () => {
    const headers = ['Team', 'Employee Name', 'Date', 'Type', 'Day of Week'];
    const dataRows: { teamName: string; name: string; dateStr: string; label: string; dayOfWeek: string; sortDate: number }[] = [];

    (Object.entries(leaves) as [string, LeaveType][]).forEach(([key, type]) => {
      if (type === LeaveType.WORK) return;

      const dateStr = key.slice(-10);
      const idPart = key.slice(0, -11);

      const [y, m, d] = dateStr.split('-').map(Number);
      if (y !== year) return;

      let name = 'Unknown';
      let teamName = '-';

      if (idPart === 'GLOBAL') {
        name = 'Axalta Holiday';
        teamName = 'All';
      } else {
        // Search across all teams
        let found = false;
        for (const t of teams) {
          const member = t.members.find(m => m.id === idPart);
          if (member) {
            name = member.name;
            teamName = t.name;
            found = true;
            break;
          }
        }
        if (!found) return; // Member might have been deleted
      }

      const date = new Date(y, m - 1, d);
      const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'long' });
      const label = LEAVE_LABELS[type] || type;

      dataRows.push({
        teamName,
        name,
        dateStr,
        label,
        dayOfWeek,
        sortDate: date.getTime()
      });
    });

    dataRows.sort((a, b) => a.sortDate - b.sortDate || a.teamName.localeCompare(b.teamName) || a.name.localeCompare(b.name));
    const escape = (str: string) => `"${str.replace(/"/g, '""')}"`;
    const rows = dataRows.map(row => 
      [escape(row.teamName), escape(row.name), escape(row.dateStr), escape(row.label), escape(row.dayOfWeek)].join(',')
    );

    const csvContent = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `leave_plan_${year}.csv`;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handlePrevMonth = () => {
    if (activeMonthIndex === 0) {
      setActiveMonthIndex(11);
      setYear(y => y - 1);
    } else {
      setActiveMonthIndex(prev => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (activeMonthIndex === 11) {
      setActiveMonthIndex(0);
      setYear(y => y + 1);
    } else {
      setActiveMonthIndex(prev => prev + 1);
    }
  };

  return (
    <div className="min-h-screen bg-t-main text-t-text pb-20 font-sans transition-colors duration-200">
      {/* Header */}
      <header className="bg-t-surface border-b border-t-border sticky top-0 z-30 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg text-white shadow-sm">
                <Calendar className="w-5 h-5" />
              </div>
              <div className="hidden sm:block">
                <h1 className="text-sm font-bold text-t-text tracking-tight uppercase leading-none">{settings.companyName}</h1>
                <p className="text-[10px] text-t-muted font-bold uppercase tracking-widest mt-1">Leave Planner</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 sm:gap-6">
            <ViewToggle viewMode={viewMode} onViewChange={setViewMode} />

            <div className="flex items-center gap-1.5 border-l border-t-border pl-3 sm:pl-6">
              <button
                onClick={handleExportCSV}
                className="p-2 rounded-full text-t-muted hover:text-blue-500 hover:bg-t-hover transition-all"
                title="Export to CSV"
              >
                <Download className="w-5 h-5" />
              </button>

              <button
                onClick={toggleTheme}
                className="p-2 rounded-full text-t-muted hover:bg-t-hover transition-colors"
                title={`Theme: ${theme.charAt(0).toUpperCase() + theme.slice(1)}`}
              >
                {theme === 'light' && <Sun className="w-5 h-5" />}
                {theme === 'soft' && <Coffee className="w-5 h-5" />}
                {theme === 'dark' && <Moon className="w-5 h-5" />}
              </button>

              <button
                onClick={() => setShowSettings(true)}
                className="p-2 rounded-full text-t-muted hover:bg-t-hover transition-colors"
                title="Settings"
              >
                <Settings className="w-5 h-5" />
              </button>
            </div>

            <div className="h-6 w-px bg-t-border"></div>
            <YearSelector year={year} onYearChange={setYear} />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Team Tabs Navigation */}
        <TeamTabs 
          teams={teams}
          activeTeamId={activeTeamId}
          onSwitch={setActiveTeamId}
          onAdd={handleAddTeam}
          onRename={handleRenameTeam}
          onDelete={handleDeleteTeam}
        />

        {/* Top Controls Area */}
        <div className="flex flex-col xl:flex-row xl:items-start justify-between gap-6 mb-8">
           {/* Paint Toolbar */}
           <div className="flex-1 min-w-0">
              <LeaveToolbar selectedTool={currentTool} onSelectTool={setCurrentTool} />
           </div>

           {/* Management Tools */}
           <div className="flex flex-col sm:flex-row gap-3 flex-shrink-0">
             <TeamManager 
                team={activeTeam.members} 
                onAddMember={handleAddMember} 
                onRemoveMember={handleRemoveMember} 
                onReorderMembers={handleReorderMembers}
             />
             <Legend />
           </div>
        </div>

        {/* Tip Box */}
        {viewMode !== 'upcoming' && (
          <div className="mb-6 flex items-center gap-3 text-sm text-blue-800 dark:text-blue-300 bg-blue-50/50 dark:bg-blue-900/20 px-4 py-3 rounded-lg border border-blue-100 dark:border-blue-800">
             <span className="bg-blue-100 dark:bg-blue-800 text-blue-700 dark:text-blue-200 text-xs font-bold px-2 py-0.5 rounded">TIP</span>
             <span>Click on a day number (e.g., "01") in the header to toggle a global <b>Axalta Holiday</b>.</span>
          </div>
        )}

        {/* Calendar View Area */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">

          {viewMode === 'upcoming' ? (
             <UpcomingLeaves team={activeTeam.members} leaves={leaves} />
          ) : viewMode === 'year' ? (
            /* YEAR VIEW: Vertical Stack */
            <div className="space-y-8">
              {MONTHS.map((month, index) => (
                <MonthGrid
                  key={`${year}-${month}-${activeTeam.id}`}
                  year={year}
                  monthIndex={index}
                  team={activeTeam.members}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              ))}
            </div>
          ) : (
            /* MONTH VIEW: Single Focused Card */
            <div className="bg-t-surface rounded-xl shadow-sm border border-t-border overflow-hidden min-h-[500px] flex flex-col transition-colors">
              {/* Custom Navigation Header for Single Month View */}
              <div className="bg-t-surface px-6 py-4 border-b border-t-border flex items-center justify-between sticky top-0 z-10 transition-colors">
                 <button 
                   onClick={handlePrevMonth}
                   className="p-2 hover:bg-t-hover rounded-full text-t-muted hover:text-blue-600 transition-colors"
                   title="Previous Month"
                 >
                   <ChevronLeft className="w-6 h-6" />
                 </button>

                 <div className="text-center">
                    <h2 className="text-2xl font-bold text-t-text">{MONTHS[activeMonthIndex]}</h2>
                    <p className="text-sm text-t-muted font-medium">{year}</p>
                 </div>

                 <button 
                   onClick={handleNextMonth}
                   className="p-2 hover:bg-t-hover rounded-full text-t-muted hover:text-blue-600 transition-colors"
                   title="Next Month"
                 >
                   <ChevronRight className="w-6 h-6" />
                 </button>
              </div>

              {/* Grid Container */}
              <div className="p-4 sm:p-6 bg-t-main flex-1 transition-colors">
                <MonthGrid
                  key={`${year}-${activeMonthIndex}-${activeTeam.id}`}
                  year={year}
                  monthIndex={activeMonthIndex}
                  team={activeTeam.members}
                  leaves={leaves}
                  currentTool={currentTool}
                  onToggleLeave={handleToggleLeave}
                />
              </div>
            </div>
          )}

        </div>

        {/* Footer */}
        <div className="mt-16 pb-8 border-t border-t-border pt-8 flex flex-col items-center">
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 text-t-muted hover:text-red-500 transition-colors text-sm font-medium px-4 py-2 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
            >
                <RotateCcw className="w-4 h-4" />
                Reset Application Data
            </button>
            <p className="mt-2 text-xs text-t-muted">
              Data is stored locally in your browser.
            </p>
        </div>

      </main>

      {showSettings && (
        <SettingsModal 
          settings={settings}
          onSave={setSettings}
          onClose={() => setShowSettings(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | string[] | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // For Matching questions
  const [matchingPairs, setMatchingPairs] = useState<Record<string, string>>({});
  const [selectedMatchKey, setSelectedMatchKey] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  // Speech states
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch (e) {}
        audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  useEffect(() => {
    if (timer === 0) return;
    if (timeLeft <= 0) { finishQuiz(); return; }
    const intervalId = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  useEffect(() => {
    const loadInitialQuestion = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) { onQuizEnd([], 0); return; }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
        } catch (err) {
          setError("Failed to generate question.");
          setIsLoading(false);
        }
      }
    };
    loadInitialQuestion();
  }, []);

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
    if (!currentQuestion) return;
    setIsGeneratingAudio(true);
    try {
        if (!audioContextRef.current) audioContextRef.current = new AudioContext();
        const textToRead = `${currentQuestion.context || ''} ${currentQuestion.question}`;
        const buffer = await generateSpeech(textToRead, 'Zephyr', audioContextRef.current);
        setIsGeneratingAudio(false);
        setIsSpeaking(true);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsSpeaking(false);
        audioSourceRef.current = source;
        source.start();
    } catch (err) {
        setIsGeneratingAudio(false);
        setIsSpeaking(false);
    }
  };

  const toggleMultiSelect = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr.filter(o => o !== option);
      return [...arr, option];
    });
  };

  const handleBuildListAdd = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr;
      return [...arr, option];
    });
  };

  const handleBuildListRemove = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      return arr.filter(o => o !== option);
    });
  };

  const handleMatchingClick = (item: string, isKey: boolean) => {
    if (quizState === 'answered') return;
    if (isKey) {
      setSelectedMatchKey(item === selectedMatchKey ? null : item);
    } else {
      if (selectedMatchKey) {
        setMatchingPairs(prev => {
          const next = { ...prev };
          // Remove item from any other key if it was already matched
          Object.keys(next).forEach(k => {
            if (next[k] === item) delete next[k];
          });
          next[selectedMatchKey] = item;
          return next;
        });
        setSelectedMatchKey(null);
      }
    }
  };

  const handleSubmit = () => {
    let finalAnswer: string | string[] | null = selectedAnswer;

    if (currentQuestion.type === 'Matching') {
      finalAnswer = Object.entries(matchingPairs).map(([k, v]) => `${k}:${v}`);
    }

    if (!finalAnswer || (Array.isArray(finalAnswer) && finalAnswer.length === 0) || quizState !== 'answering') return;

    let isCorrect = false;
    if (currentQuestion.type === 'MultipleChoice' || currentQuestion.type === 'CaseStudy') {
      isCorrect = finalAnswer === currentQuestion.answer;
    } else {
      const userArr = Array.isArray(finalAnswer) ? finalAnswer : [finalAnswer];
      const correctArr = Array.isArray(currentQuestion.answer) ? currentQuestion.answer : [currentQuestion.answer];

      if (currentQuestion.type === 'BuildList') {
        isCorrect = JSON.stringify(userArr) === JSON.stringify(correctArr);
      } else if (currentQuestion.type === 'Matching') {
        // Sort both for comparison
        isCorrect = userArr.length === correctArr.length && [...userArr].sort().join(',') === [...correctArr].sort().join(',');
      } else {
        isCorrect = userArr.length === correctArr.length && userArr.every(v => correctArr.includes(v));
      }
    }

    setResults(prev => [...prev, { question: currentQuestion, userAnswer: finalAnswer, isCorrect }]);
    setQuizState('answered');
  };

  const handleNextQuestion = async () => {
    stopSpeaking();
    const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
    if (currentQuestionIndex + 1 >= totalInSet) { finishQuiz(); return; }

    setIsLoading(true);
    try {
      const nextQ = await generateQuestion(difficulty, category);
      setQuestions(prev => [...prev, nextQ]);
      setCurrentQuestionIndex(prev => prev + 1);
      setSelectedAnswer(null);
      setMatchingPairs({});
      setSelectedMatchKey(null);
      setQuizState('answering');
    } catch (err) {
      setError("Failed to load next question.");
    } finally {
      setIsLoading(false);
    }
  };

  const renderOptions = () => {
    const { type, options } = currentQuestion;

    switch (type) {
      case 'MultiSelect':
        return (
          <div className="space-y-3 animate-fade-in-up">
            <p className="text-sm text-primary-light font-black mb-2 uppercase tracking-tight">Select all correct options:</p>
            {options.map((opt, i) => {
              const isSelected = Array.isArray(selectedAnswer) && selectedAnswer.includes(opt);
              return (
                <button key={i} onClick={() => toggleMultiSelect(opt)} disabled={quizState === 'answered'} className={`w-full text-left p-5 rounded-2xl border-2 flex items-center gap-4 transition-all shadow-sm ${isSelected ? 'border-primary bg-primary/10 ring-2 ring-primary/20' : 'border-border bg-card hover:border-slate-500'}`}>
                  <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-colors ${isSelected ? 'bg-primary border-primary' : 'border-slate-600'}`}>
                    {isSelected && <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>}
                  </div>
                  <span className="font-medium text-slate-200">{opt}</span>
                </button>
              );
            })}
          </div>
        );
      case 'BuildList':
        const buildListSelected = Array.isArray(selectedAnswer) ? selectedAnswer : [];
        const buildListAvailable = options.filter(o => !buildListSelected.includes(o));
        return (
          <div className="space-y-6 animate-fade-in-up">
             <p className="text-sm text-primary-light font-black mb-2 uppercase tracking-tight">Arrange steps in correct logical order:</p>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Available Actions</h4>
                    <div className="bg-slate-900/50 p-4 rounded-2xl border border-border min-h-[200px] space-y-2">
                        {buildListAvailable.map((opt, i) => (
                            <button key={i} onClick={() => handleBuildListAdd(opt)} disabled={quizState === 'answered'} className="w-full text-left p-4 bg-slate-800 border border-slate-700 rounded-xl text-sm font-medium hover:border-primary hover:bg-slate-700 transition-all shadow-md group">
                                <span className="group-hover:text-primary transition-colors">{opt}</span>
                            </button>
                        ))}
                    </div>
                </div>
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Ordered Sequence</h4>
                    <div className="bg-slate-900/50 p-4 rounded-2xl border border-border min-h-[200px] space-y-2">
                        {buildListSelected.map((opt, i) => (
                            <button key={i} onClick={() => handleBuildListRemove(opt)} disabled={quizState === 'answered'} className="w-full text-left p-4 bg-primary/20 border border-primary/50 rounded-xl text-sm flex items-center gap-4 group hover:bg-primary/30 transition-all">
                                <span className="w-6 h-6 flex items-center justify-center bg-primary text-white rounded-lg font-black text-xs shrink-0">{i+1}</span>
                                <span className="font-semibold text-slate-100">{opt}</span>
                            </button>
                        ))}
                        {buildListSelected.length === 0 && (
                          <div className="flex flex-col items-center justify-center h-40 text-slate-600 italic text-sm">
                            <svg className="w-8 h-8 mb-2 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/></svg>
                            Click actions to reorder
                          </div>
                        )}
                    </div>
                </div>
             </div>
          </div>
        );
      case 'Matching':
         // Assuming options is like ["Key1", "Key2", "Value1", "Value2"]
         // Usually first half are keys, second half are targets
         const half = Math.ceil(options.length / 2);
         const keys = options.slice(0, half);
         const targets = options.slice(half);

         return (
          <div className="space-y-6 animate-fade-in-up">
             <p className="text-sm text-primary-light font-black mb-2 uppercase tracking-tight">Match items from the left to categories on the right:</p>
             <div className="grid grid-cols-2 gap-10">
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Items</h4>
                    <div className="space-y-3">
                        {keys.map((k, i) => {
                          const matchedVal = matchingPairs[k];
                          return (
                            <button 
                              key={i} 
                              onClick={() => handleMatchingClick(k, true)} 
                              disabled={quizState === 'answered'}
                              className={`w-full text-left p-4 rounded-xl border-2 text-sm font-bold transition-all flex justify-between items-center ${selectedMatchKey === k ? 'border-primary bg-primary/20 scale-105 shadow-xl' : matchedVal ? 'border-success/50 bg-success/5' : 'border-border bg-card hover:border-slate-500'}`}
                            >
                                <span>{k}</span>
                                {matchedVal && <span className="text-[10px] bg-success/20 text-success px-2 py-0.5 rounded-full uppercase tracking-tighter">Matched</span>}
                            </button>
                          );
                        })}
                    </div>
                </div>
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Categories / Targets</h4>
                    <div className="space-y-3">
                        {targets.map((t, i) => {
                          const matchedKey = Object.keys(matchingPairs).find(k => matchingPairs[k] === t);
                          return (
                            <button 
                              key={i} 
                              onClick={() => handleMatchingClick(t, false)} 
                              disabled={quizState === 'answered' || !selectedMatchKey}
                              className={`w-full text-left p-4 rounded-xl border-2 text-sm font-bold transition-all flex flex-col gap-1 ${matchedKey ? 'border-primary bg-primary/10' : selectedMatchKey ? 'border-primary/50 bg-primary/5 animate-pulse' : 'border-border bg-card'}`}
                            >
                                <span className="text-slate-200">{t}</span>
                                {matchedKey && <span className="text-[9px] text-primary bg-primary/10 p-1 rounded font-black mt-1 line-clamp-1">← {matchedKey}</span>}
                            </button>
                          );
                        })}
                    </div>
                </div>
             </div>
          </div>
         );
      default:
        return (
          <div className="space-y-3 animate-fade-in-up">
            {options.map((opt, i) => (
              <button key={i} onClick={() => setSelectedAnswer(opt)} disabled={quizState === 'answered'} className={`w-full text-left p-5 rounded-2xl border-2 flex items-center gap-5 transition-all shadow-sm ${selectedAnswer === opt ? 'border-primary bg-primary/10 ring-2 ring-primary/20' : 'border-border bg-card hover:border-slate-500'}`}>
                 <div className={`w-6 h-6 rounded-full border-2 transition-all shrink-0 ${selectedAnswer === opt ? 'border-primary bg-primary ring-4 ring-primary/20' : 'border-slate-600'}`} />
                 <span className="font-semibold text-slate-200">{opt}</span>
              </button>
            ))}
          </div>
        );
    }
  };

  if (isLoading && questions.length === 0) return <Loader text="Assembling dynamic exam content..." />;

  const isMatchingComplete = currentQuestion?.type === 'Matching' 
    ? Object.keys(matchingPairs).length === Math.ceil(currentQuestion.options.length / 2)
    : !!selectedAnswer && (!Array.isArray(selectedAnswer) || selectedAnswer.length > 0);

  return (
    <div className="max-w-5xl mx-auto animate-fade-in pb-20 px-4 sm:px-0">
        <div className="flex justify-between items-center mb-8">
            <h2 className="text-3xl font-black tracking-tight flex items-center gap-4 text-slate-100">
                <div className="w-12 h-12 bg-primary rounded-2xl flex items-center justify-center text-white shadow-xl shadow-primary/20">
                    <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                </div>
                <span>{mode === 'Exam' ? 'Exam Simulation' : category === 'All' ? 'Full Practice' : category}</span>
            </h2>
            {timer > 0 && (
                <div className="flex items-center gap-4 font-mono font-bold px-6 py-3 rounded-2xl border border-border bg-slate-900/80 backdrop-blur-md shadow-2xl">
                    <StopwatchIcon className="w-6 h-6 text-primary" />
                    <span className="text-2xl text-slate-100 tracking-wider">{Math.floor(timeLeft/60)}:{(timeLeft%60).toString().padStart(2, '0')}</span>
                </div>
            )}
        </div>

        {currentQuestion.context && (
            <div className="mb-10 p-8 bg-slate-800/40 backdrop-blur-sm rounded-3xl border-l-8 border-primary shadow-2xl animate-fade-in-up">
                <h4 className="text-[10px] font-black uppercase text-primary tracking-[0.2em] mb-4">Case Study Scenario</h4>
                <div className="text-slate-300 text-lg leading-relaxed font-serif">
                    {currentQuestion.context}
                </div>
            </div>
        )}

        <div className="bg-card/80 backdrop-blur-xl p-10 sm:p-14 rounded-[3rem] shadow-2xl border border-border relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-8 flex gap-3 z-10">
                <button onClick={handleReadAloud} className={`p-3 rounded-2xl transition-all shadow-md ${isSpeaking || isGeneratingAudio ? 'bg-danger text-white' : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'}`}>
                    {isSpeaking || isGeneratingAudio ? <StopIcon className="w-6 h-6" /> : <SpeakerIcon className="w-6 h-6" />}
                </button>
                <button onClick={() => onToggleBookmark(currentQuestion)} className={`p-3 rounded-2xl transition-all shadow-md ${isBookmarked(currentQuestion) ? 'text-yellow-400 bg-yellow-400/20' : 'text-slate-500 hover:text-yellow-400 bg-slate-800/80 hover:bg-slate-700'}`}>
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} className="w-6 h-6" />
                </button>
            </div>

            <div className="mb-12">
               <span className="inline-block bg-primary text-white text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-[0.2em] mb-6 shadow-lg shadow-primary/20">
                 {currentQuestion.type} • ITEM {currentQuestionIndex + 1} OF {mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS}
               </span>
               <h3 className="text-2xl md:text-3xl font-black leading-tight text-white pr-24">{currentQuestion.question}</h3>
            </div>

            <div className="min-h-[300px]">
              {renderOptions()}
            </div>

            {quizState === 'answered' && (
                <div className="mt-12 pt-12 border-t border-border animate-fade-in-up">
                    <DexterExplains 
                      question={currentQuestion} 
                      userAnswer={results[results.length-1].userAnswer} 
                    />
                </div>
            )}

            <div className="mt-14 flex flex-col sm:flex-row gap-6">
                {quizState === 'answering' ? (
                    <button 
                      onClick={handleSubmit} 
                      disabled={!isMatchingComplete} 
                      className="flex-1 bg-primary hover:bg-primary/90 text-white font-black py-5 px-10 rounded-[1.5rem] text-xl shadow-2xl shadow-primary/30 transition-all disabled:opacity-30 disabled:cursor-not-allowed hover:scale-[1.02] active:scale-95"
                    >
                        Check Final Answer
                    </button>
                ) : (
                    <button 
                      onClick={handleNextQuestion} 
                      className="flex-1 bg-primary hover:bg-primary/90 text-white font-black py-5 px-10 rounded-[1.5rem] text-xl shadow-2xl shadow-primary/30 transition-all flex items-center justify-center gap-4 hover:scale-[1.02] active:scale-95"
                    >
                        {currentQuestionIndex + 1 === (mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS) ? 'Finish & Final Score' : 'Continue to Next Item'}
                        <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                    </button>
                )}
            </div>
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import React from 'react';
import type { Question } from '../types';
import { DexterExplains } from './DexterExplains';
import { CheckIcon } from './icons/CheckIcon';
import { XIcon } from './icons/XIcon';

interface QuestionDetailProps {
    question: Question;
    userAnswer?: string | string[] | null;
}

export const QuestionDetail: React.FC<QuestionDetailProps> = ({ question, userAnswer }) => {

    const isOptionSelected = (opt: string) => {
        if (!userAnswer) return false;
        return Array.isArray(userAnswer) ? userAnswer.includes(opt) : userAnswer === opt;
    };

    const isOptionCorrect = (opt: string) => {
        return Array.isArray(question.answer) ? question.answer.includes(opt) : question.answer === opt;
    };

    const getOptionClass = (opt: string) => {
        const correct = isOptionCorrect(opt);
        const selected = isOptionSelected(opt);

        if (correct) return 'bg-success/10 border-success/50 text-success';
        if (selected && !correct) return 'bg-danger/10 border-danger/50 text-danger';
        return 'bg-card opacity-50 border-border';
    };

    const renderMatchingReview = () => {
      const correctPairs = (Array.isArray(question.answer) ? question.answer : []) as string[];
      const userPairs = (Array.isArray(userAnswer) ? userAnswer : []) as string[];

      return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="p-6 bg-slate-900/50 rounded-2xl border border-border">
            <h4 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-4">Correct Mapping</h4>
            <div className="space-y-2">
              {correctPairs.map((p, i) => {
                const [k, v] = p.split(':');
                return (
                  <div key={i} className="flex items-center justify-between p-3 bg-slate-800 rounded-lg text-xs font-bold border border-slate-700">
                    <span className="text-slate-100">{k}</span>
                    <span className="text-primary-light">→</span>
                    <span className="text-slate-300">{v}</span>
                  </div>
                );
              })}
            </div>
          </div>
          <div className="p-6 bg-slate-900/50 rounded-2xl border border-border">
            <h4 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-4">Your Mapping</h4>
            <div className="space-y-2">
              {userPairs.length > 0 ? userPairs.map((p, i) => {
                const [k, v] = p.split(':');
                const isCorrect = correctPairs.includes(p);
                return (
                  <div key={i} className={`flex items-center justify-between p-3 rounded-lg text-xs font-bold border ${isCorrect ? 'bg-success/10 border-success/30 text-success' : 'bg-danger/10 border-danger/30 text-danger'}`}>
                    <span className="truncate max-w-[40%]">{k}</span>
                    <span className="shrink-0">→</span>
                    <span className="truncate max-w-[40%]">{v}</span>
                    {isCorrect ? <CheckIcon className="w-3 h-3" /> : <XIcon className="w-3 h-3" />}
                  </div>
                );
              }) : <p className="text-xs italic text-slate-500 py-4 text-center">No matches provided</p>}
            </div>
          </div>
        </div>
      );
    };

    return (
        <div className="bg-card/50 backdrop-blur-md p-8 md:p-12 my-6 rounded-[2.5rem] border border-border animate-fade-in shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 p-8 flex gap-2">
               {userAnswer === null ? (
                 <span className="bg-yellow-400/20 text-yellow-400 text-[10px] font-black px-3 py-1 rounded-full border border-yellow-400/30 tracking-widest uppercase">Skipped</span>
               ) : (
                 JSON.stringify(userAnswer) === JSON.stringify(question.answer) 
                  ? <span className="bg-success/20 text-success text-[10px] font-black px-3 py-1 rounded-full border border-success/30 tracking-widest uppercase flex items-center gap-1"><CheckIcon className="w-3 h-3" /> Correct</span>
                  : <span className="bg-danger/20 text-danger text-[10px] font-black px-3 py-1 rounded-full border border-danger/30 tracking-widest uppercase flex items-center gap-1"><XIcon className="w-3 h-3" /> Incorrect</span>
               )}
            </div>

            <span className="text-[10px] font-black bg-primary/20 text-primary-light px-3 py-1 rounded-full uppercase tracking-widest mb-6 inline-block border border-primary/20">
                {question.type} • REVIEW
            </span>

            {question.context && (
                <div className="mb-8 p-6 bg-slate-800/40 rounded-2xl text-sm text-slate-400 italic font-serif leading-relaxed">
                    {question.context}
                </div>
            )}

            <h3 className="text-2xl font-black mb-10 text-slate-100 leading-tight">{question.question}</h3>

            {question.type === 'Matching' ? (
              renderMatchingReview()
            ) : question.type === 'BuildList' ? (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                  <div className="bg-slate-900/40 p-6 rounded-2xl border border-border">
                    <h4 className="text-xs font-black text-primary uppercase tracking-widest mb-4">Correct Sequence</h4>
                    <div className="space-y-2">
                        {Array.isArray(question.answer) && question.answer.map((ans, i) => (
                            <div key={i} className="flex items-center gap-4 text-sm text-slate-200 bg-slate-800 p-3 rounded-xl border border-slate-700">
                                <span className="w-6 h-6 flex items-center justify-center bg-primary text-white rounded-lg font-black text-xs">{i+1}</span>
                                <span className="font-semibold">{ans}</span>
                            </div>
                        ))}
                    </div>
                  </div>
                  <div className="bg-slate-900/40 p-6 rounded-2xl border border-border">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-4">Your Sequence</h4>
                    <div className="space-y-2">
                        {Array.isArray(userAnswer) && userAnswer.length > 0 ? userAnswer.map((ans, i) => {
                            const isCorrectPos = Array.isArray(question.answer) && question.answer[i] === ans;
                            return (
                                <div key={i} className={`flex items-center gap-4 text-sm p-3 rounded-xl border transition-colors ${isCorrectPos ? 'bg-success/10 border-success/30' : 'bg-danger/10 border-danger/30'}`}>
                                    <span className={`w-6 h-6 flex items-center justify-center rounded-lg font-black text-xs ${isCorrectPos ? 'bg-success text-white' : 'bg-danger text-white'}`}>{i+1}</span>
                                    <span className={`font-semibold ${isCorrectPos ? 'text-success' : 'text-danger'}`}>{ans}</span>
                                    <div className="ml-auto">{isCorrectPos ? <CheckIcon className="w-4 h-4" /> : <XIcon className="w-4 h-4" />}</div>
                                </div>
                            );
                        }) : <p className="text-xs italic text-slate-500 py-8 text-center">No items ordered</p>}
                    </div>
                  </div>
              </div>
            ) : (
              <div className="space-y-4 mb-10">
                  {question.options.map((option, index) => (
                      <div key={index} className={`p-5 rounded-[1.5rem] border-2 flex items-center justify-between transition-all ${getOptionClass(option)}`}>
                          <span className="text-base font-bold">{option}</span>
                          <div className="flex gap-2">
                               {isOptionCorrect(option) && <CheckIcon />}
                               {isOptionSelected(option) && !isOptionCorrect(option) && <XIcon />}
                          </div>
                      </div>
                  ))}
              </div>
            )}

            <div className="mt-12 bg-slate-900/20 rounded-[2rem] p-4">
                 <DexterExplains question={question} userAnswer={userAnswer} />
            </div>
        </div>
    );
};

