import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';
import { CheckIcon } from './icons/CheckIcon';
import { XIcon } from './icons/XIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [nextQuestion, setNextQuestion] = useState<Question | null>(null);
  const [selectedAnswer, setSelectedAnswer] = useState<string | string[] | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [matchingPairs, setMatchingPairs] = useState<Record<string, string>>({});
  const [selectedMatchKey, setSelectedMatchKey] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch (e) {}
        audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  useEffect(() => {
    if (timer === 0) return;
    if (timeLeft <= 0) { finishQuiz(); return; }
    const intervalId = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  const prefetchNext = useCallback(async (index: number) => {
    const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
    if (index + 1 >= totalInSet || mode === 'BookmarkReview') return;

    try {
      const q = await generateQuestion(difficulty, category);
      setNextQuestion(q);
    } catch (err) {
      console.error("Prefetch failed", err);
    }
  }, [difficulty, category, mode, bookmarkedQuestions.length]);

  useEffect(() => {
    const loadInitialQuestion = async () => {
      setIsLoading(true);
      setError(null);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) { onQuizEnd([], 0); return; }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          const firstQuestion = await generateQuestion(difficulty, category);
          setQuestions([firstQuestion]);
          setIsLoading(false);
          prefetchNext(0);
        } catch (err) {
          setError("Failed to generate question.");
          setIsLoading(false);
        }
      }
    };
    loadInitialQuestion();
  }, [difficulty, category, mode, bookmarkedQuestions, onQuizEnd, prefetchNext]);

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
    if (!currentQuestion) return;
    setIsGeneratingAudio(true);
    try {
        if (!audioContextRef.current) audioContextRef.current = new AudioContext();
        const textToRead = `${currentQuestion.context || ''} ${currentQuestion.question}`;
        const buffer = await generateSpeech(textToRead, 'Zephyr', audioContextRef.current);
        setIsGeneratingAudio(false);
        setIsSpeaking(true);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsSpeaking(false);
        audioSourceRef.current = source;
        source.start();
    } catch (err) {
        setIsGeneratingAudio(false);
        setIsSpeaking(false);
    }
  };

  const toggleMultiSelect = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr.filter(o => o !== option);
      return [...arr, option];
    });
  };

  const handleBuildListAdd = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr;
      return [...arr, option];
    });
  };

  const handleBuildListRemove = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      return arr.filter(o => o !== option);
    });
  };

  const handleMatchingClick = (item: string, isKey: boolean) => {
    if (quizState === 'answered') return;
    if (isKey) {
      setSelectedMatchKey(item === selectedMatchKey ? null : item);
    } else {
      if (selectedMatchKey) {
        setMatchingPairs(prev => {
          const next = { ...prev };
          Object.keys(next).forEach(k => {
            if (next[k] === item) delete next[k];
          });
          next[selectedMatchKey] = item;
          return next;
        });
        setSelectedMatchKey(null);
      }
    }
  };

  const handleSubmit = () => {
    let finalAnswer: string | string[] | null = selectedAnswer;

    if (currentQuestion.type === 'Matching') {
      finalAnswer = Object.entries(matchingPairs).map(([k, v]) => `${k}:${v}`);
    }

    if (!finalAnswer || (Array.isArray(finalAnswer) && finalAnswer.length === 0) || quizState !== 'answering') return;

    let isCorrect = false;
    const cleanAnswer = currentQuestion.answer;

    if (currentQuestion.type === 'MultipleChoice' || currentQuestion.type === 'CaseStudy') {
      // Robust check for single choice types which might be returned as string or array by AI
      const normalizedCorrect = Array.isArray(cleanAnswer) ? cleanAnswer[0] : cleanAnswer;
      isCorrect = finalAnswer === normalizedCorrect;
    } else {
      const userArr = Array.isArray(finalAnswer) ? finalAnswer : [finalAnswer];
      const correctArr = Array.isArray(cleanAnswer) ? cleanAnswer : [cleanAnswer];

      if (currentQuestion.type === 'BuildList') {
        isCorrect = JSON.stringify(userArr) === JSON.stringify(correctArr);
      } else if (currentQuestion.type === 'Matching') {
        isCorrect = userArr.length === correctArr.length && [...userArr].sort().join(',') === [...correctArr].sort().join(',');
      } else {
        isCorrect = userArr.length === correctArr.length && userArr.every(v => correctArr.includes(v));
      }
    }

    setResults(prev => [...prev, { question: currentQuestion, userAnswer: finalAnswer, isCorrect }]);
    setQuizState('answered');
  };

  const handleNextQuestion = async () => {
    stopSpeaking();
    const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
    const nextIdx = currentQuestionIndex + 1;

    if (nextIdx >= totalInSet) { finishQuiz(); return; }

    if (mode === 'BookmarkReview') {
      setCurrentQuestionIndex(nextIdx);
      setSelectedAnswer(null);
      setMatchingPairs({});
      setQuizState('answering');
      return;
    }

    if (nextQuestion) {
      setQuestions(prev => [...prev, nextQuestion]);
      setNextQuestion(null);
      setCurrentQuestionIndex(nextIdx);
      setSelectedAnswer(null);
      setMatchingPairs({});
      setQuizState('answering');
      prefetchNext(nextIdx);
    } else {
      setIsLoading(true);
      try {
        const q = await generateQuestion(difficulty, category);
        setQuestions(prev => [...prev, q]);
        setCurrentQuestionIndex(nextIdx);
        setSelectedAnswer(null);
        setMatchingPairs({});
        setQuizState('answering');
        prefetchNext(nextIdx);
      } catch (err) {
        setError("Failed to load next question.");
      } finally {
        setIsLoading(false);
      }
    }
  };

  const renderOptions = () => {
    const { type, options, answer } = currentQuestion;
    const isAnswered = quizState === 'answered';
    const isMultiCorrect = Array.isArray(answer);

    switch (type) {
      case 'MultiSelect':
        return (
          <div className="space-y-3 animate-fade-in-up">
            <p className="text-sm text-primary-light font-black mb-2 uppercase tracking-tight">Select all correct options:</p>
            {options.map((opt, i) => {
              const isSelected = Array.isArray(selectedAnswer) && selectedAnswer.includes(opt);
              const isCorrect = isMultiCorrect ? (answer as string[]).includes(opt) : answer === opt;

              let styleClass = 'border-border bg-card hover:border-slate-500';
              if (isAnswered) {
                if (isCorrect) styleClass = 'border-success bg-success/10 ring-2 ring-success/20';
                else if (isSelected) styleClass = 'border-danger bg-danger/10 ring-2 ring-danger/20';
                else styleClass = 'border-border bg-card opacity-50';
              } else if (isSelected) {
                styleClass = 'border-primary bg-primary/10 ring-2 ring-primary/20';
              }

              return (
                <button key={i} onClick={() => toggleMultiSelect(opt)} disabled={isAnswered} className={`w-full text-left p-5 rounded-2xl border-2 flex items-center justify-between transition-all shadow-sm ${styleClass} min-h-[64px]`}>
                  <div className="flex items-center gap-4 flex-1 mr-4">
                    <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center shrink-0 transition-colors ${isAnswered ? (isCorrect ? 'bg-success border-success' : (isSelected ? 'bg-danger border-danger' : 'border-slate-600')) : (isSelected ? 'bg-primary border-primary' : 'border-slate-600')}`}>
                      {isSelected && <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>}
                    </div>
                    <span className="font-medium text-slate-200 break-words flex-1">{opt}</span>
                  </div>
                  <div className="shrink-0">
                    {isAnswered && (isCorrect ? <CheckIcon className="w-5 h-5" /> : (isSelected ? <XIcon className="w-5 h-5" /> : null))}
                  </div>
                </button>
              );
            })}
          </div>
        );
      case 'BuildList':
        const buildListSelected = Array.isArray(selectedAnswer) ? selectedAnswer : [];
        const buildListAvailable = options.filter(o => !buildListSelected.includes(o));
        return (
          <div className="space-y-6 animate-fade-in-up">
             <p className="text-sm text-primary-light font-black mb-2 uppercase tracking-tight">Arrange steps in correct logical order:</p>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Available Actions</h4>
                    <div className="bg-slate-900/50 p-4 rounded-2xl border border-border min-h-[200px] space-y-2">
                        {buildListAvailable.map((opt, i) => (
                            <button key={i} onClick={() => handleBuildListAdd(opt)} disabled={isAnswered} className="w-full text-left p-4 bg-slate-800 border border-slate-700 rounded-xl text-sm font-medium hover:border-primary hover:bg-slate-700 transition-all shadow-md group break-words">
                                <span className="group-hover:text-primary transition-colors">{opt}</span>
                            </button>
                        ))}
                    </div>
                </div>
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Ordered Sequence</h4>
                    <div className="bg-slate-900/50 p-4 rounded-2xl border border-border min-h-[200px] space-y-2">
                        {buildListSelected.map((opt, i) => {
                            const isCorrectPos = isAnswered && Array.isArray(answer) && answer[i] === opt;
                            return (
                                <button key={i} onClick={() => handleBuildListRemove(opt)} disabled={isAnswered} className={`w-full text-left p-4 border rounded-xl text-sm flex items-center justify-between group transition-all min-h-[56px] ${isAnswered ? (isCorrectPos ? 'bg-success/20 border-success/50' : 'bg-danger/20 border-danger/50') : 'bg-primary/20 border-primary/50 hover:bg-primary/30'}`}>
                                    <div className="flex items-center gap-4 flex-1">
                                        <span className={`w-6 h-6 flex items-center justify-center rounded-lg font-black text-xs shrink-0 ${isAnswered ? (isCorrectPos ? 'bg-success text-white' : 'bg-danger text-white') : 'bg-primary text-white'}`}>{i+1}</span>
                                        <span className={`font-semibold flex-1 break-words ${isAnswered ? (isCorrectPos ? 'text-success' : 'text-danger') : 'text-slate-100'}`}>{opt}</span>
                                    </div>
                                    <div className="shrink-0 ml-2">
                                      {isAnswered && (isCorrectPos ? <CheckIcon className="w-4 h-4" /> : <XIcon className="w-4 h-4" />)}
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
             </div>
          </div>
        );
      case 'Matching':
         const half = Math.ceil(options.length / 2);
         const keys = options.slice(0, half);
         const targets = options.slice(half);

         return (
          <div className="space-y-6 animate-fade-in-up">
             <p className="text-sm text-primary-light font-black mb-2 uppercase tracking-tight">Match items from the left to categories on the right:</p>
             <div className="grid grid-cols-2 gap-10">
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Items</h4>
                    <div className="space-y-3">
                        {keys.map((k, i) => {
                          const matchedVal = matchingPairs[k];
                          return (
                            <button key={i} onClick={() => handleMatchingClick(k, true)} disabled={isAnswered} className={`w-full text-left p-4 rounded-xl border-2 text-sm font-bold transition-all flex justify-between items-center break-words min-h-[56px] ${selectedMatchKey === k ? 'border-primary bg-primary/20 scale-105 shadow-xl' : matchedVal ? 'border-success/50 bg-success/5' : 'border-border bg-card hover:border-slate-500'}`}>
                                <span className="flex-1">{k}</span>
                                {matchedVal && <span className="shrink-0 text-[10px] bg-success/20 text-success px-2 py-0.5 rounded-full uppercase tracking-tighter ml-2">Matched</span>}
                            </button>
                          );
                        })}
                    </div>
                </div>
                <div className="space-y-3">
                    <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Categories</h4>
                    <div className="space-y-3">
                        {targets.map((t, i) => {
                          const matchedKey = Object.keys(matchingPairs).find(k => matchingPairs[k] === t);
                          return (
                            <button key={i} onClick={() => handleMatchingClick(t, false)} disabled={isAnswered || !selectedMatchKey} className={`w-full text-left p-4 rounded-xl border-2 text-sm font-bold transition-all flex flex-col gap-1 min-h-[56px] ${matchedKey ? 'border-primary bg-primary/10' : selectedMatchKey ? 'border-primary/50 bg-primary/5 animate-pulse' : 'border-border bg-card'}`}>
                                <span className="text-slate-200 break-words">{t}</span>
                                {matchedKey && <span className="text-[9px] text-primary bg-primary/10 p-1 rounded font-black mt-1 line-clamp-1">← {matchedKey}</span>}
                            </button>
                          );
                        })}
                    </div>
                </div>
             </div>
          </div>
         );
      default:
        return (
          <div className="space-y-3 animate-fade-in-up">
            {options.map((opt, i) => {
              const isSelected = selectedAnswer === opt;
              const normalizedCorrect = Array.isArray(answer) ? answer[0] : answer;
              const isCorrect = normalizedCorrect === opt;

              let styleClass = 'border-border bg-card hover:border-slate-500';
              if (isAnswered) {
                if (isCorrect) styleClass = 'border-success bg-success/10 ring-2 ring-success/20';
                else if (isSelected) styleClass = 'border-danger bg-danger/10 ring-2 ring-danger/20';
                else styleClass = 'border-border bg-card opacity-50';
              } else if (isSelected) {
                styleClass = 'border-primary bg-primary/10 ring-2 ring-primary/20';
              }

              return (
                <button key={i} onClick={() => setSelectedAnswer(opt)} disabled={isAnswered} className={`w-full text-left p-5 rounded-2xl border-2 flex items-center justify-between transition-all shadow-sm ${styleClass} min-h-[64px]`}>
                   <div className="flex items-center gap-5 flex-1 mr-4">
                      <div className={`w-6 h-6 rounded-full border-2 transition-all shrink-0 ${isAnswered ? (isCorrect ? 'border-success bg-success' : (isSelected ? 'border-danger bg-danger' : 'border-slate-600')) : (isSelected ? 'border-primary bg-primary ring-4 ring-primary/20' : 'border-slate-600')}`} />
                      <span className={`font-semibold break-words flex-1 ${isAnswered ? (isCorrect ? 'text-success' : (isSelected ? 'text-danger' : 'text-slate-400')) : 'text-slate-200'}`}>{opt}</span>
                   </div>
                   <div className="shrink-0">
                    {isAnswered && (isCorrect ? <CheckIcon className="w-5 h-5" /> : (isSelected ? <XIcon className="w-5 h-5" /> : null))}
                   </div>
                </button>
              );
            })}
          </div>
        );
    }
  };

  if (isLoading && questions.length === 0) return <Loader text="Assembling dynamic exam content..." />;

  const isMatchingComplete = currentQuestion?.type === 'Matching' 
    ? Object.keys(matchingPairs).length === Math.ceil(currentQuestion.options.length / 2)
    : !!selectedAnswer && (!Array.isArray(selectedAnswer) || selectedAnswer.length > 0);

  const lastResult = results[results.length - 1];

  return (
    <div className="max-w-5xl mx-auto animate-fade-in pb-20 px-4 sm:px-0">
        <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-black tracking-tight flex items-center gap-4 text-slate-100">
                <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center text-white shadow-lg shadow-primary/20">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                </div>
                <span className="truncate max-w-[200px] md:max-w-none">{mode === 'Exam' ? 'Exam Simulation' : category === 'All' ? 'Full Practice' : category}</span>
            </h2>
            {timer > 0 && (
                <div className="flex items-center gap-3 font-mono font-bold px-4 py-2 rounded-xl border border-border bg-slate-900/80 backdrop-blur-md">
                    <StopwatchIcon className="w-5 h-5 text-primary" />
                    <span className="text-lg text-slate-100 tracking-wider">{Math.floor(timeLeft/60)}:{(timeLeft%60).toString().padStart(2, '0')}</span>
                </div>
            )}
        </div>

        {currentQuestion.context && (
            <div className="mb-10 p-6 md:p-8 bg-slate-800/40 backdrop-blur-sm rounded-3xl border-l-8 border-primary shadow-2xl animate-fade-in-up">
                <h4 className="text-[10px] font-black uppercase text-primary tracking-[0.2em] mb-4">Case Study Scenario</h4>
                <div className="text-slate-300 text-base md:text-lg leading-relaxed font-serif">
                    {currentQuestion.context}
                </div>
            </div>
        )}

        <div className="bg-card/80 backdrop-blur-xl p-8 sm:p-12 rounded-[2.5rem] shadow-2xl border border-border relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-6 flex gap-3 z-10">
                <button onClick={handleReadAloud} className={`p-2.5 rounded-xl transition-all shadow-md ${isSpeaking || isGeneratingAudio ? 'bg-danger text-white' : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'}`}>
                    {isSpeaking || isGeneratingAudio ? <StopIcon className="w-5 h-5" /> : <SpeakerIcon className="w-5 h-5" />}
                </button>
                <button onClick={() => onToggleBookmark(currentQuestion)} className={`p-2.5 rounded-xl transition-all shadow-md ${isBookmarked(currentQuestion) ? 'text-yellow-400 bg-yellow-400/20' : 'text-slate-500 hover:text-yellow-400 bg-slate-800/80 hover:bg-slate-700'}`}>
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} className="w-5 h-5" />
                </button>
            </div>

            <div className="mb-10">
               <span className="inline-block bg-primary/20 text-primary-light text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-[0.15em] mb-6 border border-primary/20">
                 {currentQuestion.type} • ITEM {currentQuestionIndex + 1} OF {mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS}
               </span>
               <h3 className="text-xl md:text-2xl font-black leading-snug text-white pr-20">{currentQuestion.question}</h3>
            </div>

            <div className="min-h-[250px]">
              {renderOptions()}
            </div>

            {quizState === 'answered' && lastResult && (
                <div className="mt-12 pt-10 border-t border-border animate-fade-in-up">
                    <div className={`mb-8 p-5 rounded-2xl border-2 flex items-center gap-5 ${lastResult.isCorrect ? 'bg-success/10 border-success/30 text-success' : 'bg-danger/10 border-danger/30 text-danger'}`}>
                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${lastResult.isCorrect ? 'bg-success text-white' : 'bg-danger text-white shadow-lg shadow-danger/20'}`}>
                            {lastResult.isCorrect ? <CheckIcon className="w-7 h-7" /> : <XIcon className="w-7 h-7" />}
                        </div>
                        <div>
                            <h4 className="text-xl font-black uppercase tracking-tight">{lastResult.isCorrect ? 'Correct! Well Done' : 'Incorrect Answer'}</h4>
                            <p className="text-xs opacity-80 font-bold">{lastResult.isCorrect ? 'You correctly identified the key concept.' : 'See the detailed explanation below for guidance.'}</p>
                        </div>
                    </div>
                    <DexterExplains 
                      question={currentQuestion} 
                      userAnswer={lastResult.userAnswer} 
                    />
                </div>
            )}

            <div className="mt-12 flex flex-col sm:flex-row gap-4">
                {quizState === 'answering' ? (
                    <button 
                      onClick={handleSubmit} 
                      disabled={!isMatchingComplete} 
                      className="flex-1 bg-primary hover:bg-primary/90 text-white font-black py-4 px-8 rounded-2xl text-lg shadow-xl shadow-primary/30 transition-all disabled:opacity-30 disabled:cursor-not-allowed hover:scale-[1.01] active:scale-95"
                    >
                        Check Final Answer
                    </button>
                ) : (
                    <button 
                      onClick={handleNextQuestion} 
                      className="flex-1 bg-primary hover:bg-primary/90 text-white font-black py-4 px-8 rounded-2xl text-lg shadow-xl shadow-primary/30 transition-all flex items-center justify-center gap-3 hover:scale-[1.01] active:scale-95"
                    >
                        {currentQuestionIndex + 1 === (mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS) ? 'View Final Report' : 'Next Question'}
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                    </button>
                )}
            </div>
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Question, Difficulty, QuestionCategory, StudyGuideLength, QuestionType } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY! });

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const questionSchema = {
  type: Type.OBJECT,
  properties: {
    type: { 
        type: Type.STRING, 
        enum: ['MultipleChoice', 'MultiSelect', 'BuildList', 'Matching', 'CaseStudy']
    },
    question: { type: Type.STRING },
    context: { type: Type.STRING, description: 'Optional: Detailed scenario for CaseStudy types.' },
    options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: 'List of options. For matching, options contain both sets.'
    },
    answer: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: 'For MultipleChoice, a single string in an array. For MultiSelect, multiple strings. For BuildList, the strings in the correct order. For Matching, pairs like "Item:Target".'
    },
    explanation: { type: Type.STRING },
    category: {
      type: Type.STRING,
      enum: ['Prepare the data', 'Model the data', 'Visualize and analyze the data', 'Deploy and maintain assets']
    },
    difficulty: {
      type: Type.STRING,
      enum: ['Easy', 'Medium', 'Hard']
    }
  },
  required: ['type', 'question', 'options', 'answer', 'explanation', 'category', 'difficulty']
};

export const generateQuestion = async (difficulty: Difficulty, category: QuestionCategory | 'All' = 'All'): Promise<Question> => {
    const model = 'gemini-3-pro-preview';
    const randomType = ['MultipleChoice', 'MultiSelect', 'BuildList', 'Matching', 'CaseStudy'][Math.floor(Math.random() * 5)];

    const prompt = `Generate a high-quality ${randomType} question for the Microsoft PL-300 Power BI exam.
    Category: ${category}
    Difficulty: ${difficulty === 'Adaptive' ? 'appropriate for level' : difficulty}

    REQUIREMENTS BY TYPE:
    - MultiSelect: User must choose 2 or 3 correct options.
    - BuildList: User must arrange actions in correct chronological/logical order.
    - Matching: User must match items from Column A to Column B.
    - CaseStudy: Provide a "context" field with a business scenario, followed by a specific question.
    - MultipleChoice: Single correct answer.

    Return the output in the specified JSON format. Ensure 'answer' is an array of strings.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: questionSchema,
                temperature: 0.9,
            },
        });

        const generated = JSON.parse(response.text);
        // Normalize answer format for single-choice types
        if ((generated.type === 'MultipleChoice' || generated.type === 'CaseStudy') && Array.isArray(generated.answer)) {
            generated.answer = generated.answer[0];
        }
        return generated as Question;
    } catch (error) {
        console.error("Error generating question:", error);
        throw new Error("Failed to generate question.");
    }
};

export const generateSpeech = async (text: string, voiceName: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Read this exam question clearly: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data");

        return await decodeAudioData(decodeBase64(base64Audio), audioContext, 24000, 1);
    } catch (error) {
        console.error("Error generating speech:", error);
        throw error;
    }
};

export const getPersonalizedFeedback = async (question: Question, userAnswer: any): Promise<string> => {
    const model = 'gemini-3-flash-preview';
    const isCorrect = JSON.stringify(userAnswer) === JSON.stringify(question.answer);

    const prompt = `Provide professional feedback for a PL-300 student who just answered a question.

    IMPORTANT: The student was ${isCorrect ? 'CORRECT' : 'INCORRECT'}. Start your feedback accordingly.

    Question: ${JSON.stringify(question.question)}
    Context: ${question.context || 'N/A'}
    Correct Answer: ${JSON.stringify(question.answer)}
    User provided: ${JSON.stringify(userAnswer)}

