            return (
                <div className="flex items-center justify-center h-[300px] text-center text-slate-500 dark:text-slate-400 p-4">
                    <p>Complete at least two quiz sessions to see your accuracy trend over time.</p>
                </div>
            );
        }

        const colors = theme === 'light' ? {
            grid: 'rgba(0, 0, 0, 0.1)',
            axis: '#475569',
            tooltipBg: 'hsl(0, 0%, 100%)',
            tooltipBorder: 'hsl(214, 32%, 91%)',
            tooltipColor: '#0f172a',
            primary: 'hsl(262, 80%, 48%)',
            primaryLight: 'hsl(262, 80%, 48%)',
        } : theme === 'dim' ? {
            grid: 'rgba(255, 255, 255, 0.08)',
            axis: '#94a3b8',
            tooltipBg: 'hsl(215, 25%, 32%)',
