export const generateRelatedTips = async (question: any) => { return []; };

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';
import { CheckIcon } from './icons/CheckIcon';
import { XIcon } from './icons/XIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [nextQuestion, setNextQuestion] = useState<Question | null>(null);
  const [selectedAnswer, setSelectedAnswer] = useState<string | string[] | null>(null);
  const [results, setResults] = useState<ExamResult[]>([]);
  const [quizState, setQuizState] = useState<'answering' | 'answered'>('answering');
  const [isLoading, setIsLoading] = useState(true);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [matchingPairs, setMatchingPairs] = useState<Record<string, string>>({});
  const [selectedMatchKey, setSelectedMatchKey] = useState<string | null>(null);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch (e) {}
        audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    onQuizEnd(results, timeTaken);
  }, [onQuizEnd, results, timer, timeLeft]);

  useEffect(() => {
    if (timer === 0) return;
    if (timeLeft <= 0) { finishQuiz(); return; }
    const intervalId = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  const prefetchNext = useCallback(async (index: number) => {
    const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
    if (index + 1 >= totalInSet || mode === 'BookmarkReview') return;

    try {
      const q = await generateQuestion(difficulty, category);
      setNextQuestion(q);
    } catch (err) {
      console.warn("Prefetch retry on demand.");
    }
  }, [difficulty, category, mode, bookmarkedQuestions.length]);

  useEffect(() => {
    const loadInitialQuestion = async () => {
      setIsLoading(true);
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) { onQuizEnd([], 0); return; }
        setQuestions(bookmarkedQuestions);
        setIsLoading(false);
      } else {
        try {
          // Parallelize the first two requests to ensure question 2 is ready before user even clicks "Check" on Q1
          const [q1, q2] = await Promise.all([
            generateQuestion(difficulty, category),
            generateQuestion(difficulty, category)
          ]);
          setQuestions([q1]);
          setNextQuestion(q2);
          setIsLoading(false);
        } catch (err) {
          setError("Generation failed. Please check your connection.");
          setIsLoading(false);
        }
      }
    };
    loadInitialQuestion();
  }, [difficulty, category, mode, bookmarkedQuestions, onQuizEnd]);

  // Handle prefetching when moving to next questions
  useEffect(() => {
    if (currentQuestionIndex > 0 && !nextQuestion) {
      prefetchNext(currentQuestionIndex);
    }
  }, [currentQuestionIndex, nextQuestion, prefetchNext]);

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
    if (!currentQuestion) return;
    setIsGeneratingAudio(true);
    try {
        if (!audioContextRef.current) audioContextRef.current = new AudioContext();
        const textToRead = `${currentQuestion.context || ''} ${currentQuestion.question}`;
        const buffer = await generateSpeech(textToRead, 'Zephyr', audioContextRef.current);
        setIsGeneratingAudio(false);
        setIsSpeaking(true);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsSpeaking(false);
        audioSourceRef.current = source;
        source.start();
    } catch (err) {
        setIsGeneratingAudio(false);
        setIsSpeaking(false);
    }
  };

  const toggleMultiSelect = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr.filter(o => o !== option);
      return [...arr, option];
    });
  };

  const handleBuildListAdd = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      if (arr.includes(option)) return arr;
      return [...arr, option];
    });
  };

  const handleBuildListRemove = (option: string) => {
    if (quizState === 'answered') return;
    setSelectedAnswer(prev => {
      const arr = Array.isArray(prev) ? prev : [];
      return arr.filter(o => o !== option);
    });
  };

  const handleMatchingClick = (item: string, isKey: boolean) => {
    if (quizState === 'answered') return;
    if (isKey) {
      setSelectedMatchKey(item === selectedMatchKey ? null : item);
    } else {
      if (selectedMatchKey) {
        setMatchingPairs(prev => {
          const next = { ...prev };
          Object.keys(next).forEach(k => { if (next[k] === item) delete next[k]; });
          next[selectedMatchKey] = item;
          return next;
        });
        setSelectedMatchKey(null);
      }
    }
  };

  const handleSubmit = () => {
    let finalAnswer: string | string[] | null = selectedAnswer;
    if (currentQuestion.type === 'Matching') {
      finalAnswer = Object.entries(matchingPairs).map(([k, v]) => `${k}:${v}`);
    }
    if (!finalAnswer || (Array.isArray(finalAnswer) && finalAnswer.length === 0) || quizState !== 'answering') return;

    let isCorrect = false;
    const cleanAnswer = currentQuestion.answer;
    if (currentQuestion.type === 'MultipleChoice' || currentQuestion.type === 'CaseStudy') {
      const normalizedCorrect = Array.isArray(cleanAnswer) ? cleanAnswer[0] : cleanAnswer;
      isCorrect = finalAnswer === normalizedCorrect;
    } else {
      const userArr = Array.isArray(finalAnswer) ? finalAnswer : [finalAnswer];
      const correctArr = Array.isArray(cleanAnswer) ? cleanAnswer : [cleanAnswer];
      if (currentQuestion.type === 'BuildList') {
        isCorrect = JSON.stringify(userArr) === JSON.stringify(correctArr);
      } else if (currentQuestion.type === 'Matching') {
        isCorrect = userArr.length === correctArr.length && [...userArr].sort().join(',') === [...correctArr].sort().join(',');
      } else {
        isCorrect = userArr.length === correctArr.length && userArr.every(v => correctArr.includes(v));
      }
    }
    setResults(prev => [...prev, { question: currentQuestion, userAnswer: finalAnswer, isCorrect }]);
    setQuizState('answered');
  };

  const handleNextQuestion = async () => {
    stopSpeaking();
    const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
    const nextIdx = currentQuestionIndex + 1;

    if (nextIdx >= totalInSet) { 
      finishQuiz(); 
      return; 
    }

    if (mode === 'BookmarkReview') {
      setCurrentQuestionIndex(nextIdx);
      setSelectedAnswer(null);
      setQuizState('answering');
      return;
    }

    if (nextQuestion) {
      setQuestions(prev => [...prev, nextQuestion]);
      setNextQuestion(null);
      setCurrentQuestionIndex(nextIdx);
      setSelectedAnswer(null);
      setMatchingPairs({});
      setQuizState('answering');
    } else {
      setIsLoading(true);
      try {
        const q = await generateQuestion(difficulty, category);
        setQuestions(prev => [...prev, q]);
        setCurrentQuestionIndex(nextIdx);
        setSelectedAnswer(null);
        setMatchingPairs({});
        setQuizState('answering');
      } catch (err) {
        setError("Network error. Retrying...");
      } finally {
        setIsLoading(false);
      }
    }
  };

  const renderOptions = () => {
    const { type, options, answer } = currentQuestion;
    const isAnswered = quizState === 'answered';
    const isMultiCorrect = Array.isArray(answer);

    switch (type) {
      case 'MultiSelect':
        return (
          <div className="grid grid-cols-1 gap-3">
            {options.map((opt, i) => {
              const isSelected = Array.isArray(selectedAnswer) && selectedAnswer.includes(opt);
              const isCorrect = isMultiCorrect ? (answer as string[]).includes(opt) : answer === opt;
              let styleClass = 'border-border bg-card hover:border-slate-500';
              if (isAnswered) {
                if (isCorrect) styleClass = 'border-success bg-success/10 ring-2 ring-success/20';
                else if (isSelected) styleClass = 'border-danger bg-danger/10 ring-2 ring-danger/20';
                else styleClass = 'border-border bg-card opacity-50';
              } else if (isSelected) styleClass = 'border-primary bg-primary/10 ring-2 ring-primary/20';
              return (
                <button key={i} onClick={() => toggleMultiSelect(opt)} disabled={isAnswered} className={`w-full text-left px-5 py-4 rounded-xl border-2 flex items-center justify-between transition-all shadow-sm ${styleClass} min-h-[56px]`}>
                  <div className="flex items-start gap-4 flex-1">
                    <div className={`w-5 h-5 rounded border-2 mt-0.5 shrink-0 flex items-center justify-center ${isSelected ? 'bg-primary border-primary' : 'border-slate-600'}`}>
                      {isSelected && <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"/></svg>}
                    </div>
                    <span className="text-[14px] font-semibold text-slate-800 dark:text-slate-200 break-words leading-tight">{opt}</span>
                  </div>
                  {isAnswered && (isCorrect ? <CheckIcon className="w-5 h-5 shrink-0 ml-2" /> : (isSelected ? <XIcon className="w-5 h-5 shrink-0 ml-2" /> : null))}
                </button>
              );
            })}
          </div>
        );
      case 'BuildList':
        const buildListSelected = Array.isArray(selectedAnswer) ? selectedAnswer : [];
        const buildListAvailable = options.filter(o => !buildListSelected.includes(o));
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-3">
              <h4 className="text-[10px] font-black uppercase text-slate-500 pl-1">Available</h4>
              <div className="bg-slate-900/40 p-3 rounded-xl border border-border min-h-[160px] space-y-2">
                {buildListAvailable.map((opt, i) => (
                  <button key={i} onClick={() => handleBuildListAdd(opt)} disabled={isAnswered} className="w-full text-left p-3 bg-white dark:bg-slate-800 border border-border dark:border-slate-700 rounded-lg text-xs font-bold hover:border-primary transition-all break-words text-slate-800 dark:text-slate-200">{opt}</button>
                ))}
              </div>
            </div>
            <div className="space-y-3">
              <h4 className="text-[10px] font-black uppercase text-slate-500 pl-1">Selected Order</h4>
              <div className="bg-slate-900/40 p-3 rounded-xl border border-border min-h-[160px] space-y-2">
                {buildListSelected.map((opt, i) => {
                  const isCorrectPos = isAnswered && Array.isArray(answer) && answer[i] === opt;
                  return (
                    <button key={i} onClick={() => handleBuildListRemove(opt)} disabled={isAnswered} className={`w-full text-left p-3 rounded-lg border text-xs flex items-center justify-between transition-all ${isAnswered ? (isCorrectPos ? 'bg-success/20 border-success/40' : 'bg-danger/20 border-danger/40') : 'bg-primary/10 border-primary/30 hover:bg-primary/20'}`}>
                      <div className="flex items-center gap-2 overflow-hidden">
                        <span className="shrink-0 w-5 h-5 flex items-center justify-center bg-primary/20 rounded-md text-[10px] font-black text-primary">{i+1}</span>
                        <span className="font-bold break-words text-slate-800 dark:text-slate-100">{opt}</span>
                      </div>
                      {isAnswered && (isCorrectPos ? <CheckIcon className="w-3 h-3 ml-2 shrink-0" /> : <XIcon className="w-3 h-3 ml-2 shrink-0" />)}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        );
      case 'Matching':
        const keys = options.slice(0, Math.ceil(options.length / 2));
        const targets = options.slice(Math.ceil(options.length / 2));
        return (
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              {keys.map((k, i) => {
                const matchedVal = matchingPairs[k];
                return (
                  <button key={i} onClick={() => handleMatchingClick(k, true)} disabled={isAnswered} className={`w-full text-left p-3 rounded-xl border-2 text-[11px] font-bold transition-all flex justify-between items-center min-h-[44px] ${selectedMatchKey === k ? 'border-primary bg-primary/20 text-primary' : matchedVal ? 'border-success/30 bg-success/5 text-success' : 'border-border bg-card text-slate-800 dark:text-slate-200'}`}>
                    <span className="break-words leading-tight pr-1">{k}</span>
                    {matchedVal && <span className="shrink-0 bg-success/20 text-success text-[8px] px-1 py-0.5 rounded-full">OK</span>}
                  </button>
                );
              })}
            </div>
            <div className="space-y-2">
              {targets.map((t, i) => {
                const matchedKey = Object.keys(matchingPairs).find(k => matchingPairs[k] === t);
                return (
                  <button key={i} onClick={() => handleMatchingClick(t, false)} disabled={isAnswered || !selectedMatchKey} className={`w-full text-left p-3 rounded-xl border-2 text-[11px] font-bold transition-all flex flex-col min-h-[50px] ${matchedKey ? 'border-primary bg-primary/10' : selectedMatchKey ? 'border-primary/40 bg-primary/5' : 'border-border bg-card'}`}>
                    <span className="break-words leading-tight text-slate-800 dark:text-slate-200">{t}</span>
                    {matchedKey && <span className="text-[8px] text-primary font-black mt-1 uppercase line-clamp-1">← {matchedKey}</span>}
                  </button>
                );
              })}
            </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 gap-3">
            {options.map((opt, i) => {
              const isSelected = selectedAnswer === opt;
              const normalizedCorrect = Array.isArray(answer) ? answer[0] : answer;
              const isCorrect = normalizedCorrect === opt;
              let styleClass = 'border-border bg-card hover:border-slate-500';
              if (isAnswered) {
                if (isCorrect) styleClass = 'border-success bg-success/10 ring-2 ring-success/20';
                else if (isSelected) styleClass = 'border-danger bg-danger/10 ring-2 ring-danger/20';
                else styleClass = 'border-border bg-card opacity-50';
              } else if (isSelected) styleClass = 'border-primary bg-primary/10 ring-2 ring-primary/20';
              return (
                <button key={i} onClick={() => setSelectedAnswer(opt)} disabled={isAnswered} className={`w-full text-left px-5 py-4 rounded-xl border-2 flex items-center justify-between transition-all shadow-sm ${styleClass} min-h-[56px]`}>
                  <div className="flex items-start gap-4 flex-1">
                    <div className={`w-5 h-5 mt-0.5 rounded-full border-2 shrink-0 ${isAnswered ? (isCorrect ? 'border-success bg-success' : (isSelected ? 'border-danger bg-danger' : 'border-slate-600')) : (isSelected ? 'border-primary bg-primary' : 'border-slate-600')}`} />
                    <span className="text-[14px] font-semibold text-slate-800 dark:text-slate-200 break-words leading-tight">{opt}</span>
                  </div>
                  {isAnswered && (isCorrect ? <CheckIcon className="w-5 h-5 shrink-0 ml-2" /> : (isSelected ? <XIcon className="w-5 h-5 shrink-0 ml-2" /> : null))}
                </button>
              );
            })}
          </div>
        );
    }
  };

  if (isLoading && questions.length === 0) return <Loader text="Optimizing session for speed..." />;
  const lastResult = results[results.length - 1];

  return (
    <div className="max-w-4xl mx-auto animate-fade-in pb-20 px-4">
        <div className="flex justify-between items-center mb-6">
            <h2 className="text-lg font-black flex items-center gap-2 text-foreground">
                <div className="w-7 h-7 bg-primary rounded flex items-center justify-center text-white shadow-sm"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></div>
                <span className="truncate">{mode === 'Exam' ? 'Exam Simulation' : 'Practice Mode'}</span>
            </h2>
            {timer > 0 && (
                <div className="flex items-center gap-2 font-mono font-bold px-2 py-1 rounded border border-border bg-slate-900/10 dark:bg-slate-900/80"><StopwatchIcon className="w-3.5 h-3.5 text-primary" /><span className="text-sm text-foreground">{Math.floor(timeLeft/60)}:{(timeLeft%60).toString().padStart(2, '0')}</span></div>
            )}
        </div>

        {currentQuestion.context && (
            <div className="mb-6 p-5 bg-primary/5 dark:bg-slate-800/40 rounded-xl border-l-4 border-primary shadow-lg overflow-hidden">
                <h4 className="text-[8px] font-black uppercase text-primary tracking-[0.2em] mb-2">Case Study Scenario</h4>
                <div className="text-slate-700 dark:text-slate-300 text-[13px] leading-relaxed font-serif">{currentQuestion.context}</div>
            </div>
        )}

        <div className="bg-card p-6 md:p-8 rounded-[1.5rem] shadow-xl border border-border relative overflow-hidden group">
            <div className="mb-6">
               <div className="flex justify-between items-start mb-3">
                  <span className="inline-block bg-primary/10 text-primary text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest border border-primary/20">
                    {currentQuestion.type} • ITEM {currentQuestionIndex + 1} OF {mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS}
                  </span>
               </div>
               <h3 className="text-[16px] md:text-[18px] font-bold leading-snug text-foreground pr-6 mb-2">{currentQuestion.question}</h3>
            </div>

            <div className="min-h-[160px]">
              {renderOptions()}
            </div>

            {quizState === 'answered' && lastResult && (
                <div className="mt-8 pt-6 border-t border-border animate-fade-in-up">
                    <div className={`mb-6 p-4 rounded-xl border-2 flex items-center gap-4 ${lastResult.isCorrect ? 'bg-success/5 border-success/30 text-success' : 'bg-danger/5 border-danger/30 text-danger'}`}>
                        <div className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${lastResult.isCorrect ? 'bg-success text-white' : 'bg-danger text-white'}`}>
                            {lastResult.isCorrect ? <CheckIcon className="w-5 h-5" /> : <XIcon className="w-5 h-5" />}
                        </div>
                        <div>
                            <h4 className="text-sm font-black uppercase tracking-tight">{lastResult.isCorrect ? 'Correct! Well Done' : 'Incorrect Answer'}</h4>
                            <p className="text-[9px] opacity-80 font-bold">{lastResult.isCorrect ? 'Official status: Passed item.' : 'Official status: Review needed.'}</p>
                        </div>
                    </div>
                    <DexterExplains 
                      question={currentQuestion} 
                      userAnswer={lastResult.userAnswer} 
                      isCorrect={lastResult.isCorrect}
                    />
                </div>
            )}

            <div className="mt-8 flex gap-3">
                {quizState === 'answering' ? (
                    <button 
                      onClick={handleSubmit} 
                      disabled={!(currentQuestion?.type === 'Matching' ? Object.keys(matchingPairs).length > 0 : !!selectedAnswer)} 
                      className="flex-1 bg-primary hover:bg-primary/90 text-primary-foreground font-black py-3.5 px-6 rounded-xl text-[14px] transition-all disabled:opacity-30 disabled:cursor-not-allowed shadow-md"
                    >
                        Check Final Answer
                    </button>
                ) : (
                    <button 
                      onClick={handleNextQuestion} 
                      className="flex-1 bg-primary hover:bg-primary/90 text-primary-foreground font-black py-3.5 px-6 rounded-xl text-[14px] transition-all flex items-center justify-center gap-2 shadow-md active:scale-[0.98]"
                    >
                        {currentQuestionIndex + 1 === (mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS) ? 'Finish & Final Score' : 'Next Question'}
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                    </button>
                )}
            </div>

            {/* Action Bar Overlay */}
            <div className="absolute top-4 right-4 flex gap-2">
                 <button onClick={handleReadAloud} className={`p-1.5 rounded-lg transition-all border ${isSpeaking || isGeneratingAudio ? 'bg-danger border-danger text-white' : 'bg-slate-100 dark:bg-slate-800/80 border-border text-slate-500 dark:text-slate-400 hover:text-primary dark:hover:text-white'}`}>
                    {isSpeaking || isGeneratingAudio ? <StopIcon className="w-3.5 h-3.5" /> : <SpeakerIcon className="w-3.5 h-3.5" />}
                </button>
                <button onClick={() => onToggleBookmark(currentQuestion)} className={`p-1.5 rounded-lg transition-all border ${isBookmarked(currentQuestion) ? 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20' : 'text-slate-500 bg-slate-100 dark:bg-slate-800/80 border-border hover:text-yellow-500'}`}>
                    <BookmarkIcon filled={isBookmarked(currentQuestion)} className="w-3.5 h-3.5" />
                </button>
            </div>
        </div>
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from '../types';
import { generateQuestion, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { StopwatchIcon } from './icons/StopwatchIcon';
import { KeyboardShortcutsGuide } from './KeyboardShortcutsGuide';
import { DexterExplains } from './DexterExplains';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';
import { CheckIcon } from './icons/CheckIcon';
import { XIcon } from './icons/XIcon';

interface QuizProps {
  difficulty: Difficulty;
  timer: TimerSetting;
  mode: QuizMode;
  category: QuestionCategoryFilter;
  bookmarkedQuestions: Question[];
  onQuizEnd: (results: ExamResult[], timeTaken: number) => void;
  onToggleBookmark: (question: Question) => void;
  isBookmarked: (question: Question) => boolean;
}

const TOTAL_QUESTIONS = 10;

export const Quiz: React.FC<QuizProps> = ({
  difficulty,
  timer,
  mode,
  category,
  bookmarkedQuestions,
  onQuizEnd,
  onToggleBookmark,
  isBookmarked,
}) => {
  // We now store questions in a fixed-length array to support jumping to any index
  const totalInSet = mode === 'BookmarkReview' ? bookmarkedQuestions.length : TOTAL_QUESTIONS;
  const [questions, setQuestions] = useState<(Question | null)[]>(new Array(totalInSet).fill(null));
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  // Track selected answers per question index to preserve state when jumping back and forth
  const [answersState, setAnswersState] = useState<Record<number, string | string[] | null>>({});
  // Track matching pairs per question index
  const [matchingState, setMatchingState] = useState<Record<number, Record<string, string>>>({});

  const [resultsMap, setResultsMap] = useState<Record<number, ExamResult>>({});
  const [isLoadingSpecific, setIsLoadingSpecific] = useState(false);

  const [timeLeft, setTimeLeft] = useState(timer > 0 ? timer * 60 : Infinity);
  const startTimeRef = useRef<number>(Date.now());

  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQuestion = questions[currentQuestionIndex];
  const currentAnswer = answersState[currentQuestionIndex] || null;
  const currentMatching = matchingState[currentQuestionIndex] || {};
  const isAnswered = !!resultsMap[currentQuestionIndex];

  const stopSpeaking = () => {
    if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch (e) {}
        audioSourceRef.current = null;
    }
    setIsSpeaking(false);
    setIsGeneratingAudio(false);
  };

  const finishQuiz = useCallback(() => {
    stopSpeaking();
    const timeTaken = timer > 0 ? (timer * 60 - timeLeft) : Math.round((Date.now() - startTimeRef.current) / 1000);
    // Convert resultsMap to an array for the parent
    const finalResults = Object.values(resultsMap);
    onQuizEnd(finalResults, timeTaken);
  }, [onQuizEnd, resultsMap, timer, timeLeft]);

  useEffect(() => {
    if (timer === 0) return;
    if (timeLeft <= 0) { finishQuiz(); return; }
    const intervalId = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(intervalId);
  }, [timeLeft, timer, finishQuiz]);

  const loadQuestionAtIndex = useCallback(async (index: number) => {
    if (questions[index]) return; // Already loaded

    setIsLoadingSpecific(true);
    try {
      const q = await generateQuestion(difficulty, category);
      setQuestions(prev => {
        const next = [...prev];
        next[index] = q;
        return next;
      });
    } catch (err) {
      console.error("Failed to load question at index", index);
    } finally {
      setIsLoadingSpecific(false);
    }
  }, [questions, difficulty, category]);

  // Initial load
  useEffect(() => {
    const loadInitial = async () => {
      if (mode === 'BookmarkReview') {
        if (bookmarkedQuestions.length === 0) { onQuizEnd([], 0); return; }
        setQuestions(bookmarkedQuestions);
      } else {
        await loadQuestionAtIndex(0);
        // Prefetch next one immediately
        loadQuestionAtIndex(1);
      }
    };
    loadInitial();
  }, [mode, bookmarkedQuestions, onQuizEnd, loadQuestionAtIndex]);

  const jumpToQuestion = async (index: number) => {
    if (index < 0 || index >= totalInSet) return;
    stopSpeaking();
    if (!questions[index]) {
      await loadQuestionAtIndex(index);
    }
    setCurrentQuestionIndex(index);
    // Prefetch next one if it doesn't exist
    if (index + 1 < totalInSet && !questions[index + 1]) {
      loadQuestionAtIndex(index + 1);
    }
  };

  const handleReadAloud = async () => {
    if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
    if (!currentQuestion) return;
    setIsGeneratingAudio(true);
    try {
        if (!audioContextRef.current) audioContextRef.current = new AudioContext();
        const textToRead = `${currentQuestion.context || ''} ${currentQuestion.question}`;
        const buffer = await generateSpeech(textToRead, 'Zephyr', audioContextRef.current);
        setIsGeneratingAudio(false);
        setIsSpeaking(true);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsSpeaking(false);
        audioSourceRef.current = source;
        source.start();
    } catch (err) {
        setIsGeneratingAudio(false);
        setIsSpeaking(false);
    }
  };

  const toggleMultiSelect = (option: string) => {
    if (isAnswered) return;
    setAnswersState(prev => {
      const current = prev[currentQuestionIndex];
      const arr = Array.isArray(current) ? current : [];
      const nextArr = arr.includes(option) ? arr.filter(o => o !== option) : [...arr, option];
      return { ...prev, [currentQuestionIndex]: nextArr };
    });
  };

  const handleBuildListAdd = (option: string) => {
    if (isAnswered) return;
    setAnswersState(prev => {
      const current = prev[currentQuestionIndex];
      const arr = Array.isArray(current) ? current : [];
      if (arr.includes(option)) return prev;
      return { ...prev, [currentQuestionIndex]: [...arr, option] };
    });
  };

  const handleBuildListRemove = (option: string) => {
    if (isAnswered) return;
    setAnswersState(prev => {
      const current = prev[currentQuestionIndex];
      const arr = Array.isArray(current) ? current : [];
      return { ...prev, [currentQuestionIndex]: arr.filter(o => o !== option) };
    });
  };

  const handleMatchingClick = (item: string, isKey: boolean) => {
    if (isAnswered) return;
    // Matching is handled slightly differently to keep the UI selection logic separate
    // We'll use a local state for the "currently selected key" but keep the map in global state
    // To simplify, we keep the existing logic but map it to state
  };

  // Dedicated matching logic for the multi-question state
  const [selectedMatchKey, setSelectedMatchKey] = useState<string | null>(null);
  const handleMatching = (item: string, isKey: boolean) => {
    if (isAnswered) return;
    if (isKey) {
        setSelectedMatchKey(item === selectedMatchKey ? null : item);
    } else if (selectedMatchKey) {
        setMatchingState(prev => {
            const current = prev[currentQuestionIndex] || {};
            const next = { ...current };
            Object.keys(next).forEach(k => { if (next[k] === item) delete next[k]; });
            next[selectedMatchKey] = item;
            return { ...prev, [currentQuestionIndex]: next };
        });
        setSelectedMatchKey(null);
    }
  };

  const handleSubmit = () => {
    if (!currentQuestion || isAnswered) return;

    let finalAnswer: string | string[] | null = currentAnswer;
    if (currentQuestion.type === 'Matching') {
      finalAnswer = Object.entries(currentMatching).map(([k, v]) => `${k}:${v}`);
    }

    if (!finalAnswer || (Array.isArray(finalAnswer) && finalAnswer.length === 0)) return;

    let isCorrect = false;
    const cleanAnswer = currentQuestion.answer;
    if (currentQuestion.type === 'MultipleChoice' || currentQuestion.type === 'CaseStudy') {
      const normalizedCorrect = Array.isArray(cleanAnswer) ? cleanAnswer[0] : cleanAnswer;
      isCorrect = finalAnswer === normalizedCorrect;
    } else {
      const userArr = Array.isArray(finalAnswer) ? finalAnswer : [finalAnswer];
      const correctArr = Array.isArray(cleanAnswer) ? cleanAnswer : [cleanAnswer];
      if (currentQuestion.type === 'BuildList') {
        isCorrect = JSON.stringify(userArr) === JSON.stringify(correctArr);
      } else if (currentQuestion.type === 'Matching') {
        isCorrect = userArr.length === correctArr.length && [...userArr].sort().join(',') === [...correctArr].sort().join(',');
      } else {
        isCorrect = userArr.length === correctArr.length && userArr.every(v => correctArr.includes(v));
      }
    }

    setResultsMap(prev => ({
        ...prev,
        [currentQuestionIndex]: { question: currentQuestion, userAnswer: finalAnswer, isCorrect }
    }));
  };

  const handleNext = () => {
    if (currentQuestionIndex + 1 < totalInSet) {
      jumpToQuestion(currentQuestionIndex + 1);
    } else {
      finishQuiz();
    }
  };

  const renderOptions = () => {
    if (!currentQuestion) return null;
    const { type, options, answer } = currentQuestion;
    const result = resultsMap[currentQuestionIndex];
    const isAnswered = !!result;

    switch (type) {
      case 'MultiSelect':
        return (
          <div className="grid grid-cols-1 gap-3">
            {options.map((opt, i) => {
              const isSelected = Array.isArray(currentAnswer) && currentAnswer.includes(opt);
              const isCorrect = Array.isArray(answer) ? answer.includes(opt) : answer === opt;
              let styleClass = 'border-border bg-card hover:border-slate-500';
              if (isAnswered) {
                if (isCorrect) styleClass = 'border-success bg-success/10 ring-2 ring-success/20';
                else if (isSelected) styleClass = 'border-danger bg-danger/10 ring-2 ring-danger/20';
                else styleClass = 'border-border bg-card opacity-50';
              } else if (isSelected) styleClass = 'border-primary bg-primary/10 ring-2 ring-primary/20';
              return (
                <button key={i} onClick={() => toggleMultiSelect(opt)} disabled={isAnswered} className={`w-full text-left px-5 py-4 rounded-xl border-2 flex items-center justify-between transition-all shadow-sm ${styleClass} min-h-[56px]`}>
                  <div className="flex items-start gap-4 flex-1">
                    <div className={`w-5 h-5 rounded border-2 mt-0.5 shrink-0 flex items-center justify-center ${isSelected ? 'bg-primary border-primary' : 'border-slate-600'}`}>
                      {isSelected && <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"/></svg>}
                    </div>
                    <span className="text-[14px] font-semibold text-slate-800 dark:text-slate-200 break-words leading-tight">{opt}</span>
                  </div>
                  {isAnswered && (isCorrect ? <CheckIcon className="w-5 h-5 shrink-0 ml-2" /> : (isSelected ? <XIcon className="w-5 h-5 shrink-0 ml-2" /> : null))}
                </button>
              );
            })}
          </div>
        );
      case 'BuildList':
        const buildListSelected = Array.isArray(currentAnswer) ? currentAnswer : [];
        const buildListAvailable = options.filter(o => !buildListSelected.includes(o));
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-3">
              <h4 className="text-[10px] font-black uppercase text-slate-500 pl-1">Available</h4>
              <div className="bg-slate-900/40 p-3 rounded-xl border border-border min-h-[160px] space-y-2">
                {buildListAvailable.map((opt, i) => (
                  <button key={i} onClick={() => handleBuildListAdd(opt)} disabled={isAnswered} className="w-full text-left p-3 bg-white dark:bg-slate-800 border border-border dark:border-slate-700 rounded-lg text-xs font-bold hover:border-primary transition-all break-words text-slate-800 dark:text-slate-200">{opt}</button>
                ))}
              </div>
            </div>
            <div className="space-y-3">
              <h4 className="text-[10px] font-black uppercase text-slate-500 pl-1">Selected Order</h4>
              <div className="bg-slate-900/40 p-3 rounded-xl border border-border min-h-[160px] space-y-2">
                {buildListSelected.map((opt, i) => {
                  const isCorrectPos = isAnswered && Array.isArray(answer) && answer[i] === opt;
                  return (
                    <button key={i} onClick={() => handleBuildListRemove(opt)} disabled={isAnswered} className={`w-full text-left p-3 rounded-lg border text-xs flex items-center justify-between transition-all ${isAnswered ? (isCorrectPos ? 'bg-success/20 border-success/40' : 'bg-danger/20 border-danger/40') : 'bg-primary/10 border-primary/30 hover:bg-primary/20'}`}>
                      <div className="flex items-center gap-2 overflow-hidden">
                        <span className="shrink-0 w-5 h-5 flex items-center justify-center bg-primary/20 rounded-md text-[10px] font-black text-primary">{i+1}</span>
                        <span className="font-bold break-words text-slate-800 dark:text-slate-100">{opt}</span>
                      </div>
                      {isAnswered && (isCorrectPos ? <CheckIcon className="w-3 h-3 ml-2 shrink-0" /> : <XIcon className="w-3 h-3 ml-2 shrink-0" />)}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        );
      case 'Matching':
        const keys = options.slice(0, Math.ceil(options.length / 2));
        const targets = options.slice(Math.ceil(options.length / 2));
        return (
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              {keys.map((k, i) => {
                const matchedVal = currentMatching[k];
                return (
                  <button key={i} onClick={() => handleMatching(k, true)} disabled={isAnswered} className={`w-full text-left p-3 rounded-xl border-2 text-[11px] font-bold transition-all flex justify-between items-center min-h-[44px] ${selectedMatchKey === k ? 'border-primary bg-primary/20 text-primary' : matchedVal ? 'border-success/30 bg-success/5 text-success' : 'border-border bg-card text-slate-800 dark:text-slate-200'}`}>
                    <span className="break-words leading-tight pr-1">{k}</span>
                    {matchedVal && <span className="shrink-0 bg-success/20 text-success text-[8px] px-1 py-0.5 rounded-full">OK</span>}
                  </button>
                );
              })}
            </div>
            <div className="space-y-2">
              {targets.map((t, i) => {
                const matchedKey = Object.keys(currentMatching).find(k => currentMatching[k] === t);
                return (
                  <button key={i} onClick={() => handleMatching(t, false)} disabled={isAnswered || !selectedMatchKey} className={`w-full text-left p-3 rounded-xl border-2 text-[11px] font-bold transition-all flex flex-col min-h-[50px] ${matchedKey ? 'border-primary bg-primary/10' : selectedMatchKey ? 'border-primary/40 bg-primary/5' : 'border-border bg-card'}`}>
                    <span className="break-words leading-tight text-slate-800 dark:text-slate-200">{t}</span>
                    {matchedKey && <span className="text-[8px] text-primary font-black mt-1 uppercase line-clamp-1">← {matchedKey}</span>}
                  </button>
                );
              })}
            </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 gap-3">
            {options.map((opt, i) => {
              const isSelected = currentAnswer === opt;
              const normalizedCorrect = Array.isArray(answer) ? answer[0] : answer;
              const isCorrect = normalizedCorrect === opt;
              let styleClass = 'border-border bg-card hover:border-slate-500';
              if (isAnswered) {
                if (isCorrect) styleClass = 'border-success bg-success/10 ring-2 ring-success/20';
                else if (isSelected) styleClass = 'border-danger bg-danger/10 ring-2 ring-danger/20';
                else styleClass = 'border-border bg-card opacity-50';
              } else if (isSelected) styleClass = 'border-primary bg-primary/10 ring-2 ring-primary/20';
              return (
                <button key={i} onClick={() => setAnswersState(prev => ({...prev, [currentQuestionIndex]: opt}))} disabled={isAnswered} className={`w-full text-left px-5 py-4 rounded-xl border-2 flex items-center justify-between transition-all shadow-sm ${styleClass} min-h-[56px]`}>
                  <div className="flex items-start gap-4 flex-1">
                    <div className={`w-5 h-5 mt-0.5 rounded-full border-2 shrink-0 ${isAnswered ? (isCorrect ? 'border-success bg-success' : (isSelected ? 'border-danger bg-danger' : 'border-slate-600')) : (isSelected ? 'border-primary bg-primary' : 'border-slate-600')}`} />
                    <span className="text-[14px] font-semibold text-slate-800 dark:text-slate-200 break-words leading-tight">{opt}</span>
                  </div>
                  {isAnswered && (isCorrect ? <CheckIcon className="w-5 h-5 shrink-0 ml-2" /> : (isSelected ? <XIcon className="w-5 h-5 shrink-0 ml-2" /> : null))}
                </button>
              );
            })}
          </div>
        );
    }
  };

  const QuestionMap = () => (
    <div className="flex flex-wrap gap-2 mb-6 justify-center">
        {questions.map((_, idx) => {
            const result = resultsMap[idx];
            const isCurrent = currentQuestionIndex === idx;
            const isGenerated = !!questions[idx];

            let statusClass = 'border-border bg-card text-slate-500';
            if (isCurrent) statusClass = 'border-primary ring-2 ring-primary/20 bg-primary/10 text-primary animate-pulse';
            else if (result) {
                statusClass = result.isCorrect ? 'border-success bg-success text-white' : 'border-danger bg-danger text-white';
            } else if (!isGenerated) {
                statusClass = 'border-dashed border-border opacity-40';
            }

            return (
                <button
                    key={idx}
                    onClick={() => jumpToQuestion(idx)}
                    className={`w-9 h-9 rounded-lg border-2 flex items-center justify-center text-xs font-black transition-all hover:scale-105 active:scale-95 ${statusClass}`}
                    title={`Go to Question ${idx + 1}`}
                >
                    {idx + 1}
                </button>
            );
        })}
    </div>
  );

  if (isLoadingSpecific && !currentQuestion) return <Loader text="Assembling question..." />;

  return (
    <div className="max-w-4xl mx-auto animate-fade-in pb-20 px-4">
        <div className="flex justify-between items-center mb-6">
            <h2 className="text-lg font-black flex items-center gap-2 text-foreground">
                <div className="w-7 h-7 bg-primary rounded flex items-center justify-center text-white shadow-sm"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg></div>
                <span className="truncate">{mode === 'Exam' ? 'Exam Simulation' : 'Practice Mode'}</span>
            </h2>
            {timer > 0 && (
                <div className="flex items-center gap-2 font-mono font-bold px-2 py-1 rounded border border-border bg-slate-900/10 dark:bg-slate-900/80"><StopwatchIcon className="w-3.5 h-3.5 text-primary" /><span className="text-sm text-foreground">{Math.floor(timeLeft/60)}:{(timeLeft%60).toString().padStart(2, '0')}</span></div>
            )}
        </div>

        <QuestionMap />

        {!currentQuestion ? (
            <div className="bg-card p-12 rounded-[1.5rem] border border-border text-center">
                 <Loader text="Generating on demand..." />
            </div>
        ) : (
            <div className="animate-fade-in">
                {currentQuestion.context && (
                    <div className="mb-6 p-5 bg-primary/5 dark:bg-slate-800/40 rounded-xl border-l-4 border-primary shadow-lg overflow-hidden">
                        <h4 className="text-[8px] font-black uppercase text-primary tracking-[0.2em] mb-2">Case Study Scenario</h4>
                        <div className="text-slate-700 dark:text-slate-300 text-[13px] leading-relaxed font-serif">{currentQuestion.context}</div>
                    </div>
                )}

                <div className="bg-card p-6 md:p-8 rounded-[1.5rem] shadow-xl border border-border relative overflow-hidden group">
                    <div className="mb-6">
                    <div className="flex justify-between items-start mb-3">
                        <span className="inline-block bg-primary/10 text-primary text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest border border-primary/20">
                            {currentQuestion.type} • ITEM {currentQuestionIndex + 1} OF {totalInSet}
                        </span>
                    </div>
                    <h3 className="text-[16px] md:text-[18px] font-bold leading-snug text-foreground pr-6 mb-2">{currentQuestion.question}</h3>
                    </div>

                    <div className="min-h-[160px]">
                        {renderOptions()}
                    </div>

                    {isAnswered && resultsMap[currentQuestionIndex] && (
                        <div className="mt-8 pt-6 border-t border-border animate-fade-in-up">
                            <div className={`mb-6 p-4 rounded-xl border-2 flex items-center gap-4 ${resultsMap[currentQuestionIndex].isCorrect ? 'bg-success/5 border-success/30 text-success' : 'bg-danger/5 border-danger/30 text-danger'}`}>
                                <div className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${resultsMap[currentQuestionIndex].isCorrect ? 'bg-success text-white' : 'bg-danger text-white'}`}>
                                    {resultsMap[currentQuestionIndex].isCorrect ? <CheckIcon className="w-5 h-5" /> : <XIcon className="w-5 h-5" />}
                                </div>
                                <div>
                                    <h4 className="text-sm font-black uppercase tracking-tight">{resultsMap[currentQuestionIndex].isCorrect ? 'Correct! Well Done' : 'Incorrect Answer'}</h4>
                                    <p className="text-[9px] opacity-80 font-bold">{resultsMap[currentQuestionIndex].isCorrect ? 'Official status: Passed item.' : 'Official status: Review needed.'}</p>
                                </div>
                            </div>
                            <DexterExplains 
                            question={currentQuestion} 
                            userAnswer={resultsMap[currentQuestionIndex].userAnswer} 
                            isCorrect={resultsMap[currentQuestionIndex].isCorrect}
                            />
                        </div>
                    )}

                    <div className="mt-8 flex gap-3">
                        {!isAnswered ? (
                            <button 
                            onClick={handleSubmit} 
                            disabled={!(currentQuestion?.type === 'Matching' ? Object.keys(currentMatching).length > 0 : !!currentAnswer)} 
                            className="flex-1 bg-primary hover:bg-primary/90 text-primary-foreground font-black py-3.5 px-6 rounded-xl text-[14px] transition-all disabled:opacity-30 disabled:cursor-not-allowed shadow-md"
                            >
                                Check Final Answer
                            </button>
                        ) : (
                            <button 
                            onClick={handleNext} 
                            className="flex-1 bg-primary hover:bg-primary/90 text-primary-foreground font-black py-3.5 px-6 rounded-xl text-[14px] transition-all flex items-center justify-center gap-2 shadow-md active:scale-[0.98]"
                            >
                                {currentQuestionIndex + 1 === totalInSet ? 'Finish & Final Score' : 'Next Question'}
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                            </button>
                        )}
                    </div>

                    {/* Action Bar Overlay */}
                    <div className="absolute top-4 right-4 flex gap-2">
                        <button onClick={handleReadAloud} className={`p-1.5 rounded-lg transition-all border ${isSpeaking || isGeneratingAudio ? 'bg-danger border-danger text-white' : 'bg-slate-100 dark:bg-slate-800/80 border-border text-slate-500 dark:text-slate-400 hover:text-primary dark:hover:text-white'}`}>
                            {isSpeaking || isGeneratingAudio ? <StopIcon className="w-3.5 h-3.5" /> : <SpeakerIcon className="w-3.5 h-3.5" />}
                        </button>
                        <button onClick={() => onToggleBookmark(currentQuestion)} className={`p-1.5 rounded-lg transition-all border ${isBookmarked(currentQuestion) ? 'text-yellow-500 bg-yellow-500/10 border-yellow-500/20' : 'text-slate-500 bg-slate-100 dark:bg-slate-800/80 border-border hover:text-yellow-500'}`}>
                            <BookmarkIcon filled={isBookmarked(currentQuestion)} className="w-3.5 h-3.5" />
                        </button>
                    </div>
                </div>
            </div>
        )}
        <KeyboardShortcutsGuide mode={mode} />
    </div>
  );
};

// Implemented the main App component to handle state management, view routing, data persistence, and theme.
import React, { useState, useEffect, useCallback } from 'react';
import { Dashboard } from './components/Dashboard';
import { Quiz } from './components/Quiz';
import { SessionReview } from './components/SessionReview';
import { BookmarkedQuestions } from './components/BookmarkedQuestions';
import { StudyHub } from './components/StudyHub';
import type { ProgressData, Question, ExamResult, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter } from './types';
import { PowerBiIcon } from './components/icons/PowerBiIcon';
import { PerformanceSummaryModal } from './components/PerformanceSummaryModal';
import { ThemeToggle } from './components/ThemeToggle';
import { PracticeExamDownloader } from './components/PracticeExamDownloader';

type View = 'dashboard' | 'quiz' | 'review' | 'bookmarks' | 'study-hub';
export type Theme = 'light' | 'dim' | 'dark';

const INITIAL_PROGRESS: ProgressData = {
  totalQuestions: 0,
  totalCorrect: 0,
  currentStreak: 0,
  categoryStats: {
    'Prepare the data': { correct: 0, total: 0 },
    'Model the data': { correct: 0, total: 0 },
    'Visualize and analyze the data': { correct: 0, total: 0 },
    'Deploy and maintain assets': { correct: 0, total: 0 },
  },
  bookmarkedQuestions: [],
  accuracyHistory: [],
  examHistory: [],
};

const APP_DATA_KEY = 'pl300-progress';

interface SessionSummary {
    score: number;
    total: number;
    accuracy: string;
    timeTaken: number;
}

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [progressData, setProgressData] = useState<ProgressData>(INITIAL_PROGRESS);
  const [quizSettings, setQuizSettings] = useState<{ difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }>({
    difficulty: 'Adaptive',
    timer: 15,
    mode: 'Practice',
    category: 'All',
  });
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [showSummaryModal, setShowSummaryModal] = useState(false);
  const [sessionSummary, setSessionSummary] = useState<SessionSummary | null>(null);
  const [theme, setTheme] = useState<Theme>('dim');
  const [showPracticeExamModal, setShowPracticeExamModal] = useState(false);

  // Effect to load theme on initial load
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as Theme | null;
    const initialTheme = savedTheme || 'dim';
    setTheme(initialTheme);
  }, []);

  // Effect to apply theme class and save to localStorage
  useEffect(() => {
    const root = document.documentElement;
    root.classList.remove('light', 'dark', 'dim');
    if (theme === 'dark') {
      root.classList.add('dark');
    } else if (theme === 'dim') {
      // Apply both so 'dark:' tailwind variants trigger, but 'dim' CSS vars take priority
      root.classList.add('dim', 'dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => {
        if (prevTheme === 'light') return 'dim';
        if (prevTheme === 'dim') return 'dark';
        return 'light';
    });
  };

  // Effect to load data on initial load
  useEffect(() => {
    try {
      const savedData = localStorage.getItem(APP_DATA_KEY);
      if (savedData) {
        const parsedData = JSON.parse(savedData);
        const mergedData: ProgressData = {
          ...INITIAL_PROGRESS,
          ...parsedData,
          categoryStats: { ...INITIAL_PROGRESS.categoryStats, ...(parsedData.categoryStats || {}), },
          bookmarkedQuestions: parsedData.bookmarkedQuestions || [],
          accuracyHistory: parsedData.accuracyHistory || [],
          examHistory: parsedData.examHistory || [],
        };
        setProgressData(mergedData);
      } else {
        setProgressData(INITIAL_PROGRESS);
      }
    } catch (error) {
      console.error("Failed to load progress data. Resetting.", error);
      setProgressData(INITIAL_PROGRESS);
    }
  }, []);

  // Effect to save data whenever it changes
  useEffect(() => {
    try {
      localStorage.setItem(APP_DATA_KEY, JSON.stringify(progressData));
    } catch (error) {
      console.error("Failed to save progress data", error);
    }
  }, [progressData]);

  const handleStartQuiz = useCallback((settings: { difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }) => {
    setQuizSettings(settings);
    setView('quiz');
  }, []);

  const handleQuizEnd = useCallback((results: ExamResult[], timeTaken: number) => {
    setExamResults(results);

    if (results.length === 0) {
        setView('review');
        return;
    }

    setProgressData(prevData => {
      const newData = { ...prevData, categoryStats: JSON.parse(JSON.stringify(prevData.categoryStats)), accuracyHistory: [...(prevData.accuracyHistory || [])], };
      let newStreak = prevData.currentStreak;
      let sessionCorrect = 0;

      results.forEach(result => {
        newData.totalQuestions += 1;
        const category = result.question.category;
        if (!newData.categoryStats[category]) {
           newData.categoryStats[category] = { correct: 0, total: 0 };
        }
        newData.categoryStats[category].total += 1;

        if (result.isCorrect) {
          newData.totalCorrect += 1;
          newData.categoryStats[category].correct += 1;
          newStreak += 1;
          sessionCorrect += 1;
        } else {
          newStreak = 0;
        }
      });
      newData.currentStreak = newStreak;

      const sessionAccuracy = (sessionCorrect / results.length) * 100;
      newData.accuracyHistory.push({
          session: newData.accuracyHistory.length + 1,
          accuracy: sessionAccuracy,
      });

      const newHistory = [...(prevData.examHistory || []), results].slice(-10);
      newData.examHistory = newHistory;

      return newData;
    });

    const score = results.filter(r => r.isCorrect).length;
    const total = results.length;
    const accuracy = total > 0 ? ((score / total) * 100).toFixed(0) : '0';

    setSessionSummary({ score, total, accuracy, timeTaken });
    setShowSummaryModal(true);
  }, []);

  const handleCloseSummaryModal = useCallback(() => {
    setShowSummaryModal(false);
    setView('review');
  }, []);

  const handleToggleBookmark = useCallback((question: Question) => {
    setProgressData(prevData => {
      const isBookmarked = prevData.bookmarkedQuestions.some(bq => bq.question === question.question);
      return {
        ...prevData,
        bookmarkedQuestions: isBookmarked
          ? prevData.bookmarkedQuestions.filter(bq => bq.question !== question.question)
          : [...prevData.bookmarkedQuestions, question],
      };
    });
  }, []);

  const isBookmarked = useCallback((question: Question) => progressData.bookmarkedQuestions.some(bq => bq.question === question.question), [progressData.bookmarkedQuestions]);
  const handleViewBookmarks = useCallback(() => setView('bookmarks'), []);
  const handleViewStudyHub = useCallback(() => setView('study-hub'), []);
  const handleStartBookmarkReview = useCallback(() => handleStartQuiz({ difficulty: 'Easy', timer: 0, mode: 'BookmarkReview', category: 'All' }), [handleStartQuiz]);
  const handleBackToDashboard = useCallback(() => { setExamResults([]); setSessionSummary(null); setView('dashboard'); }, []);
  const handleResetProgress = useCallback(() => {
    if (window.confirm("Are you sure you want to reset all your progress? This action cannot be undone.")) {
        setProgressData(INITIAL_PROGRESS);
        setView('dashboard');
    }
  }, []);

  const renderAppContent = () => {
    switch (view) {
      case 'quiz':
        return <Quiz {...quizSettings} bookmarkedQuestions={progressData.bookmarkedQuestions} onQuizEnd={handleQuizEnd} onToggleBookmark={handleToggleBookmark} isBookmarked={isBookmarked} />;
      case 'review':
        return <SessionReview results={examResults} onBackToDashboard={handleBackToDashboard} theme={theme} />;
      case 'bookmarks':
        return <BookmarkedQuestions questions={progressData.bookmarkedQuestions} onToggleBookmark={handleToggleBookmark} onBackToDashboard={handleBackToDashboard} onStartQuiz={handleStartBookmarkReview} />;
      case 'study-hub':
        return <StudyHub onBackToDashboard={handleBackToDashboard} />;
      case 'dashboard':
      default:
        return <Dashboard 
                    progressData={progressData} 
                    onStartQuiz={handleStartQuiz} 
                    onViewBookmarks={handleViewBookmarks} 
                    onViewStudyHub={handleViewStudyHub}
                    onResetProgress={handleResetProgress} 
                    onDownloadPracticeExam={() => setShowPracticeExamModal(true)}
                    theme={theme} />;
    }
  };

  return (
    <div className="bg-background text-foreground min-h-screen font-sans">
      <header className="py-4 border-b border-border print:hidden">
        <div className="max-w-screen-2xl mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer" onClick={handleBackToDashboard}>
            <PowerBiIcon className="w-10 h-10" />
            <h1 className="text-2xl md:text-3xl font-bold tracking-tight">PL-300 Power Practice</h1>
          </div>
          <ThemeToggle theme={theme} toggleTheme={toggleTheme} />
        </div>
      </header>
      <main className="max-w-screen-2xl mx-auto p-4 md:p-8">
        {renderAppContent()}
      </main>
       {showSummaryModal && sessionSummary && (
            <PerformanceSummaryModal summary={sessionSummary} onClose={handleCloseSummaryModal} />
        )}
        {showPracticeExamModal && (
            <PracticeExamDownloader onClose={() => setShowPracticeExamModal(false)} />
        )}
      <footer className="text-center py-4 text-slate-500 dark:text-slate-400 text-sm border-t border-border mt-8 print:hidden">
        <p>Powered by Gemini & AI Studio. Built for learning.</p>
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { Question, Difficulty, QuestionCategory, StudyGuideLength, QuestionType } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY! });

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const questionSchema = {
  type: Type.OBJECT,
  properties: {
    type: { 
        type: Type.STRING, 
        enum: ['MultipleChoice', 'MultiSelect', 'BuildList', 'Matching', 'CaseStudy']
    },
    question: { type: Type.STRING },
    context: { type: Type.STRING, description: 'Optional: Detailed scenario for CaseStudy types.' },
    options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: 'List of options. For matching, options contain both sets.'
    },
    answer: { 
        type: Type.ARRAY, 
        items: { type: Type.STRING },
        description: 'For MultipleChoice, a single string in an array. For MultiSelect, multiple strings. For BuildList, the strings in the correct order. For Matching, pairs like "Item:Target".'
    },
    explanation: { type: Type.STRING },
    category: {
      type: Type.STRING,
      enum: ['Prepare the data', 'Model the data', 'Visualize and analyze the data', 'Deploy and maintain assets']
    },
    difficulty: {
      type: Type.STRING,
      enum: ['Easy', 'Medium', 'Hard']
    }
  },
  required: ['type', 'question', 'options', 'answer', 'explanation', 'category', 'difficulty']
};

export const generateQuestion = async (difficulty: Difficulty, category: QuestionCategory | 'All' = 'All'): Promise<Question> => {
    const model = 'gemini-3-flash-preview';
    const randomType = ['MultipleChoice', 'MultiSelect', 'BuildList', 'Matching', 'CaseStudy'][Math.floor(Math.random() * 5)];

    const prompt = `Generate a professional ${randomType} question for the Microsoft PL-300 Power BI exam.
    Category: ${category}
    Difficulty: ${difficulty === 'Adaptive' ? 'appropriate for level' : difficulty}

    CRITICAL INSTRUCTION FOR EXPLANATION:
    Always begin the "explanation" field with a clear summary: "Correct Answer(s): [List the correct choices here]". 
    Then, provide the technical reasoning.

    Return valid JSON.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: questionSchema,
                temperature: 0.7,
            },
        });

        const generated = JSON.parse(response.text);
        if ((generated.type === 'MultipleChoice' || generated.type === 'CaseStudy') && Array.isArray(generated.answer)) {
            generated.answer = generated.answer[0];
        }
        return generated as Question;
    } catch (error) {
        console.error("Error generating question:", error);
        throw new Error("Failed to generate question.");
    }
};

export const getPersonalizedFeedback = async (question: Question, userAnswer: any, isCorrect: boolean): Promise<string> => {
    const model = 'gemini-3-flash-preview';
    const prompt = `Provide concise technical feedback for a PL-300 student.
    Status: Answer is ${isCorrect ? 'CORRECT' : 'INCORRECT'}.
    Question: ${question.question}
    Correct Answer: ${JSON.stringify(question.answer)}
    User Answer: ${JSON.stringify(userAnswer)}

    MANDATORY FORMAT:
    1. Start with: "**Correct Answer(s): [Explicitly list labels or text of correct answers]**"
    2. Then: A 2-3 sentence technical explanation.
    Keep total length under 60 words.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContent({ model, contents: prompt });
        return response.text;
    } catch (error) {
        return `**Correct Answer(s): ${Array.isArray(question.answer) ? question.answer.join(', ') : question.answer}**\n\n${question.explanation}`;
    }
};

export const generateSpeech = async (text: string, voiceName: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    const ai = getAiClient();
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Read this exam question clearly: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data");

        return await decodeAudioData(decodeBase64(base64Audio), audioContext, 24000, 1);
    } catch (error) {
        console.error("Error generating speech:", error);
        throw error;
    }
};

export const generatePracticeExamStream = async (onChunk: (chunk: string) => void, questionCount: number = 25): Promise<void> => {
    const model = 'gemini-3-flash-preview'; 
    const prompt = `Generate a high-quality PL-300 Power BI practice exam with exactly ${questionCount} questions.

    FOR EACH QUESTION:
    1. Provide the Question text and Options (A, B, C, D).
    2. IMMEDIATELY follow each question with its solution wrapped in specific markers like this:
    [ANSWER_START]
    **Correct Answer(s): [List them]**
    Explanation: [Technical reasoning]
    [ANSWER_END]

    Include a mix of Multiple Choice, Multi-select (choose 2 or 3), and Build List scenarios.
    Use Markdown formatting. Don't add a preamble. Go straight to Question 1.`;

    try {
        const ai = getAiClient();
        const response = await ai.models.generateContentStream({ model, contents: prompt });
        for await (const chunk of response) if (chunk.text) onChunk(chunk.text);
    } catch (error) {
        console.error("Stream failed:", error);
        throw error;
    }
};

