import React, { useState, useMemo } from 'react';
import type { ProgressData, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter, ExamResult, Question } from '../types';
import { ProgressChart } from './ProgressChart';
import { StudyGuide } from './StudyGuide';
import { TrashIcon } from './icons/TrashIcon';
import { BookmarkIcon } from './icons/BookmarkIcon';
import { FlameIcon } from './icons/FlameIcon';
import { PencilIcon } from './icons/PencilIcon';
import { TargetIcon } from './icons/TargetIcon';
import { calculateReadinessScore } from '../utils/readinessScore';
import { ExamReadinessGauge } from './ExamReadinessGauge';
import { InfoIcon } from './icons/InfoIcon';
import { DocumentDownloadIcon } from './icons/DocumentDownloadIcon';
import { SearchIcon } from './icons/SearchIcon';
import { QuestionDetail } from './QuestionDetail';
import { SparklesIcon } from './icons/SparklesIcon';
import { ExamCalendar } from './ExamCalendar';
import { LayoutGrid, TrendingUp, BookOpen, Settings } from 'lucide-react';

interface DashboardProps {
    progressData: ProgressData;
    onStartQuiz: (settings: { difficulty: Difficulty; timer: TimerSetting; mode: QuizMode; category: QuestionCategoryFilter; }) => void;
    onViewBookmarks: () => void;
    onViewStudyHub: () => void;
    onResetProgress: () => void;
    onDownloadPracticeExam: () => void;
    theme: 'light' | 'dim' | 'dark';
}

interface SearchableItem {
    question: Question;
    isBookmarked: boolean;
    history: ExamResult[];
}

type TabType = 'practice' | 'analytics';

export const Dashboard: React.FC<DashboardProps> = ({ progressData, onStartQuiz, onViewBookmarks, onViewStudyHub, onResetProgress, onDownloadPracticeExam, theme }) => {
    const [activeTab, setActiveTab] = useState<TabType>('practice');
    const [difficulty, setDifficulty] = useState<Difficulty>('Adaptive');
    const [timer, setTimer] = useState<TimerSetting>(15);
    const [category, setCategory] = useState<QuestionCategoryFilter>('All');
    const [searchQuery, setSearchQuery] = useState('');
    const [activeSearchIndex, setActiveSearchIndex] = useState<string | null>(null);

    const overallAccuracy = progressData.totalQuestions > 0 ? ((progressData.totalCorrect / progressData.totalQuestions) * 100).toFixed(1) + '%' : 'N/A';
    const readinessScore = calculateReadinessScore(progressData);

    const searchableData: SearchableItem[] = useMemo(() => {
        const questionMap = new Map<string, SearchableItem>();

        const addOrGetQuestion = (q: Question) => {
            if (!questionMap.has(q.question)) {
                questionMap.set(q.question, {
                    question: q,
                    isBookmarked: false,
                    history: []
                });
            }
            return questionMap.get(q.question)!;
        };

        progressData.bookmarkedQuestions.forEach(q => {
            const item = addOrGetQuestion(q);
            item.isBookmarked = true;
        });

        (progressData.examHistory || []).flat().forEach(result => {
            const item = addOrGetQuestion(result.question);
            if (!item.history.some(h => h.userAnswer === result.userAnswer && h.question.question === result.question.question)) {
                item.history.push(result);
            }
        });

        return Array.from(questionMap.values());
    }, [progressData.bookmarkedQuestions, progressData.examHistory]);

    const filteredResults = useMemo(() => {
        const trimmedQuery = searchQuery.trim();
        if (trimmedQuery.length < 3) return [];
        const lowerCaseQuery = trimmedQuery.toLowerCase();
        return searchableData.filter(item => 
            item.question.question.toLowerCase().includes(lowerCaseQuery) ||
            item.question.options.some(opt => opt.toLowerCase().includes(lowerCaseQuery))
        );
    }, [searchQuery, searchableData]);


    const getStreakStyles = (streak: number) => {
        if (streak >= 10) return { color: 'text-red-500', animation: 'animate-pulse' };
        if (streak >= 5) return { color: 'text-orange-400', animation: '' };
        if (streak > 0) return { color: 'text-yellow-400', animation: '' };
        return { color: 'text-slate-500 dark:text-slate-400', animation: '' };
    };
    const streakStyles = getStreakStyles(progressData.currentStreak);

    const handleStartPractice = () => {
        onStartQuiz({ difficulty, timer, mode: 'Practice', category });
    };

    const handleStartExam = () => {
        onStartQuiz({ difficulty: 'Hard', timer: 10, mode: 'Exam', category: 'All' });
    };

    const handleResetPracticeSettings = () => {
        setDifficulty('Adaptive');
        setTimer(15);
        setCategory('All');
    };

    const renderSearchResults = () => (
        <div className="bg-card p-6 rounded-lg shadow-lg space-y-4 border border-border animate-fade-in">
            <h3 className="text-2xl font-bold mb-4">
                Search Results ({filteredResults.length} found)
            </h3>
            {filteredResults.length > 0 ? (
                <div className="space-y-2">
                    {filteredResults.map((item) => (
                        <div key={item.question.question}>
                            <button
                                onClick={() => setActiveSearchIndex(activeSearchIndex === item.question.question ? null : item.question.question)}
                                className="w-full bg-card hover:bg-border border border-border p-4 rounded-lg text-left flex justify-between items-center transition-all"
                            >
                                <span className="flex-1 truncate pr-4 text-slate-700 dark:text-slate-300">
                                    {item.question.question}
                                </span>
                                {item.isBookmarked && (
                                    <BookmarkIcon filled={true} className="text-yellow-400 flex-shrink-0" />
                                )}
                            </button>
                            {activeSearchIndex === item.question.question && (
                                <QuestionDetail question={item.question} />
                            )}
                        </div>
                    ))}
                </div>
            ) : (
                <p className="text-center text-slate-500 dark:text-slate-400 py-8">
                    No questions found matching your search.
                </p>
            )}
        </div>
    );

    return (
        <div className="max-w-6xl mx-auto space-y-8 animate-fade-in">

            {/* Global Search Bar */}
            <div className="relative max-w-2xl mx-auto">
                <input
                    type="search"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search your question history (3+ chars)..."
                    className="w-full bg-card border border-border rounded-xl py-3.5 pl-11 pr-4 text-foreground focus:ring-2 focus:ring-primary focus:outline-none shadow-sm transition-all"
                />
                <div className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none">
                    <SearchIcon className="w-5 h-5 text-slate-500" />
                </div>
            </div>

            {searchQuery.trim().length >= 3 ? (
                renderSearchResults()
            ) : (
                <>
                    {/* Tab Navigation */}
                    <div className="flex justify-center">
                        <div className="p-1 bg-card border border-border rounded-2xl flex gap-1 shadow-md">
                            <button
                                onClick={() => setActiveTab('practice')}
                                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold transition-all ${activeTab === 'practice' ? 'bg-primary text-primary-foreground shadow-lg' : 'text-slate-500 hover:bg-border'}`}
                            >
                                <LayoutGrid className="w-5 h-5" />
                                Train
                            </button>
                            <button
                                onClick={() => setActiveTab('analytics')}
                                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold transition-all ${activeTab === 'analytics' ? 'bg-primary text-primary-foreground shadow-lg' : 'text-slate-500 hover:bg-border'}`}
                            >
                                <TrendingUp className="w-5 h-5" />
                                Analytics & Resources
                            </button>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
                        {activeTab === 'practice' ? (
                            <>
                                {/* Left Side: Quiz Settings */}
                                <div className="lg:col-span-7 space-y-8">
                                    <div className="bg-card p-8 rounded-3xl shadow-xl border border-border space-y-6">
                                        <div className="flex justify-between items-center">
                                            <h3 className="text-2xl font-black tracking-tight flex items-center gap-2"><Settings className="w-6 h-6 text-primary" /> Practice Session</h3>
                                            <button onClick={handleResetPracticeSettings} className="text-xs font-bold text-slate-500 hover:text-primary transition-colors">Reset</button>
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-slate-500 uppercase flex items-center gap-1.5">Difficulty <InfoIcon className="w-3 h-3" /></label>
                                                <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="w-full bg-input border border-border rounded-xl p-3 font-semibold">
                                                    <option value="Adaptive">Adaptive (Recommended)</option>
                                                    <option value="Easy">Easy</option>
                                                    <option value="Medium">Medium</option>
                                                    <option value="Hard">Hard</option>
                                                </select>
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-slate-500 uppercase">Category</label>
                                                <select value={category} onChange={(e) => setCategory(e.target.value as QuestionCategoryFilter)} className="w-full bg-input border border-border rounded-xl p-3 font-semibold">
                                                    <option value="All">All Categories</option>
                                                    <option value="Prepare the data">Prepare the data</option>
                                                    <option value="Model the data">Model the data</option>
                                                    <option value="Visualize and analyze the data">Visualize and analyze the data</option>
                                                    <option value="Deploy and maintain assets">Deploy and maintain assets</option>
                                                </select>
                                            </div>
                                        </div>

                                        <div className="space-y-2">
                                            <label className="text-sm font-bold text-slate-500 uppercase">Timer (minutes)</label>
                                            <select value={timer} onChange={(e) => setTimer(Number(e.target.value) as TimerSetting)} className="w-full bg-input border border-border rounded-xl p-3 font-semibold">
                                                <option value={15}>15</option>
                                                <option value={10}>10</option>
                                                <option value={5}>5</option>
                                                <option value={0}>No Limit</option>
                                            </select>
                                        </div>

                                        <button onClick={handleStartPractice} className="w-full bg-primary hover:bg-primary/90 text-primary-foreground font-black py-4 px-6 rounded-2xl text-xl shadow-lg shadow-primary/20 transition-all active:scale-95">
                                            Start Practice
                                        </button>
                                    </div>

                                    <div className="bg-card p-8 rounded-3xl shadow-xl border border-border overflow-hidden relative group">
                                        <div className="relative z-10 flex flex-col md:flex-row gap-6 items-center">
                                            <div className="flex-1 space-y-2">
                                                <h4 className="text-2xl font-black flex items-center gap-2"><FlameIcon className="w-6 h-6 text-red-500" /> Exam Simulation</h4>
                                                <p className="text-sm text-slate-500 font-medium">10 high-difficulty questions, 10 minutes. Evaluate your actual level before exam day.</p>
                                            </div>
                                            <button onClick={handleStartExam} className="w-full md:w-auto bg-danger hover:bg-red-700 text-white font-black py-4 px-10 rounded-2xl text-lg shadow-lg shadow-danger/20 transition-all">
                                                Start Exam
                                            </button>
                                        </div>
                                    </div>
                                </div>

                                {/* Right Side: Schedule and Quick Links */}
                                <div className="lg:col-span-5 space-y-6">
                                    <ExamCalendar />

                                    <div className="grid grid-cols-1 gap-4">
                                        <button onClick={onViewBookmarks} className="w-full bg-card hover:bg-border border border-border p-5 rounded-2xl flex items-center justify-between font-bold shadow-sm transition-all group">
                                            <div className="flex items-center gap-3">
                                                <BookmarkIcon filled={true} className="text-yellow-400" />
                                                <span>Bookmarks ({progressData.bookmarkedQuestions.length})</span>
                                            </div>
                                            <svg className="w-5 h-5 text-slate-400 group-hover:text-primary transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                                        </button>
                                        <button onClick={onDownloadPracticeExam} className="w-full bg-card hover:bg-border border border-border p-5 rounded-2xl flex items-center justify-between font-bold shadow-sm transition-all group">
                                            <div className="flex items-center gap-3">
                                                <DocumentDownloadIcon className="text-primary" />
                                                <span>Download PDF Exam</span>
                                            </div>
                                            <svg className="w-5 h-5 text-slate-400 group-hover:text-primary transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                                        </button>
                                    </div>

                                    <div className="bg-card p-6 rounded-2xl border border-border">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <FlameIcon className={`w-7 h-7 ${streakStyles.color}`} />
                                                <span className="font-bold text-slate-500">Current Streak</span>
                                            </div>
                                            <span className={`text-3xl font-black ${streakStyles.color}`}>{progressData.currentStreak}</span>
                                        </div>
                                    </div>
                                </div>
                            </>
                        ) : (
                            <>
                                {/* Performance Hub */}
                                <div className="lg:col-span-8 space-y-8">
                                    <div className="bg-card p-8 rounded-3xl border border-border shadow-lg">
                                        <h3 className="text-xl font-black mb-6 flex items-center gap-2"><TrendingUp className="w-6 h-6 text-primary" /> Your Evolution</h3>
