        return response.text;
    } catch (error) {
        return `**Correct Answer(s): ${Array.isArray(question.answer) ? question.answer.join(', ') : question.answer}**\n\n${question.explanation}`;
    }
};

export const generateSpeech = async (text: string, voiceName: string = 'Puck', audioContext: AudioContext): Promise<AudioBuffer> => {
    const ai = getAiClient();
    try {
        // Voice names for TTS: 'Puck', 'Charon', 'Kore', 'Fenrir'. 
        // 'Zephyr' is primarily for Live API. We use 'Puck' as a safe default.
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: `Read this exam material clearly: ${text}` }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) throw new Error("No audio data returned from Gemini");

        return await decodeAudioData(decodeBase64(base64Audio), audioContext, 24000, 1);
    } catch (error) {
        console.error("Error in generateSpeech:", error);
        throw error;
    }
};

