import React, { useState, useMemo, useRef } from 'react';
import { generatePracticeExamStream, generateSpeech } from '../services/geminiService';
import { Loader } from './Loader';
import { SparklesIcon } from './icons/SparklesIcon';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';

interface StudyHubProps {
    onBackToDashboard: () => void;
}

type QuestionCount = 25 | 50 | 100;
type FontSize = 'sm' | 'base' | 'lg' | 'xl';

export const StudyHub: React.FC<StudyHubProps> = ({ onBackToDashboard }) => {
    const [isGenerating, setIsGenerating] = useState(false);
    const [content, setContent] = useState('');
    const [title, setTitle] = useState('');
    const [selectedCount, setSelectedCount] = useState<QuestionCount>(25);
    const [includeAnswers, setIncludeAnswers] = useState(true);
    const [fontSize, setFontSize] = useState<FontSize>('base');
    const contentRef = useRef<HTMLDivElement>(null);

    // Voice related state
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    const generateQuickSet = async () => {
        stopSpeaking();
        setIsGenerating(true);
        setContent('');
        setTitle(`PL-300 Integrated Practice Exam`);
        try {
            await generatePracticeExamStream((chunk) => {
                setContent(prev => prev + chunk);
            }, selectedCount);
        } catch (err) {
            console.error("StudyHub Generation Error:", err);
            setContent("## Error during generation\n\nThe AI model encountered a temporary issue generating such a large set. \n\n**Suggestions:**\n- Try a smaller question count (25).\n- Check your internet connection.\n- Click 'Generate' again.");
        } finally {
            setIsGenerating(false);
        }
    };

    const stopSpeaking = () => {
        if (audioSourceRef.current) {
            try { audioSourceRef.current.stop(); } catch (e) {}
            audioSourceRef.current = null;
        }
        setIsSpeaking(false);
        setIsGeneratingAudio(false);
    };

    const handleReadAloud = async () => {
        if (isSpeaking || isGeneratingAudio) {
            stopSpeaking();
            return;
        }

        if (!content) return;

        // Trigger API key selection if needed for preview models
        if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
            await window.aistudio.openSelectKey();
        }

        setIsGeneratingAudio(true);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }

            // TTS models have character limits per request. Using 2000 for safety.
            const cleanText = content.substring(0, 2000).replace(/\[ANSWER_(START|END)\]/g, '');
            const buffer = await generateSpeech(cleanText, 'Puck', audioContextRef.current);
            setIsGeneratingAudio(false);

            if (!audioContextRef.current) return;
            setIsSpeaking(true);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => setIsSpeaking(false);
            audioSourceRef.current = source;
            source.start();
        } catch (err) {
            console.error("Speech generation failed", err);
            setIsGeneratingAudio(false);
            setIsSpeaking(false);
            alert("Audio generation failed. Please try a shorter selection or ensure a valid API key is selected.");
        }
    };

    const handlePrint = () => {
        if (!content) return;
        window.print();
    };

    const getFontSizeClass = () => {
        switch (fontSize) {
            case 'sm': return 'text-sm';
            case 'lg': return 'text-lg';
            case 'xl': return 'text-xl';
            default: return 'text-base';
        }
    };

    // Robustly handle interspersed content
    const processedContent = useMemo(() => {
        if (includeAnswers) {
            return content.replace(/\[ANSWER_(START|END)\]/g, '');
        }
        // In preview mode (not printing), we just hide the text between markers
        return content.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answer hidden for testing)*\n');
    }, [content, includeAnswers]);

    const printableContent = useMemo(() => {
        let text = content;
        if (!includeAnswers) {
            text = text.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answers omitted for this copy)*\n');
        } else {
            // Convert markers to HTML blocks for specialized print styling
            text = text.replace(/\[ANSWER_START\]/g, '\n<div class="answer-block">')
                       .replace(/\[ANSWER_END\]/g, '</div>\n');
        }
        return text;
    }, [content, includeAnswers]);

    return (
        <div className="space-y-8 animate-fade-in max-w-5xl mx-auto pb-20">
            {/* Control Panel - Hidden during print */}
            <div className="bg-card p-6 rounded-2xl shadow-xl border border-border flex flex-col gap-6 print:hidden">
                <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                    <div className="flex items-center gap-4">
                        <button 
                            onClick={onBackToDashboard}
                            className="p-2.5 hover:bg-border rounded-xl transition-all border border-transparent hover:border-border"
                            title="Back to Dashboard"
                        >
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                        </button>
                        <div>
                            <h2 className="text-2xl font-bold tracking-tight">Study Hub</h2>
                            <p className="text-sm text-slate-400">Integrated Q&A for focused learning</p>
                        </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-4">
                        {content && !isGenerating && (
                            <button
                                onClick={handleReadAloud}
                                className={`flex items-center gap-2 font-bold py-3 px-6 rounded-xl shadow-lg transition-all ${
                                    isSpeaking || isGeneratingAudio ? 'bg-danger text-white scale-105' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
                                }`}
                            >
                                {isSpeaking || isGeneratingAudio ? <StopIcon className="w-5 h-5" /> : <SpeakerIcon className="w-5 h-5" />}
                                {isGeneratingAudio ? 'Synthesizing...' : isSpeaking ? 'Stop Reading' : 'Listen'}
                            </button>
                        )}
                        <button
                            onClick={generateQuickSet}
                            disabled={isGenerating}
                            className="bg-primary hover:bg-primary/90 text-white font-bold py-3 px-8 rounded-xl shadow-lg shadow-primary/20 flex items-center gap-2 transition-all disabled:opacity-50 hover:-translate-y-0.5"
                        >
                            <SparklesIcon className="w-5 h-5" />
                            {isGenerating ? 'Generating...' : content ? 'Re-Generate' : 'Generate Exam Set'}
                        </button>

                        {content && !isGenerating && (
                            <button
                                onClick={handlePrint}
                                className="bg-success hover:bg-success/90 text-white font-extrabold py-3 px-8 rounded-xl flex items-center gap-2 transition-all hover:-translate-y-0.5 shadow-lg shadow-success/20"
                            >
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                                Print / Save PDF
                            </button>
                        )}
                    </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-6 border-t border-border/50">
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Total Questions</label>
                        <select 
                            value={selectedCount}
                            onChange={(e) => setSelectedCount(Number(e.target.value) as QuestionCount)}
                            className="w-full bg-background border border-border rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-primary focus:outline-none transition-all"
                            disabled={isGenerating}
                        >
                            <option value={25}>25 Questions</option>
                            <option value={50}>50 Questions</option>
                        </select>
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Answer Display</label>
                        <div className="flex items-center gap-4 bg-background border border-border rounded-lg px-4 py-2.5">
                            <label className="flex items-center gap-2 text-sm cursor-pointer select-none">
                                <input 
                                    type="checkbox" 
                                    checked={includeAnswers} 
                                    onChange={(e) => setIncludeAnswers(e.target.checked)}
                                    className="w-4 h-4 rounded text-primary focus:ring-primary border-slate-700 bg-slate-800"
                                />
                                Show Answers integrated
                            </label>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-wider text-slate-500">Text Size</label>
                        <div className="flex items-center gap-2">
                            {(['sm', 'base', 'lg', 'xl'] as FontSize[]).map(size => (
                                <button
                                    key={size}
                                    onClick={() => setFontSize(size)}
                                    className={`flex-1 py-2 px-1 text-xs font-bold rounded-lg border transition-all ${fontSize === size ? 'bg-primary border-primary text-white' : 'bg-background border-border text-slate-500 hover:border-slate-500'}`}
                                >
                                    {size.toUpperCase()}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Preview Container */}
            {!content && !isGenerating ? (
                <div className="bg-card/30 border-2 border-dashed border-border rounded-[2rem] p-20 text-center animate-fade-in print:hidden">
                    <h3 className="text-3xl font-extrabold mb-4">Ready to Study Integrated?</h3>
                    <p className="text-slate-400 max-w-lg mx-auto mb-10 text-lg leading-relaxed">
                        In this mode, each question is followed immediately by its answer. Great for learning as you go or listening to the full session with AI voice.
                    </p>
                    <button
                        onClick={generateQuickSet}
                        className="bg-primary hover:bg-primary/90 text-white font-extrabold py-4 px-12 rounded-2xl shadow-xl shadow-primary/20 transition-all hover:scale-105"
                    >
                        Generate Study Set
                    </button>
                </div>
            ) : (
                <div className={`animate-fade-in bg-card p-12 md:p-20 rounded-[2.5rem] shadow-2xl border border-border min-h-screen relative overflow-hidden print:p-0 print:shadow-none print:border-none print:bg-white print:text-black print:rounded-none ${getFontSizeClass()}`}>
                    {isGenerating && !content ? (
                        <div className="flex flex-col items-center justify-center py-32">
                            <Loader text={`Constructing your integrated study set...`} />
                        </div>
                    ) : (
                        <div className="prose prose-lg dark:prose-invert max-w-none print:prose-neutral">
                            <div className="mb-12 text-center border-b border-border/50 pb-12 print:border-black/20">
                                <h1 className="text-4xl font-black mb-4 print:text-black">
                                    {title}
                                </h1>
                                <p className="text-slate-400 print:text-gray-600 font-bold">
                                    Integrated Study Materials • {selectedCount} Questions • {new Date().toLocaleDateString()}
                                </p>
                            </div>

                            <div className="whitespace-pre-wrap leading-relaxed text-slate-200 print:text-black print:hidden">
                                {processedContent}
                            </div>

                            {/* Hidden printable section for StudyHub as well */}
                            <div className="hidden print:block text-black font-serif leading-relaxed">
                                <div dangerouslySetInnerHTML={{ __html: printableContent }} />
                            </div>

                            {isGenerating && (
                                <div className="mt-12 flex items-center justify-center gap-4 text-primary animate-pulse py-8 bg-primary/5 rounded-2xl border border-primary/10 print:hidden">
                                    <svg className="animate-spin h-6 w-6" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                    <span className="font-black text-lg">AI is streaming questions...</span>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            )}

            <style dangerouslySetInnerHTML={{ __html: `
                @media print {
                    @page { margin: 2cm; size: A4 portrait; }
                    html, body { background: white !important; color: black !important; }
                    .print\\:hidden, header, footer, .control-panel, aside, .sidebar { display: none !important; }
                    .answer-block {
                        background: #f9fafb !important;
                        padding: 1.5rem !important;
                        border-left: 4px solid black !important;
                        margin: 1.5rem 0 !important;
                        break-inside: avoid !important;
                    }
                }
            `}} />
        </div>
    );
};

import React, { useState, useRef, useMemo } from 'react';
import { generatePracticeExamStream, generateSpeech } from '../services/geminiService';
import { DocumentDownloadIcon } from './icons/DocumentDownloadIcon';
import { XIcon } from './icons/XIcon';
import { SparklesIcon } from './icons/SparklesIcon';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';
import { DownloadIcon } from './icons/DownloadIcon';
import { Loader } from './Loader';

declare const saveAs: (blob: Blob, filename: string) => void;

interface PracticeExamDownloaderProps {
    onClose: () => void;
}

export const PracticeExamDownloader: React.FC<PracticeExamDownloaderProps> = ({ onClose }) => {
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState('');
    const [examContent, setExamContent] = useState('');
    const [includeAnswers, setIncludeAnswers] = useState(true);
    const examContentRef = useRef('');

    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    const handleGenerate = async () => {
        stopSpeaking();
        setIsGenerating(true);
        setError('');
        setExamContent('');
        examContentRef.current = '';

        try {
            await generatePracticeExamStream((chunk) => {
                examContentRef.current += chunk;
                setExamContent(examContentRef.current);
            }, 10); // Generating 10 questions for performance stability
        } catch (err) {
            setError("Generation encountered an error. Please check your connection.");
        } finally {
            setIsGenerating(false);
        }
    };

    const stopSpeaking = () => {
        if (audioSourceRef.current) {
            try { audioSourceRef.current.stop(); } catch (e) {}
            audioSourceRef.current = null;
        }
        setIsSpeaking(false);
        setIsGeneratingAudio(false);
    };

    const handleReadAloud = async () => {
        if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
        if (!examContent) return;

        if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
            await window.aistudio.openSelectKey();
        }

        setIsGeneratingAudio(true);
        try {
            if (!audioContextRef.current) audioContextRef.current = new AudioContext();
            const textToRead = examContent.substring(0, 2000).replace(/\[ANSWER_(START|END)\]/g, '');
            const buffer = await generateSpeech(textToRead, 'Puck', audioContextRef.current);
            setIsGeneratingAudio(false);
            setIsSpeaking(true);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => setIsSpeaking(false);
            audioSourceRef.current = source;
            source.start();
        } catch (err) {
            setIsGeneratingAudio(false);
            setIsSpeaking(false);
            alert("Audio generation failed. Please try a shorter selection.");
        }
    };

    const handleExportMarkdown = () => {
        if (!examContent) return;
        let exportText = examContent;
        if (!includeAnswers) {
            exportText = exportText.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n*(Answers hidden)*\n');
        } else {
            exportText = exportText.replace(/\[ANSWER_START\]/g, '\n--- SOLUTION ---\n').replace(/\[ANSWER_END\]/g, '\n-----------------\n');
        }
        const blob = new Blob([exportText], { type: 'text/markdown;charset=utf-8' });
        saveAs(blob, "PL-300_Practice_Exam.md");
    };

    const processedHtml = useMemo(() => {
        let text = examContent;
        if (!text) return '';

        // Sanitize for basic HTML conversion
        text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

        // Simple Markdown-ish conversion
        text = text.replace(/^### (.*$)/gim, '<h3 class="text-lg font-black mt-6 mb-2 text-primary">$1</h3>');
        text = text.replace(/^## (.*$)/gim, '<h2 class="text-xl font-black mt-8 mb-4 border-b border-border pb-2">$1</h2>');
        text = text.replace(/^# (.*$)/gim, '<h1 class="text-2xl font-black mt-10 mb-6">$1</h1>');
        text = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
        text = text.replace(/\*(.*?)\*/g, '<em>$1</em>');
        text = text.replace(/\n/g, '<br />');

        if (!includeAnswers) {
            text = text.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '<div class="p-4 bg-slate-800/50 border border-dashed border-border rounded-xl my-4 text-slate-500 font-bold text-center">*(Answers hidden for testing)*</div>');
        } else {
            text = text.replace(/\[ANSWER_START\]/g, '<div class="answer-box">')
                       .replace(/\[ANSWER_END\]/g, '</div>');
        }
        return text;
    }, [examContent, includeAnswers]);

    return (
        <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static" role="dialog">
            <div className="bg-card rounded-[2.5rem] shadow-2xl w-full max-w-5xl h-[90vh] overflow-hidden flex flex-col animate-pop-in print:hidden border border-border/50">
                <div className="p-8 border-b border-border flex justify-between items-center bg-card/50 backdrop-blur-md sticky top-0 z-20">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-primary/10 rounded-2xl">
                           <DocumentDownloadIcon className="text-primary w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black tracking-tight">Exam Generator</h2>
                            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Mixed item types • Professional Assessment</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-border rounded-full transition-all text-slate-400 hover:text-white">
                        <XIcon />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-10 space-y-8 custom-scrollbar bg-background/30">
                    {error && <div className="p-4 bg-danger/10 border border-danger text-danger rounded-xl text-center font-bold">{error}</div>}

                    {!examContent && !isGenerating ? (
                        <div className="py-24 text-center">
                            <div className="w-20 h-20 bg-primary/10 rounded-3xl flex items-center justify-center mx-auto mb-8 animate-bounce">
                                <SparklesIcon className="w-10 h-10 text-primary" />
                            </div>
                            <h3 className="text-4xl font-black mb-4">Ready for the Exam?</h3>
                            <p className="text-slate-400 max-w-md mx-auto mb-10 text-lg leading-relaxed">
                                Generate a printable session including <b>Case Studies</b>, <b>Build Lists</b>, and <b>Multi-Select</b> items.
                            </p>
                            <button onClick={handleGenerate} className="bg-primary hover:bg-primary/90 text-white font-black py-5 px-14 rounded-2xl shadow-2xl shadow-primary/30 transition-all active:scale-95 text-xl flex items-center gap-3 mx-auto">
                                <SparklesIcon className="w-6 h-6" />
                                Generate Exam Content
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-8 max-w-4xl mx-auto">
                            <div className="sticky top-0 z-10 flex flex-wrap items-center justify-between gap-6 p-5 bg-card/90 backdrop-blur-2xl border border-border rounded-2xl shadow-2xl">
                                <label className="flex items-center gap-3 text-sm font-black cursor-pointer uppercase tracking-tighter hover:text-primary transition-colors">
                                    <input type="checkbox" checked={includeAnswers} onChange={e => setIncludeAnswers(e.target.checked)} className="w-6 h-6 rounded-lg text-primary bg-slate-900 border-border focus:ring-primary" />
                                    Include Answer Keys
                                </label>
                                <div className="flex flex-wrap gap-2">
                                    <button onClick={handleReadAloud} className={`px-5 py-3 rounded-xl font-bold flex items-center gap-2 transition-all ${isSpeaking || isGeneratingAudio ? 'bg-danger text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}>
                                        {isSpeaking || isGeneratingAudio ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                                        {isSpeaking ? 'Stop' : 'Read Out'}
                                    </button>
                                    <button onClick={handleExportMarkdown} className="bg-slate-800 text-slate-300 px-5 py-3 rounded-xl font-bold hover:bg-slate-700 transition-all flex items-center gap-2">
                                        <DownloadIcon className="w-4 h-4" />
                                        MD
                                    </button>
                                    <button onClick={() => window.print()} className="bg-success text-white px-8 py-3 rounded-xl font-black hover:bg-success/90 transition-all shadow-lg shadow-success/20 flex items-center gap-2">
                                        <DocumentDownloadIcon className="w-4 h-4" />
                                        Save as PDF
                                    </button>
                                </div>
                            </div>

                            <div 
                                className="bg-card p-10 md:p-16 rounded-[2rem] border border-border shadow-inner font-serif leading-relaxed text-slate-200"
                                dangerouslySetInnerHTML={{ __html: processedHtml }} 
                            />

                            {isGenerating && (
                                <div className="p-8 bg-primary/5 border-2 border-dashed border-primary/20 rounded-3xl text-center">
                                   <Loader text="AI is formulating complex item scenarios..." />
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="p-6 bg-card border-t border-border flex justify-center">
                    <button onClick={onClose} className="text-slate-500 hover:text-slate-300 font-black text-sm uppercase tracking-widest transition-colors">Return to Dashboard</button>
                </div>
            </div>

            {/* Print-only View */}
            <div className="hidden print:block w-full text-black bg-white p-10 font-serif">
                <div className="text-center border-b-4 border-black pb-8 mb-12">
                    <h1 className="text-4xl font-black uppercase mb-2">Microsoft PL-300 Power BI</h1>
                    <h2 className="text-xl font-bold text-gray-700">Practice Assessment • Official Simulation</h2>
                    <p className="mt-2 font-mono text-sm">Generated on: {new Date().toLocaleDateString()} • User ID: Assessment_Ready</p>
