import React, { useState, useRef, useMemo } from 'react';
import { generatePracticeExamStream, generateSpeech } from '../services/geminiService';
import { DocumentDownloadIcon } from './icons/DocumentDownloadIcon';
import { XIcon } from './icons/XIcon';
import { SparklesIcon } from './icons/SparklesIcon';
import { SpeakerIcon } from './icons/SpeakerIcon';
import { StopIcon } from './icons/StopIcon';
import { DownloadIcon } from './icons/DownloadIcon';
import { Loader } from './Loader';

declare const saveAs: (blob: Blob, filename: string) => void;

interface PracticeExamDownloaderProps {
    onClose: () => void;
}

export const PracticeExamDownloader: React.FC<PracticeExamDownloaderProps> = ({ onClose }) => {
    const [isGenerating, setIsGenerating] = useState(false);
    const [error, setError] = useState('');
    const [examContent, setExamContent] = useState('');
    const [includeAnswers, setIncludeAnswers] = useState(true);
    const examContentRef = useRef('');

    const [isSpeaking, setIsSpeaking] = useState(false);
    const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    const handleGenerate = async () => {
        stopSpeaking();
        setIsGenerating(true);
        setError('');
        setExamContent('');
        examContentRef.current = '';

        try {
            await generatePracticeExamStream((chunk) => {
                examContentRef.current += chunk;
                // Force state update to show streaming content
                setExamContent(examContentRef.current);
            }, 10); 
        } catch (err) {
            setError("Generation encountered an error. Please check your connection and API key.");
        } finally {
            setIsGenerating(false);
        }
    };

    const stopSpeaking = () => {
        if (audioSourceRef.current) {
            try { audioSourceRef.current.stop(); } catch (e) {}
            audioSourceRef.current = null;
        }
        setIsSpeaking(false);
        setIsGeneratingAudio(false);
    };

    const handleReadAloud = async () => {
        if (isSpeaking || isGeneratingAudio) { stopSpeaking(); return; }
        if (!examContent) return;

        if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
            await window.aistudio.openSelectKey();
        }

        setIsGeneratingAudio(true);
        try {
            if (!audioContextRef.current) audioContextRef.current = new AudioContext();
            const textToRead = examContent.substring(0, 2000).replace(/\[ANSWER_(START|END)\]/g, '');
            const buffer = await generateSpeech(textToRead, 'Puck', audioContextRef.current);
            setIsGeneratingAudio(false);
            setIsSpeaking(true);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => setIsSpeaking(false);
            audioSourceRef.current = source;
            source.start();
        } catch (err) {
            setIsGeneratingAudio(false);
            setIsSpeaking(false);
            alert("Audio generation failed.");
        }
    };

    const downloadFile = (content: string, type: string, extension: string) => {
        const blob = new Blob([content], { type });
        saveAs(blob, `PL-300_Exam_${new Date().getTime()}.${extension}`);
    };

    const handleDownloadTxt = () => {
        let text = examContent.replace(/\[ANSWER_START\]/g, '\n--- ANSWER ---\n').replace(/\[ANSWER_END\]/g, '\n---------------\n');
        if (!includeAnswers) {
            text = examContent.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '\n[Answer Hidden]\n');
        }
        downloadFile(text, 'text/plain;charset=utf-8', 'txt');
    };

    const handleDownloadHtml = () => {
        const htmlContent = `
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="UTF-8">
                <title>PL-300 Practice Exam</title>
                <style>
                    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 40px auto; padding: 20px; color: #333; }
                    h1 { text-align: center; border-bottom: 2px solid #333; padding-bottom: 10px; }
                    .answer-box { background: #f0f4f8; border-left: 5px solid #2563eb; padding: 15px; margin: 15px 0; border-radius: 4px; }
                    .hidden-answer { color: #999; font-style: italic; border: 1px dashed #ccc; padding: 10px; }
                </style>
            </head>
            <body>
                <h1>PL-300 Practice Exam</h1>
                ${processedHtml}
            </body>
            </html>
        `;
        downloadFile(htmlContent, 'text/html;charset=utf-8', 'html');
    };

    const processedHtml = useMemo(() => {
        let text = examContent;
        if (!text) return '';

        // Basic Markdown Conversion
        let html = text
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/^### (.*$)/gim, '<h3 style="color: #2563eb; margin-top: 20px;">$1</h3>')
            .replace(/^## (.*$)/gim, '<h2 style="border-bottom: 1px solid #ccc; padding-bottom: 5px; margin-top: 30px;">$1</h2>')
            .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
            .replace(/\n/g, '<br />');

        if (!includeAnswers) {
            html = html.replace(/\[ANSWER_START\][\s\S]*?\[ANSWER_END\]/g, '<div class="hidden-answer">*(Answer key omitted)*</div>');
        } else {
            html = html.replace(/\[ANSWER_START\]/g, '<div class="answer-box">')
                       .replace(/\[ANSWER_END\]/g, '</div>');
        }
        return html;
    }, [examContent, includeAnswers]);

    return (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 p-4 print:p-0 print:bg-white print:static" role="dialog">
            <div className="bg-card rounded-[2rem] shadow-2xl w-full max-w-5xl h-[90vh] overflow-hidden flex flex-col animate-pop-in print:hidden">
                <div className="p-6 border-b border-border flex justify-between items-center bg-card/80 backdrop-blur-md">
                    <div className="flex items-center gap-4">
                        <DocumentDownloadIcon className="text-primary w-8 h-8" />
                        <div>
                            <h2 className="text-xl font-black">Exam Generator</h2>
                            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Generate & Export Practice Items</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-full transition-all text-slate-400 hover:text-white">
                        <XIcon />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 md:p-10 space-y-6 bg-background/50 custom-scrollbar">
                    {error && <div className="p-4 bg-danger/10 border border-danger/20 text-danger rounded-xl text-sm font-bold">{error}</div>}

                    {!examContent && !isGenerating ? (
                        <div className="py-20 text-center space-y-6">
                            <SparklesIcon className="w-12 h-12 text-primary/40 mx-auto animate-pulse" />
                            <h3 className="text-3xl font-black">Build Your Custom Exam</h3>
                            <p className="text-slate-400 max-w-md mx-auto font-medium">Generate 10 professional-grade items with solutions to study offline.</p>
                            <button onClick={handleGenerate} className="bg-primary hover:bg-primary/90 text-white font-black py-4 px-10 rounded-2xl shadow-xl transition-all hover:scale-105 active:scale-95">
                                Generate Now
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6">
                            <div className="sticky top-0 z-10 p-4 bg-card/95 backdrop-blur-md border border-border rounded-2xl shadow-xl flex flex-wrap items-center justify-between gap-4">
                                <label className="flex items-center gap-3 text-xs font-black cursor-pointer uppercase">
                                    <input type="checkbox" checked={includeAnswers} onChange={e => setIncludeAnswers(e.target.checked)} className="w-5 h-5 rounded bg-slate-900 border-border" />
                                    Include Answers
                                </label>
                                <div className="flex flex-wrap gap-2">
                                    <button onClick={handleReadAloud} className="bg-slate-800 text-slate-300 px-4 py-2 rounded-xl text-xs font-bold hover:bg-slate-700 flex items-center gap-2 transition-all">
                                        {isSpeaking ? <StopIcon className="w-4 h-4" /> : <SpeakerIcon className="w-4 h-4" />}
                                        {isSpeaking ? 'Stop' : 'Listen'}
                                    </button>
                                    <button onClick={handleDownloadTxt} className="bg-slate-800 text-slate-300 px-4 py-2 rounded-xl text-xs font-bold hover:bg-slate-700 flex items-center gap-2 transition-all">
                                        <DownloadIcon className="w-4 h-4" /> TXT
                                    </button>
                                    <button onClick={handleDownloadHtml} className="bg-slate-800 text-slate-300 px-4 py-2 rounded-xl text-xs font-bold hover:bg-slate-700 flex items-center gap-2 transition-all">
                                        <DownloadIcon className="w-4 h-4" /> HTML
                                    </button>
                                    <button onClick={() => window.print()} className="bg-success text-white px-6 py-2 rounded-xl text-xs font-black hover:bg-success/90 transition-all shadow-lg flex items-center gap-2">
                                        <DocumentDownloadIcon className="w-4 h-4" /> Print / PDF
                                    </button>
                                </div>
                            </div>

                            <div 
                                className="bg-card p-8 md:p-12 rounded-3xl border border-border font-serif leading-relaxed text-slate-200 shadow-inner min-h-[400px]"
                                dangerouslySetInnerHTML={{ __html: processedHtml || (isGenerating ? '<p class="animate-pulse">Consulting AI for exam content...</p>' : '') }} 
                            />

                            {isGenerating && (
                                <div className="flex justify-center p-4">
                                   <Loader text="AI is formulating the next question..." />
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="p-4 bg-card/80 border-t border-border flex justify-center">
                    <button onClick={onClose} className="text-slate-500 hover:text-slate-300 font-bold text-xs uppercase tracking-widest transition-colors">Close Generator</button>
                </div>
            </div>

            {/* Hidden Print Container */}
            <div className="hidden print:block w-full text-black bg-white p-10 font-serif">
                <h1 className="text-3xl font-bold mb-4 border-b-2 border-black pb-2">PL-300 Practice Exam</h1>
                <p className="text-sm mb-10 text-gray-600 italic">Official generated practice session - {new Date().toLocaleDateString()}</p>
                <div 
                    className="print-output text-[12pt] leading-relaxed"
                    dangerouslySetInnerHTML={{ __html: processedHtml }} 
                />
            </div>

            <style dangerouslySetInnerHTML={{ __html: `
                .answer-box {
                    background: rgba(37, 99, 235, 0.08);
                    border-left: 4px solid #4f46e5;
                    padding: 1.5rem;
                    margin: 1.5rem 0;
                    border-radius: 0.75rem;
                    color: #e2e8f0;
                }
                .hidden-answer {
                    padding: 1rem;
                    border: 1px dashed #475569;
                    color: #94a3b8;
                    font-style: italic;
                    text-align: center;
                    margin: 1rem 0;
                }
                @media print {
                    @page { margin: 2cm; size: A4 portrait; }
                    body { background: white !important; color: black !important; }
                    .print\\:hidden { display: none !important; }
                    .answer-box { 
                        background: #f1f5f9 !important; 
