        saveAs(blob, `PL300_StudyHub_${selectedCount}Q_${new Date().getTime()}.txt`);
    };

    const getFontSizeClass = () => {
        switch (fontSize) {
            case 'sm': return 'text-sm';
            case 'lg': return 'text-lg';
            case 'xl': return 'text-xl';
            default: return 'text-base';
        }
    };

    const processedContent = useMemo(() => {
        return content.replace(/\[ANSWER_START\]/g, '\n<div class="bg-primary/5 p-4 rounded-lg my-4 border-l-4 border-primary">')
                      .replace(/\[ANSWER_END\]/g, '</div>\n');
    }, [content]);

    return (
        <div className="space-y-8 animate-fade-in max-w-5xl mx-auto pb-20">
            <div className="bg-card p-6 rounded-2xl shadow-xl border border-border flex flex-col gap-6">
                <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                    <div className="flex items-center gap-4">
                        <button onClick={onBackToDashboard} className="p-2.5 hover:bg-border rounded-xl transition-all">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                        </button>
                        <div>
                            <h2 className="text-2xl font-bold">Study Hub</h2>
                            <p className="text-sm text-slate-400">Integrated Q&A Session</p>
                        </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-4">
                        <button onClick={generateQuickSet} disabled={isGenerating} className="bg-primary hover:bg-primary/90 text-white font-bold py-3 px-8 rounded-xl shadow-lg flex items-center gap-2 transition-all">
                            <SparklesIcon className="w-5 h-5" />
                            {isGenerating ? 'Generating...' : 'Start Session'}
                        </button>

                        {content && !isGenerating && (
                            <button onClick={handleDownloadTxt} className="bg-success hover:bg-success/90 text-white font-extrabold py-3 px-8 rounded-xl flex items-center gap-2 transition-all shadow-lg shadow-success/20">
                                <DownloadIcon className="w-5 h-5" />
                                Download (.txt)
                            </button>
                        )}
                    </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 pt-6 border-t border-border/50">
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase text-slate-500">Number of Questions</label>
                        <select value={selectedCount} onChange={(e) => setSelectedCount(Number(e.target.value) as QuestionCount)} className="w-full bg-background border border-border rounded-lg px-4 py-2 text-sm">
                            <option value={25}>25 Questions</option>
                            <option value={50}>50 Questions</option>
                            <option value={100}>100 Questions</option>
                        </select>
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase text-slate-500">Text Display Size</label>
                        <div className="flex gap-2">
                            {(['sm', 'base', 'lg', 'xl'] as FontSize[]).map(size => (
                                <button key={size} onClick={() => setFontSize(size)} className={`flex-1 py-2 text-xs font-bold rounded-lg border ${fontSize === size ? 'bg-primary border-primary text-white' : 'bg-background border-border text-slate-500'}`}>
                                    {size.toUpperCase()}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {!content && !isGenerating ? (
                <div className="bg-card/30 border-2 border-dashed border-border rounded-[2rem] p-20 text-center">
                    <h3 className="text-3xl font-extrabold mb-4">Study Ready?</h3>
                    <p className="text-slate-400 mb-8">Generate an integrated Q&A set to study in the browser or download as a text file.</p>
                    <button onClick={generateQuickSet} className="bg-primary py-4 px-12 rounded-2xl shadow-xl font-bold text-white">Generate Study Set</button>
                </div>
            ) : (
                <div className={`animate-fade-in bg-card p-12 md:p-20 rounded-[2.5rem] shadow-2xl border border-border min-h-screen ${getFontSizeClass()}`}>
                    {isGenerating && !content ? (
                        <Loader text="AI is streaming content..." />
                    ) : (
                        <div>
                             <h1 className="text-3xl font-black mb-8 border-b border-border pb-6">{title}</h1>
                             <div className="whitespace-pre-wrap leading-relaxed text-slate-200" dangerouslySetInnerHTML={{ __html: processedContent }} />
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { generateStudyGuideStream } from '../services/geminiService';
import type { ProgressData, QuestionCategory, StudyGuideLength } from '../types';
import { Loader } from './Loader';
import { SparklesIcon } from './icons/SparklesIcon';
import { DownloadIcon } from './icons/DownloadIcon';

declare const saveAs: (blob: Blob, filename: string) => void;

interface StudyGuideProps {
  categoryStats: ProgressData['categoryStats'];
}

const categories: (QuestionCategory | 'All Topics')[] = [
    'Prepare the data',
    'Model the data',
    'Visualize and analyze the data',
    'Deploy and maintain assets',
    'All Topics'
];

export const StudyGuide: React.FC<StudyGuideProps> = ({ categoryStats }) => {
    const [isGenerating, setIsGenerating] = useState(false);
    const [guideContent, setGuideContent] = useState('');
    const [showModal, setShowModal] = useState(false);
    const [error, setError] = useState('');

    const [selectedCategory, setSelectedCategory] = useState<QuestionCategory | 'All Topics'>('Prepare the data');
    const [selectedLength, setSelectedLength] = useState<StudyGuideLength>('Concise');

    const weakestCategory = useMemo(() => {
        let weakest: QuestionCategory | null = null;
        let lowestScore = 101; 

        (Object.keys(categoryStats) as QuestionCategory[]).forEach(key => {
            const stats = categoryStats[key];
            if (stats.total >= 3) { 
                const score = (stats.correct / stats.total) * 100;
                if (score < lowestScore) {
                    lowestScore = score;
                    weakest = key;
                }
            }
        });
        return weakest;
    }, [categoryStats]);

    useEffect(() => {
        if (weakestCategory) {
            setSelectedCategory(weakestCategory);
        }
    }, [weakestCategory]);

    const handleGenerate = async () => {
        setIsGenerating(true);
        setError('');
        setGuideContent('');
        setShowModal(true); 

        const categoryToGenerate = selectedCategory === 'All Topics' ? 'All' : selectedCategory;

        try {
            await generateStudyGuideStream(categoryToGenerate, selectedLength, (chunk: string) => {
                setGuideContent(prev => prev + chunk);
            });
        } catch (err) {
            setError('An error occurred during generation.');
        } finally {
            setIsGenerating(false);
        }
    };

    const handleDownload = () => {
        if (!guideContent) return;

        const filename = `PL300_StudyGuide_${selectedCategory.substring(0, 15)}_${new Date().getTime()}.txt`;
        const blob = new Blob([guideContent], { type: 'text/plain;charset=utf-8' });
        saveAs(blob, filename);
    };

    return (
        <>
            <div className="bg-card p-6 rounded-lg shadow-lg flex flex-col min-h-[220px]">
                <div className="flex items-center gap-4 mb-4">
                     <div className="p-3 bg-indigo-500/10 rounded-full text-indigo-400">
                        <SparklesIcon className="w-6 h-6"/>
                    </div>
                    <h3 className="text-xl font-bold">AI Study Guide</h3>
                </div>

                <p className="text-slate-300 mb-4 text-sm">Generate a customized technical overview for your study session.</p>

                <div className="mt-auto space-y-3">
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block text-slate-300 font-semibold mb-1 text-xs">Topic</label>
                            <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value as any)} className="w-full bg-input border border-border rounded-md p-2 text-sm">
                                {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                            </select>
                        </div>
                        <div>
                             <label className="block text-slate-300 font-semibold mb-1 text-xs">Detail Level</label>
                            <select value={selectedLength} onChange={(e) => setSelectedLength(e.target.value as any)} className="w-full bg-input border border-border rounded-md p-2 text-sm">
                                <option value="Concise">Concise</option>
                                <option value="Detailed">Detailed</option>
                                <option value="Comprehensive">Comprehensive</option>
                            </select>
                        </div>
                    </div>

                    <button onClick={handleGenerate} disabled={isGenerating} className="w-full bg-indigo-500 hover:bg-indigo-600 text-white font-bold py-3 px-4 rounded-md transition disabled:bg-slate-500 flex items-center justify-center gap-2">
                        {isGenerating ? 'Generating...' : 'Generate Study Guide'}
                    </button>
                </div>
            </div>

            {showModal && (
                <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4" onClick={() => setShowModal(false)}>
                    <div className="bg-card rounded-lg shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col" onClick={e => e.stopPropagation()}>
                        <div className="p-6 border-b border-border flex justify-between items-center">
                            <h2 className="text-2xl font-bold">Study Guide Preview</h2>
                            <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-white text-3xl">&times;</button>
                        </div>
                        <div className="p-6 overflow-y-auto">
                            {isGenerating && !guideContent && <Loader text="Generating content..." />}
                            {error && <p className="text-danger">{error}</p>}
                            {guideContent && <div className="prose prose-sm prose-invert max-w-none whitespace-pre-wrap leading-relaxed text-slate-200">{guideContent}</div>}
                        </div>
                         <div className="p-4 border-t border-border flex justify-between items-center">
                            <button onClick={handleDownload} disabled={!guideContent || isGenerating} className="flex items-center gap-2 bg-success text-white font-bold py-2 px-6 rounded-lg disabled:opacity-50 shadow-lg">
                                <DownloadIcon />
                                Download (.txt)
                            </button>
                            <button onClick={() => setShowModal(false)} className="bg-slate-600 hover:bg-slate-700 text-white font-bold py-2 px-6 rounded-lg">Close</button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
};

import React, { useState, useMemo } from 'react';
import type { ProgressData, Difficulty, TimerSetting, QuizMode, QuestionCategoryFilter, ExamResult, Question } from '../types';
