                            <button
                                onClick={() => setActiveTab('analytics')}
                                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold transition-all ${activeTab === 'analytics' ? 'bg-primary text-primary-foreground shadow-lg' : 'text-slate-500 hover:bg-border'}`}
                            >
                                <TrendingUp className="w-5 h-5" />
                                Analytics & Resources
