                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
                        {activeTab === 'practice' ? (
                            <>
                                {/* Left Side: Quiz Settings */}
                                <div className="lg:col-span-7 space-y-8">
                                    <div className="bg-card p-8 rounded-3xl shadow-xl border border-border space-y-6">
                                        <div className="flex justify-between items-center">
                                            <h3 className="text-2xl font-black tracking-tight flex items-center gap-2"><Settings className="w-6 h-6 text-primary" /> Practice Session</h3>
