                                                </select>
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-sm font-bold text-slate-500 uppercase">Category</label>
                                                <select value={category} onChange={(e) => setCategory(e.target.value as QuestionCategoryFilter)} className="w-full bg-input border border-border rounded-xl p-3 font-semibold">
                                                    <option value="All">All Categories</option>
                                                    <option value="Prepare the data">Prepare the data</option>
                                                    <option value="Model the data">Model the data</option>
                                                    <option value="Visualize and analyze the data">Visualize and analyze the data</option>
                                                    <option value="Deploy and maintain assets">Deploy and maintain assets</option>
                                                </select>
                                            </div>
                                        </div>

                                        <div className="space-y-2">
                                            <label className="text-sm font-bold text-slate-500 uppercase">Timer (minutes)</label>
                                            <select value={timer} onChange={(e) => setTimer(Number(e.target.value) as TimerSetting)} className="w-full bg-input border border-border rounded-xl p-3 font-semibold">
