                                        </div>
                                    </div>

                                    <StudyGuide categoryStats={progressData.categoryStats} />
                                </div>

                                <div className="lg:col-span-4 space-y-6">
                                    <ExamReadinessGauge score={readinessScore} theme={theme} />

                                    <div className="bg-gradient-to-br from-indigo-600 to-primary p-6 rounded-3xl shadow-xl text-white">
                                        <div className="flex items-center gap-3 mb-4">
                                            <SparklesIcon className="w-7 h-7 text-white" />
                                            <h3 className="text-xl font-black">Study Hub</h3>
                                        </div>
                                        <p className="text-sm text-white/80 mb-6 font-medium">Access integrated, printable study sets ready for offline review.</p>
                                        <button onClick={onViewStudyHub} className="w-full bg-white text-indigo-600 hover:bg-indigo-50 font-black py-4 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2">
                                            Enter Hub
                                            <BookOpen className="w-4 h-4" />
                                        </button>
                                    </div>

                                    <div className="flex justify-center pt-8">
                                        <button onClick={onResetProgress} className="flex items-center gap-2 text-xs font-bold text-slate-500 hover:text-danger transition-colors uppercase tracking-widest">
                                            <TrashIcon className="w-4 h-4" /> Reset Progress
                                        </button>
                                    </div>
                                </div>
                            </>
                        )}
                    </div>
                </>
            )}
        </div>
    );
};
